const a={"les-n3-u08-01":{pedagogical_framework:{what:{summary:"Kewajaran Logis, Kepastian & Hakikat Fenomena (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜こそ, 〜さえ, 〜なんか / 〜なんて / 〜など, 〜はもちろん, 〜ばかりか〜(も) dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜こそ dan 〜さえ dalam percakapan kerja wajar.",targetPatterns:["〜こそ (justru ... / (inilah) yang sesungguhnya ...)","〜さえ (bahkan ... / ... saja pun)","〜なんか / 〜なんて / 〜など (hal seperti ... / ... dan sejenisnya)","〜はもちろん (... sudah pasti / tidak hanya ... tapi juga ...)","〜ばかりか〜(も) (bukan hanya ... tapi juga ...)"],coreVocabSample:["よわめる","あいさつ","あきる","あける","あらわす","いち","うけとる","うごかす"]},sensei_context:{sceneIntro:"Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜こそ dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kewajaran Logis, Kepastian & Hakikat Fenomena",etiquette:"Gunakan 〜wake da saat memahami penjelasan teknis lawan bicara sebagai bentuk sinyal pemahaman mendalam.",taboos:"Jangan gunakan 〜mono da untuk menggurui atasan mengenai etika dasar."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜こそ",moraNote:"Tekankan intonasi datar stabil pada kata penjelas wa-ke-da.",soundTip:"Ucapkan 〜こそ dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜こそ",caseScenario:"Menggunakan 〜こそ tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜こそ.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜こそ sesuai kaidah.",explanation:"Kaidah koneksi 〜こそ: N + こそ / 〜てこそ."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kewajaran Logis, Kepastian & Hakikat Fenomena (Fondasi & Pemahaman Pola)",setting:"Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola 〜こそ."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、弱めるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、弱めるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, yowameru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai melemahkan, mengecilkan (api/suara/kekuatan), mengurangi tekanan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ 今こそ行動するときだ！。",furigana:"はい、Kenjiさん！ 今こそ行動するときだ！。",romaji:"Hai, Kenji-san! こそ de susumete imasu.",idText:"Ya, Kenji! Justru sekaranglah saatnya bertindak!."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。疲れて、歩くさえできなかった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。疲れて、歩くさえできなかった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Lelah sekali, bahkan berjalan saja tidak bisa.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02429",word:"弱める",reading:"よわめる",romaji:"yowameru",meaning:"melemahkan, mengecilkan (api/suara/kekuatan), mengurangi tekanan",pos:"verb-ru",nuance:"Verba transitif yang berarti sengaja mengecilkan besar api kompor, volume, daya tekan, atau mengurangi intensitas suatu kekuatan (contoh: 火を弱める mengecilkan api kompor, 勢いを弱める memperlambat laju). Lawan katanya adalah 強める (tsuyomeru).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"弱める【よわめる】を 確認【かくにん】します。",furigana:"弱めるを 確認します。",romaji:"yowameru o kakunin shimasu.",idText:"Memeriksa melemahkan, mengecilkan (api/suara/kekuatan), mengurangi tekanan."}},{id:"vg-n3-02432",word:"挨拶",reading:"あいさつ",romaji:"aisatsu",meaning:"salam; sapaan",pos:"verb-suru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"挨拶【あいさつ】を 確認【かくにん】します。",furigana:"挨拶を 確認します。",romaji:"aisatsu o kakunin shimasu.",idText:"Memeriksa salam; sapaan."}},{id:"vg-n3-02436",word:"飽きる",reading:"あきる",romaji:"akiru",meaning:"bosan; jenuh",pos:"verb-ru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"飽きる【あきる】を 確認【かくにん】します。",furigana:"飽きるを 確認します。",romaji:"akiru o kakunin shimasu.",idText:"Memeriksa bosan; jenuh."}},{id:"vg-n3-02437",word:"明ける",reading:"あける",romaji:"akeru",meaning:"fajar",pos:"verb-ru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"明ける【あける】を 確認【かくにん】します。",furigana:"明けるを 確認します。",romaji:"akeru o kakunin shimasu.",idText:"Memeriksa fajar."}},{id:"vg-n3-02440",word:"現す",reading:"あらわす",romaji:"arawasu",meaning:"menunjukkan",pos:"verb-u",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"現す【あらわす】を 確認【かくにん】します。",furigana:"現すを 確認します。",romaji:"arawasu o kakunin shimasu.",idText:"Memeriksa menunjukkan."}},{id:"vg-n3-02448",word:"位置",reading:"いち",romaji:"ichi",meaning:"place; situation",pos:"verb-suru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"位置【いち】を 確認【かくにん】します。",furigana:"位置を 確認します。",romaji:"ichi o kakunin shimasu.",idText:"Memeriksa place; situation."}},{id:"vg-n3-02452",word:"受け取る",reading:"うけとる",romaji:"uketoru",meaning:"menerima",pos:"verb-u",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"受け取る【うけとる】を 確認【かくにん】します。",furigana:"受け取るを 確認します。",romaji:"uketoru o kakunin shimasu.",idText:"Memeriksa menerima."}},{id:"vg-n3-02453",word:"動かす",reading:"うごかす",romaji:"ugokasu",meaning:"bergerak",pos:"verb-u",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"動かす【うごかす】を 確認【かくにん】します。",furigana:"動かすを 確認します。",romaji:"ugokasu o kakunin shimasu.",idText:"Memeriksa bergerak."}}],explanations:[{id:"exp-1",grammarId:"gn3-00039",title:"Pola: 〜こそ",formula:"N + こそ / 〜てこそ",meaning:"justru ... / (inilah) yang sesungguhnya ...",nuanceNotes:'〜こそ memberikan penekanan kuat: "justru ini", "inilah yang sesungguhnya". Memfokuskan perhatian pada hal tertentu.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜こそ",idText:"justru ... / (inilah) yang sesungguhnya ..."}],examples:[{jp:"今こそ行動するときだ！",romaji:"",idText:"Justru sekaranglah saatnya bertindak!"},{jp:"あなたこそ、私の理想の人です。",romaji:"",idText:"Justru kamulah orang yang ideal bagiku."}]},{id:"exp-2",grammarId:"gn3-00040",title:"Pola: 〜さえ",formula:"N + さえ / Vさえ",meaning:"bahkan ... / ... saja pun",nuanceNotes:'〜さえ memberikan penekanan pada contoh ekstrem: "bahkan ... saja pun". Sering menyiratkan keterkejutan atau kondisi paling minimum.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜さえ",idText:"bahkan ... / ... saja pun"}],examples:[{jp:"疲れて、歩くさえできなかった。",romaji:"",idText:"Lelah sekali, bahkan berjalan saja tidak bisa."},{jp:"彼は自分の名前さえ書けない。",romaji:"",idText:"Bahkan namanya sendiri saja tidak bisa dia tulis."}]},{id:"exp-3",grammarId:"gn3-00041",title:"Pola: 〜なんか / 〜なんて / 〜など",formula:"N/V + なんか / なんて / など",meaning:"hal seperti ... / ... dan sejenisnya",nuanceNotes:"〜なんか / なんて: informal, sering merendahkan atau mengejutkan. 〜など: formal, menyebutkan contoh-contoh. Ketiganya bisa menyatakan kejutan atau meremehkan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜なんか / 〜なんて / 〜など",idText:"hal seperti ... / ... dan sejenisnya"}],examples:[{jp:"そんなことなんてどうでもいい。",romaji:"",idText:"Hal seperti itu tidak penting."},{jp:"私なんかに無理だよ。",romaji:"",idText:"Orang seperti saya tidak bisa."},{jp:"リンゴなどの果物が好きです。",romaji:"",idText:"Saya suka buah-buahan seperti apel."}]},{id:"exp-4",grammarId:"gn3-00042",title:"Pola: 〜はもちろん",formula:"N + はもちろん + N/V + も",meaning:"... sudah pasti / tidak hanya ... tapi juga ...",nuanceNotes:"〜はもちろん menyatakan bahwa suatu hal sudah jelas, ditambah dengan hal lain yang mungkin lebih mengejutkan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜はもちろん",idText:"... sudah pasti / tidak hanya ... tapi juga ..."}],examples:[{jp:"日本語はもちろん、英語も話せます。",romaji:"",idText:"Sudah pasti bisa bahasa Jepang, bahkan bahasa Inggris juga bisa."},{jp:"子どもはもちろん、大人にも人気があります。",romaji:"",idText:"Sudah pasti populer di kalangan anak-anak, bahkan orang dewasa pun menyukainya."}]},{id:"exp-5",grammarId:"gn3-00043",title:"Pola: 〜ばかりか〜(も)",formula:"V/Adj plain / N + ばかりか + V/N + も",meaning:"bukan hanya ... tapi juga ...",nuanceNotes:"〜ばかりか〜も menyatakan bahwa tidak hanya hal pertama, tapi hal kedua yang bahkan lebih mengejutkan juga berlaku.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ばかりか〜(も)",idText:"bukan hanya ... tapi juga ..."}],examples:[{jp:"彼は英語ばかりかフランス語も話せる。",romaji:"",idText:"Bukan hanya bahasa Inggris, bahasa Prancis pun dia bisa."},{jp:"家族ばかりか友人も心配してくれた。",romaji:"",idText:"Bukan hanya keluarga, teman-teman pun ikut khawatir."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "弱める"?',sentencePrompt:'Makna kata "弱める" (よわめる) dalam situasi kerja ini adalah:',options:["melemahkan, mengecilkan (api/suara/kekuatan), mengurangi tekanan","salam; sapaan","bosan; jenuh","fajar"],correctAnswer:"melemahkan, mengecilkan (api/suara/kekuatan), mengurangi tekanan",explanation:'Makna yang tepat untuk "弱める" adalah "melemahkan, mengecilkan (api/suara/kekuatan), mengurangi tekanan".',diagnosticFeedback:{"salam; sapaan":'Salah: Pilihan "salam; sapaan" adalah makna dari kata "挨拶" (あいさつ), bukan arti kata "弱める".',"bosan; jenuh":'Salah: Pilihan "bosan; jenuh" adalah makna dari kata "飽きる" (あきる), bukan arti kata "弱める".',fajar:'Salah: Pilihan "fajar" adalah makna dari kata "明ける" (あける), bukan arti kata "弱める".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"今（　　）行動するときだ！",options:["こそ","さえ","なんか / 〜なんて / 〜など","っぽい"],correctAnswer:"こそ",explanation:'Pola 〜こそ bermakna "justru ... / (inilah) yang sesungguhnya ...". Kalimat lengkap: "今こそ行動するときだ！".',diagnosticFeedback:{さえ:'Salah: Pola "さえ" bermakna "bahkan ... / ... saja pun", yang tidak sesuai konteks kalimat ini.',"なんか / 〜なんて / 〜など":'Salah: Pola "なんか / 〜なんて / 〜など" bermakna "hal seperti ... / ... dan sejenisnya", yang tidak sesuai konteks kalimat ini.',っぽい:'Salah: Pola "っぽい" bermakna "keliatan seperti ... / tampak ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜こそ secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["あなたこそ、私の理想の人です。","あなたこそでした、私の理想の人です。","疲れて、歩くさえできなかった。","明日は晴れるでしょう。"],correctAnswer:"あなたこそ、私の理想の人です。",explanation:'Kalimat yang benar dan alami adalah "あなたこそ、私の理想の人です。" (Justru kamulah orang yang ideal bagiku.).',diagnosticFeedback:{"あなたこそでした、私の理想の人です。":"Jebakan Konjugasi: Pola 〜こそ membutuhkan aturan sambung (N + こそ / 〜てこそ), bukan bentuk ini.","疲れて、歩くさえできなかった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜さえ: bahkan ... / ... saja pun), bukan kaidah 〜こそ.","明日は晴れるでしょう。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜こそ secara tepat (justru ... / (inilah) yang sesungguhnya ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["疲れて 、 歩くさえできなかった 。","、 疲れて 歩くさえできなかった 。","疲れて 歩くさえできなかった 、 。","。 疲れて 、 歩くさえできなかった"],correctAnswer:"疲れて 、 歩くさえできなかった 。",explanation:'Susunan yang benar: "疲れて 、 歩くさえできなかった 。" (Lelah sekali, bahkan berjalan saja tidak bisa.).',diagnosticFeedback:{"、 疲れて 歩くさえできなかった 。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","疲れて 歩くさえできなかった 、 。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","。 疲れて 、 歩くさえできなかった":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["疲れて","、","歩くさえできなかった","。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.", saat Kenji menyampaikan arahan: 「なるほど。疲れて、歩くさえできなかった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜こそ dan 〜さえ dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜こそ!",modelAnswer:"はい、Kenjiさん！ 今こそ行動するときだ！。",modelAnswerId:"Ya, Kenji! Justru sekaranglah saatnya bertindak!.",culturalEtiquette:"Gunakan 〜wake da saat memahami penjelasan teknis lawan bicara sebagai bentuk sinyal pemahaman mendalam.",skillUnlocked:["Menguasai formulasi pola 〜こそ","Mampu menerapkan prinsip koordinasi komunikasi kerja Kewajaran Logis, Kepastian & Hakikat Fenomena"]},pocket_summary:{keyFormula:"〜こそ (justru ... / (inilah) yang sesungguhnya ...)",coreWords:["弱める【よわめる】 (melemahkan, mengecilkan (api/suara/kekuatan), mengurangi tekanan)","挨拶【あいさつ】 (salam; sapaan)","飽きる【あきる】 (bosan; jenuh)","明ける【あける】 (fajar)"],coreWarning:"Jangan gunakan 〜mono da untuk menggurui atasan mengenai etika dasar.",quickDialogue:"A: ブディさん、弱めるの 状況【じょうきょう】は どう... → B: はい、Kenjiさん！ 今こそ行動するときだ！。..."}},"les-n3-u08-02":{pedagogical_framework:{what:{summary:"Kewajaran Logis, Kepastian & Hakikat Fenomena (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ように言う / 頼む, 〜ことだ, 〜ことか, 〜ふりをする dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ように言う / 頼む dan 〜ことだ secara mandiri.",targetPatterns:["〜ように言う / 頼む (menyuruh agar ... / meminta supaya ...)","〜ことだ (yang penting adalah ... / sebaiknya ...)","〜ことか (betapa ... / sungguh ...)","〜ふりをする (berpura-pura ... / pura-pura ...)"],coreVocabSample:["メモ","ゆう","ゆっくり","よほう","よると","よろしく","ろうどう","ふくざつ"]},sensei_context:{sceneIntro:"Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ように言う / 頼む dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kewajaran Logis, Kepastian & Hakikat Fenomena",etiquette:"Gunakan 〜wake da saat memahami penjelasan teknis lawan bicara sebagai bentuk sinyal pemahaman mendalam.",taboos:"Jangan gunakan 〜mono da untuk menggurui atasan mengenai etika dasar."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ように言う / 頼む",moraNote:"Tekankan intonasi datar stabil pada kata penjelas wa-ke-da.",soundTip:"Ucapkan 〜ように言う / 頼む dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ように言う / 頼む",caseScenario:"Menggunakan 〜ように言う / 頼む tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ように言う / 頼む.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ように言う / 頼む sesuai kaidah.",explanation:"Kaidah koneksi 〜ように言う / 頼む: N (orang) + に + Vる/ない + ように + 言う/頼む/伝える."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kewajaran Logis, Kepastian & Hakikat Fenomena (Produksi Aktif & Aplikasi Nyata)",setting:"Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ように言う / 頼む."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、メモの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、メモの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, memo no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai catatan ringkas (memo)? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ 先生に早く来るように言われました。。",furigana:"はい、Kenjiさん！ 先生に早く来るように言われました。。",romaji:"Hai, Kenji-san! ように言う / 頼む de susumete imasu.",idText:"Ya, Kenji! Guru menyuruh saya untuk datang lebih awal.."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。健康のためには、よく寝ることだ。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。健康のためには、よく寝ることだ。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Yang penting untuk kesehatan adalah tidur yang cukup.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02629",word:"メモ",reading:"メモ",romaji:"memo",meaning:"catatan ringkas (memo)",pos:"verb-suru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"メモを 確認【かくにん】します。",furigana:"メモを 確認します。",romaji:"memo o kakunin shimasu.",idText:"Memeriksa catatan ringkas (memo)."}},{id:"vg-n3-02631",word:"言う",reading:"ゆう",romaji:"yuu",meaning:"berkata",pos:"verb-u",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"言う【ゆう】を 確認【かくにん】します。",furigana:"言うを 確認します。",romaji:"yuu o kakunin shimasu.",idText:"Memeriksa berkata."}},{id:"vg-n3-02634",word:"ゆっくり",reading:"ゆっくり",romaji:"yukkuri",meaning:"perlahan; dengan nyaman",pos:"verb-suru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ゆっくりを 確認【かくにん】します。",furigana:"ゆっくりを 確認します。",romaji:"yukkuri o kakunin shimasu.",idText:"Memeriksa perlahan; dengan nyaman."}},{id:"vg-n3-02638",word:"予報",reading:"よほう",romaji:"yohou",meaning:"perkiraan; prediksi",pos:"verb-suru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"予報【よほう】を 確認【かくにん】します。",furigana:"予報を 確認します。",romaji:"yohou o kakunin shimasu.",idText:"Memeriksa perkiraan; prediksi."}},{id:"vg-n3-02639",word:"よると",reading:"よると",romaji:"yoruto",meaning:"menurut",pos:"verb-u",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"よるとを 確認【かくにん】します。",furigana:"よるとを 確認します。",romaji:"yoruto o kakunin shimasu.",idText:"Memeriksa menurut."}},{id:"vg-n3-02641",word:"よろしく",reading:"よろしく",romaji:"yoroshiku",meaning:"well; properly",pos:"adverb",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"よろしくを 確認【かくにん】します。",furigana:"よろしくを 確認します。",romaji:"yoroshiku o kakunin shimasu.",idText:"Memeriksa well; properly."}},{id:"vg-n3-02643",word:"労働",reading:"ろうどう",romaji:"roudou",meaning:"manual labor; toil",pos:"verb-suru",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"労働【ろうどう】を 確認【かくにん】します。",furigana:"労働を 確認します。",romaji:"roudou o kakunin shimasu.",idText:"Memeriksa manual labor; toil."}},{id:"vg-n3-00041",word:"複雑",reading:"ふくざつ",romaji:"fukuzatsu",meaning:"rumit, kompleks",pos:"na-adj",nuance:"Na-adjektif. Lawan: 簡単 (sederhana).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"複雑【ふくざつ】を 確認【かくにん】します。",furigana:"複雑を 確認します。",romaji:"fukuzatsu o kakunin shimasu.",idText:"Memeriksa rumit, kompleks."}}],explanations:[{id:"exp-1",grammarId:"gn3-00070",title:"Pola: 〜ように言う / 頼む",formula:"N (orang) + に + Vる/ない + ように + 言う/頼む/伝える",meaning:"menyuruh agar ... / meminta supaya ...",nuanceNotes:"〜ように言う/頼む digunakan untuk melaporkan perintah atau permintaan tidak langsung.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ように言う / 頼む",idText:"menyuruh agar ... / meminta supaya ..."}],examples:[{jp:"先生に早く来るように言われました。",romaji:"",idText:"Guru menyuruh saya untuk datang lebih awal."},{jp:"彼に静かにするように頼んだ。",romaji:"",idText:"Saya meminta dia agar diam."}]},{id:"exp-2",grammarId:"gn3-00073",title:"Pola: 〜ことだ",formula:"Vる / Vない + ことだ",meaning:"yang penting adalah ... / sebaiknya ...",nuanceNotes:"〜ことだ digunakan untuk memberikan saran atau menyatakan hal yang paling penting untuk dilakukan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことだ",idText:"yang penting adalah ... / sebaiknya ..."}],examples:[{jp:"健康のためには、よく寝ることだ。",romaji:"",idText:"Yang penting untuk kesehatan adalah tidur yang cukup."},{jp:"まず医者に診てもらうことだ。",romaji:"",idText:"Pertama-tama, sebaiknya periksa ke dokter."}]},{id:"exp-3",grammarId:"gn3-00074",title:"Pola: 〜ことか",formula:"疑問詞 + Vた/Adjい + ことか",meaning:"betapa ... / sungguh ...",nuanceNotes:'〜ことか mengekspresikan perasaan yang kuat, biasanya digunakan dengan kata tanya (何度、どれほど, dll): "betapa", "sungguh".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことか",idText:"betapa ... / sungguh ..."}],examples:[{jp:"どれほど心配したことか。",romaji:"",idText:"Betapa saya sudah sangat khawatir."},{jp:"何度泣いたことか。",romaji:"",idText:"Sungguh berkali-kali saya menangis."}]},{id:"exp-4",grammarId:"gn3-00075",title:"Pola: 〜ふりをする",formula:"Vている / Adj / N + の + ふりをする",meaning:"berpura-pura ... / pura-pura ...",nuanceNotes:"〜ふりをする menyatakan berpura-pura melakukan atau berada dalam suatu keadaan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ふりをする",idText:"berpura-pura ... / pura-pura ..."}],examples:[{jp:"聞いたふりをしていた。",romaji:"",idText:"Dia berpura-pura sudah mendengar."},{jp:"知らないふりをしてください。",romaji:"",idText:"Tolong pura-pura tidak tahu."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "メモ"?',sentencePrompt:'Makna kata "メモ" (メモ) dalam situasi kerja ini adalah:',options:["catatan ringkas (memo)","berkata","perlahan; dengan nyaman","perkiraan; prediksi"],correctAnswer:"catatan ringkas (memo)",explanation:'Makna yang tepat untuk "メモ" adalah "catatan ringkas (memo)".',diagnosticFeedback:{berkata:'Salah: Pilihan "berkata" adalah makna dari kata "言う" (ゆう), bukan arti kata "メモ".',"perlahan; dengan nyaman":'Salah: Pilihan "perlahan; dengan nyaman" adalah makna dari kata "ゆっくり" (ゆっくり), bukan arti kata "メモ".',"perkiraan; prediksi":'Salah: Pilihan "perkiraan; prediksi" adalah makna dari kata "予報" (よほう), bukan arti kata "メモ".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"先生に早く来る（　　）。",options:["ように言われました","ことだ","ことか","っぽい"],correctAnswer:"ように言われました",explanation:'Pola 〜ように言う / 頼む bermakna "menyuruh agar ... / meminta supaya ...". Kalimat lengkap: "先生に早く来るように言われました。".',diagnosticFeedback:{ことだ:'Salah: Pola "ことだ" bermakna "yang penting adalah ... / sebaiknya ...", yang tidak sesuai konteks kalimat ini.',ことか:'Salah: Pola "ことか" bermakna "betapa ... / sungguh ...", yang tidak sesuai konteks kalimat ini.',っぽい:'Salah: Pola "っぽい" bermakna "keliatan seperti ... / tampak ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ように言う / 頼む secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["彼に静かにするように頼んだ。","彼に静かにするように頼んだ。でした","健康のためには、よく寝ることだ。","明日は晴れるでしょう。"],correctAnswer:"彼に静かにするように頼んだ。",explanation:'Kalimat yang benar dan alami adalah "彼に静かにするように頼んだ。" (Saya meminta dia agar diam.).',diagnosticFeedback:{"彼に静かにするように頼んだ。でした":"Jebakan Konjugasi: Pola 〜ように言う / 頼む membutuhkan aturan sambung (N (orang) + に + Vる/ない + ように + 言う/頼む/伝える), bukan bentuk ini.","健康のためには、よく寝ることだ。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ことだ: yang penting adalah ... / sebaiknya ...), bukan kaidah 〜ように言う / 頼む.","明日は晴れるでしょう。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ように言う / 頼む secara tepat (menyuruh agar ... / meminta supaya ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["健康のた めには、 よく寝る ことだ。","めには、 健康のた よく寝る ことだ。","健康のた よく寝る めには、 ことだ。","ことだ。 健康のた めには、 よく寝る"],correctAnswer:"健康のた めには、 よく寝る ことだ。",explanation:'Susunan yang benar: "健康のた めには、 よく寝る ことだ。" (Yang penting untuk kesehatan adalah tidur yang cukup.).',diagnosticFeedback:{"めには、 健康のた よく寝る ことだ。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","健康のた よく寝る めには、 ことだ。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","ことだ。 健康のた めには、 よく寝る":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["健康のた","めには、","よく寝る","ことだ。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.", saat Kenji menyampaikan arahan: 「なるほど。健康のためには、よく寝ることだ。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ように言う / 頼む dan 〜ことだ secara mandiri.",situation:"Situasi komunikasi profesional di Diskusi laboratorium kalibrasi alat ukur presisi mikrometer bersama teknisi senior.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ように言う / 頼む!",modelAnswer:"はい、Kenjiさん！ 先生に早く来るように言われました。。",modelAnswerId:"Ya, Kenji! Guru menyuruh saya untuk datang lebih awal..",culturalEtiquette:"Gunakan 〜wake da saat memahami penjelasan teknis lawan bicara sebagai bentuk sinyal pemahaman mendalam.",skillUnlocked:["Menguasai formulasi pola 〜ように言う / 頼む","Mampu menerapkan prinsip koordinasi komunikasi kerja Kewajaran Logis, Kepastian & Hakikat Fenomena"]},pocket_summary:{keyFormula:"〜ように言う / 頼む (menyuruh agar ... / meminta supaya ...)",coreWords:["メモ【メモ】 (catatan ringkas (memo))","言う【ゆう】 (berkata)","ゆっくり【ゆっくり】 (perlahan; dengan nyaman)","予報【よほう】 (perkiraan; prediksi)"],coreWarning:"Jangan gunakan 〜mono da untuk menggurui atasan mengenai etika dasar.",quickDialogue:"A: ブディさん、メモの 状況【じょうきょう】は どうで... → B: はい、Kenjiさん！ 先生に早く来るように言われ..."}}},n={"les-n3-u09-01":{pedagogical_framework:{what:{summary:"Penekanan Topik, Pengecualian & Batas Minimal (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜っぽい, 〜ような気がする, 〜だっけ, 〜だもん / 〜だもの, 〜ものか / 〜もんか dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜っぽい dan 〜ような気がする dalam percakapan kerja wajar.",targetPatterns:["〜っぽい (keliatan seperti ... / tampak ...)","〜ような気がする (rasanya ... / sepertinya ...)","〜だっけ (... ya? / ... kan? (mengingat-ingat))","〜だもん / 〜だもの (kan ... / soalnya ... (pembenaran kasual))","〜ものか / 〜もんか (tidak sudi ... / masa mau ... (penolakan tegas))"],coreVocabSample:["しんちょう","せっきょくてき","しょうきょくてき","じゅうなん","こうへい","ふこうへい","どくとく","いっぱんてき"]},sensei_context:{sceneIntro:"Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜っぽい dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Penekanan Topik, Pengecualian & Batas Minimal",etiquette:"Pilihlah 〜koso saat menyampaikan komitmen integritas kerja tim di hadapan auditor eksternal.",taboos:"Perhatikan bahwa 〜sae terkadang mengandung nuansa menyindir jika ditujukan pada kekhilafan orang lain."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜っぽい",moraNote:"Lafalkan ko-so dengan nada tegas berbobot pada mora pertama.",soundTip:"Ucapkan 〜っぽい dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜っぽい",caseScenario:"Menggunakan 〜っぽい tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜っぽい.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜っぽい sesuai kaidah.",explanation:"Kaidah koneksi 〜っぽい: N / V-ます語幹 / Adj語幹 + っぽい."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Penekanan Topik, Pengecualian & Batas Minimal (Fondasi & Pemahaman Pola)",setting:"Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 〜っぽい."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、慎重の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、慎重の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, shinchou no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai berhati-hati, cermat, penuh pertimbangan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ この料理は子どもっぽい。。",furigana:"はい、Yamadaさん！ この料理は子どもっぽい。。",romaji:"Hai, Yamada-san! っぽい de susumete imasu.",idText:"Ya, Yamada! Masakan ini seperti makanan anak-anak.."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。今日は何か良いことがあるような気がする。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。今日は何か良いことがあるような気がする。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Rasanya hari ini akan ada sesuatu yang baik.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00471",word:"慎重",reading:"しんちょう",romaji:"shinchou",meaning:"berhati-hati, cermat, penuh pertimbangan",pos:"na-adj",nuance:"慎重 menekankan kehati-hatian dalam proses berpikir dan pengambilan keputusan agar tidak membuat kesalahan. Berbeda dari 丁寧 (teinei — teliti dalam pelaksanaan) yang lebih tentang cara mengerjakan sesuatu — 慎重 lebih tentang mempertimbangkan risiko sebelum bertindak atau memutuskan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"慎重【しんちょう】を 確認【かくにん】します。",furigana:"慎重を 確認します。",romaji:"shinchou o kakunin shimasu.",idText:"Memeriksa berhati-hati, cermat, penuh pertimbangan."}},{id:"vg-n3-00472",word:"積極的",reading:"せっきょくてき",romaji:"sekkyokuteki",meaning:"proaktif, aktif, bersemangat",pos:"na-adj",nuance:"積極的 berarti aktif berinisiatif dan tidak menunggu disuruh. Lawan langsungnya adalah 消極的 (shoukyokuteki — pasif). Dalam konteks kerja atau pendidikan, 積極的に参加する = berpartisipasi secara aktif. Sering muncul dalam evaluasi kinerja di Jepang sebagai kualitas yang dipuji.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"積極的【せっきょくてき】を 確認【かくにん】します。",furigana:"積極的を 確認します。",romaji:"sekkyokuteki o kakunin shimasu.",idText:"Memeriksa proaktif, aktif, bersemangat."}},{id:"vg-n3-00473",word:"消極的",reading:"しょうきょくてき",romaji:"shoukyokuteki",meaning:"pasif, tidak antusias, kurang berinisiatif",pos:"na-adj",nuance:"消極的 berarti cenderung menghindari tindakan atau kurang berinisiatif. Lawan langsung dari 積極的. Tidak selalu bermakna negatif — dalam beberapa konteks menggambarkan sikap yang menghindari konflik atau tidak memaksakan kehendak. Namun dalam konteks pekerjaan atau pendidikan, biasanya bernuansa kurang baik.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"消極的【しょうきょくてき】を 確認【かくにん】します。",furigana:"消極的を 確認します。",romaji:"shoukyokuteki o kakunin shimasu.",idText:"Memeriksa pasif, tidak antusias, kurang berinisiatif."}},{id:"vg-n3-00474",word:"柔軟",reading:"じゅうなん",romaji:"juunan",meaning:"fleksibel, lentur, adaptif",pos:"na-adj",nuance:"柔軟 bisa berarti fleksibel secara fisik (tubuh lentur) maupun secara pikiran (berpikiran terbuka dan adaptif). 柔軟な対応 = penanganan yang fleksibel. Berbeda dari 自由 (jiyuu — bebas) yang lebih tentang kebebasan tanpa batasan — 柔軟 menekankan kemampuan menyesuaikan diri sesuai kebutuhan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"柔軟【じゅうなん】を 確認【かくにん】します。",furigana:"柔軟を 確認します。",romaji:"juunan o kakunin shimasu.",idText:"Memeriksa fleksibel, lentur, adaptif."}},{id:"vg-n3-00475",word:"公平",reading:"こうへい",romaji:"kouhei",meaning:"adil, tidak memihak, fair",pos:"na-adj",nuance:"公平 berarti memberikan perlakuan yang tepat dan tidak memihak. Berbeda dari 平等 (byoudou — kesetaraan/sama rata) yang menekankan distribusi yang identik — 公平 lebih tentang keadilan yang disesuaikan dengan konteks, di mana perlakuan berbeda pun bisa 公平 jika sesuai kebutuhan masing-masing.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"公平【こうへい】を 確認【かくにん】します。",furigana:"公平を 確認します。",romaji:"kouhei o kakunin shimasu.",idText:"Memeriksa adil, tidak memihak, fair."}},{id:"vg-n3-00476",word:"不公平",reading:"ふこうへい",romaji:"fukouhei",meaning:"tidak adil, berat sebelah",pos:"na-adj",nuance:"不公平 adalah antonim langsung dari 公平, menggambarkan perlakuan yang berat sebelah atau tidak merata. Berbeda dari 不平等 (fubyoudou — ketidaksetaraan sistemik) yang lebih sering digunakan dalam konteks sosial atau akademik — 不公平 lebih umum dalam percakapan sehari-hari untuk mengungkapkan rasa tidak adil dalam situasi konkret.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"不公平【ふこうへい】を 確認【かくにん】します。",furigana:"不公平を 確認します。",romaji:"fukouhei o kakunin shimasu.",idText:"Memeriksa tidak adil, berat sebelah."}},{id:"vg-n3-00477",word:"独特",reading:"どくとく",romaji:"dokutoku",meaning:"unik, khas, berbeda dari yang lain",pos:"na-adj",nuance:"独特 menekankan keunikan yang membedakan dari yang lain, bisa bernilai positif maupun netral. Berbeda dari ユニーク (yuniiku) yang berasal dari bahasa Inggris dan bernuansa lebih positif/modern — 独特 lebih formal dan bisa juga menyiratkan 'aneh' atau 'tidak biasa' tanpa konotasi positif yang kuat.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"独特【どくとく】を 確認【かくにん】します。",furigana:"独特を 確認します。",romaji:"dokutoku o kakunin shimasu.",idText:"Memeriksa unik, khas, berbeda dari yang lain."}},{id:"vg-n3-00478",word:"一般的",reading:"いっぱんてき",romaji:"ippanteki",meaning:"umum, lazim, pada umumnya",pos:"na-adj",nuance:"一般的 berarti berlaku luas untuk banyak orang atau situasi, bersifat umum. Berbeda dari 普通 (futsuu — biasa/normal) yang lebih kasual dan sehari-hari — 一般的 lebih formal dan akademis, sering digunakan dalam penjelasan atau analisis. 一般的に言えば = secara umum.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"一般的【いっぱんてき】を 確認【かくにん】します。",furigana:"一般的を 確認します。",romaji:"ippanteki o kakunin shimasu.",idText:"Memeriksa umum, lazim, pada umumnya."}}],explanations:[{id:"exp-1",grammarId:"gn3-00076",title:"Pola: 〜っぽい",formula:"N / V-ます語幹 / Adj語幹 + っぽい",meaning:"keliatan seperti ... / tampak ...",nuanceNotes:'〜っぽい menyatakan kesan atau kecenderungan: "tampaknya", "sepertinya". Bernada kasual.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜っぽい",idText:"keliatan seperti ... / tampak ..."}],examples:[{jp:"この料理は子どもっぽい。",romaji:"",idText:"Masakan ini seperti makanan anak-anak."},{jp:"彼は忘れっぽい性格だ。",romaji:"",idText:"Karakternya mudah lupa."}]},{id:"exp-2",grammarId:"gn3-00083",title:"Pola: 〜ような気がする",formula:"V/Adj plain / N + の + ような気がする",meaning:"rasanya ... / sepertinya ...",nuanceNotes:'〜ような気がする mengekspresikan perasaan subjektif atau intuisi: "rasanya", "seperti ada perasaan bahwa".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ような気がする",idText:"rasanya ... / sepertinya ..."}],examples:[{jp:"今日は何か良いことがあるような気がする。",romaji:"",idText:"Rasanya hari ini akan ada sesuatu yang baik."},{jp:"彼に会ったことがあるような気がする。",romaji:"",idText:"Sepertinya saya pernah bertemu dia."}]},{id:"exp-3",grammarId:"gn3-00089",title:"Pola: 〜だっけ",formula:"V/Adj plain / N + だっけ",meaning:"... ya? / ... kan? (mengingat-ingat)",nuanceNotes:"〜だっけ digunakan ketika pembicara mencoba mengingat-ingat informasi atau meminta konfirmasi dari lawan bicara secara kasual.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜だっけ",idText:"... ya? / ... kan? (mengingat-ingat)"}],examples:[{jp:"パーティーは何時からだっけ？",romaji:"",idText:"Pestanya mulai jam berapa ya?"},{jp:"田中さんって、結婚してるんだっけ？",romaji:"",idText:"Tanaka-san sudah menikah kan?"}]},{id:"exp-4",grammarId:"gn3-00090",title:"Pola: 〜だもん / 〜だもの",formula:"V/Adj plain / N + だもん / だもの",meaning:"kan ... / soalnya ... (pembenaran kasual)",nuanceNotes:"〜だもん / 〜だもの digunakan sebagai pembenaran atau alasan kasual, bernada sedikit merengek atau membela diri.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜だもん / 〜だもの",idText:"kan ... / soalnya ... (pembenaran kasual)"}],examples:[{jp:"食べちゃった。だっておいしかったんだもん。",romaji:"",idText:"Sudah kumakan. Soalnya enak sih."},{jp:"仕方ないでしょ、疲れてるんだもの。",romaji:"",idText:"Tidak bisa disalahkan, soalnya capek."}]},{id:"exp-5",grammarId:"gn3-00092",title:"Pola: 〜ものか / 〜もんか",formula:"Vる / Adjい + ものか",meaning:"tidak sudi ... / masa mau ... (penolakan tegas)",nuanceNotes:'〜ものか menyatakan penolakan tegas atau tekad kuat untuk tidak melakukan sesuatu: "tidak sudi", "masa mau".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ものか / 〜もんか",idText:"tidak sudi ... / masa mau ... (penolakan tegas)"}],examples:[{jp:"あんな人に頼むものか！",romaji:"",idText:"Masa mau minta tolong kepada orang seperti itu!"},{jp:"絶対に負けるものか！",romaji:"",idText:"Tidak sudi kalah!"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "慎重"?',sentencePrompt:'Makna kata "慎重" (しんちょう) dalam situasi kerja ini adalah:',options:["berhati-hati, cermat, penuh pertimbangan","proaktif, aktif, bersemangat","pasif, tidak antusias, kurang berinisiatif","fleksibel, lentur, adaptif"],correctAnswer:"berhati-hati, cermat, penuh pertimbangan",explanation:'Makna yang tepat untuk "慎重" adalah "berhati-hati, cermat, penuh pertimbangan".',diagnosticFeedback:{"proaktif, aktif, bersemangat":'Salah: Pilihan "proaktif, aktif, bersemangat" adalah makna dari kata "積極的" (せっきょくてき), bukan arti kata "慎重".',"pasif, tidak antusias, kurang berinisiatif":'Salah: Pilihan "pasif, tidak antusias, kurang berinisiatif" adalah makna dari kata "消極的" (しょうきょくてき), bukan arti kata "慎重".',"fleksibel, lentur, adaptif":'Salah: Pilihan "fleksibel, lentur, adaptif" adalah makna dari kata "柔軟" (じゅうなん), bukan arti kata "慎重".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"この料理は子ども（　　）。",options:["っぽい","ような気がする","だっけ","ことになっている"],correctAnswer:"っぽい",explanation:'Pola 〜っぽい bermakna "keliatan seperti ... / tampak ...". Kalimat lengkap: "この料理は子どもっぽい。".',diagnosticFeedback:{ような気がする:'Salah: Pola "ような気がする" bermakna "rasanya ... / sepertinya ...", yang tidak sesuai konteks kalimat ini.',だっけ:'Salah: Pola "だっけ" bermakna "... ya? / ... kan? (mengingat-ingat)", yang tidak sesuai konteks kalimat ini.',ことになっている:'Salah: Pola "ことになっている" bermakna "sudah ada aturan bahwa ..., berlaku ketentuan ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜っぽい secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["彼は忘れっぽい性格だ。","彼は忘れっぽいでした性格だ。","今日は何か良いことがあるような気がする。","趣味というより、もはや仕事になっている。"],correctAnswer:"彼は忘れっぽい性格だ。",explanation:'Kalimat yang benar dan alami adalah "彼は忘れっぽい性格だ。" (Karakternya mudah lupa.).',diagnosticFeedback:{"彼は忘れっぽいでした性格だ。":"Jebakan Konjugasi: Pola 〜っぽい membutuhkan aturan sambung (N / V-ます語幹 / Adj語幹 + っぽい), bukan bentuk ini.","今日は何か良いことがあるような気がする。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ような気がする: rasanya ... / sepertinya ...), bukan kaidah 〜っぽい.","趣味というより、もはや仕事になっている。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜っぽい secara tepat (keliatan seperti ... / tampak ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["今日は何か 良いことが あるような 気がする。","良いことが 今日は何か あるような 気がする。","今日は何か あるような 良いことが 気がする。","気がする。 今日は何か 良いことが あるような"],correctAnswer:"今日は何か 良いことが あるような 気がする。",explanation:'Susunan yang benar: "今日は何か 良いことが あるような 気がする。" (Rasanya hari ini akan ada sesuatu yang baik.).',diagnosticFeedback:{"良いことが 今日は何か あるような 気がする。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","今日は何か あるような 良いことが 気がする。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","気がする。 今日は何か 良いことが あるような":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["今日は何か","良いことが","あるような","気がする。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.", saat Yamada menyampaikan arahan: 「なるほど。今日は何か良いことがあるような気がする。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜っぽい dan 〜ような気がする dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜っぽい!",modelAnswer:"はい、Yamadaさん！ この料理は子どもっぽい。。",modelAnswerId:"Ya, Yamada! Masakan ini seperti makanan anak-anak..",culturalEtiquette:"Pilihlah 〜koso saat menyampaikan komitmen integritas kerja tim di hadapan auditor eksternal.",skillUnlocked:["Menguasai formulasi pola 〜っぽい","Mampu menerapkan prinsip koordinasi komunikasi kerja Penekanan Topik, Pengecualian & Batas Minimal"]},pocket_summary:{keyFormula:"〜っぽい (keliatan seperti ... / tampak ...)",coreWords:["慎重【しんちょう】 (berhati-hati, cermat, penuh pertimbangan)","積極的【せっきょくてき】 (proaktif, aktif, bersemangat)","消極的【しょうきょくてき】 (pasif, tidak antusias, kurang berinisiatif)","柔軟【じゅうなん】 (fleksibel, lentur, adaptif)"],coreWarning:"Perhatikan bahwa 〜sae terkadang mengandung nuansa menyindir jika ditujukan pada kekhilafan orang lain.",quickDialogue:"A: ブディさん、慎重の 状況【じょうきょう】は どうで... → B: はい、Yamadaさん！ この料理は子どもっぽい。..."}},"les-n3-u09-02":{pedagogical_framework:{what:{summary:"Penekanan Topik, Pengecualian & Batas Minimal (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜てごらん, 〜んだって, もしかすると / もしかしたら〜かもしれない, 〜かな（あ） dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜てごらん dan 〜んだって secara mandiri.",targetPatterns:["〜てごらん (coba lakukan ... / cobalah ...)","〜んだって (katanya ... / memangnya ...)","もしかすると / もしかしたら〜かもしれない (mungkin saja ... / bisa jadi ...)","〜かな（あ） (... ya kira-kira / ... ya (monolog))"],coreVocabSample:["けんこう","こい","こううん","こうか","ごうか","こうせい","こうふく","さいこう"]},sensei_context:{sceneIntro:"Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜てごらん dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Penekanan Topik, Pengecualian & Batas Minimal",etiquette:"Pilihlah 〜koso saat menyampaikan komitmen integritas kerja tim di hadapan auditor eksternal.",taboos:"Perhatikan bahwa 〜sae terkadang mengandung nuansa menyindir jika ditujukan pada kekhilafan orang lain."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜てごらん",moraNote:"Lafalkan ko-so dengan nada tegas berbobot pada mora pertama.",soundTip:"Ucapkan 〜てごらん dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜てごらん",caseScenario:"Menggunakan 〜てごらん tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜てごらん.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜てごらん sesuai kaidah.",explanation:"Kaidah koneksi 〜てごらん: Vて + ごらん."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Penekanan Topik, Pengecualian & Batas Minimal (Produksi Aktif & Aplikasi Nyata)",setting:"Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 〜てごらん."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、健康の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、健康の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, kenkou no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai kesehatan; sehat, bugar? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ やってみてごらん。きっとできるよ。。",furigana:"はい、Yamadaさん！ やってみてごらん。きっとできるよ。。",romaji:"Hai, Yamada-san! てごらん de susumete imasu.",idText:"Ya, Yamada! Coba lakukan. Pasti bisa.."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。田中さん、転職するんだって。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。田中さん、転職するんだって。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Katanya Tanaka-san mau ganti pekerjaan.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01377",word:"健康",reading:"けんこう",romaji:"kenkou",meaning:"kesehatan; sehat, bugar",pos:"na-adj",nuance:"Bisa berfungsi sebagai nomina (keadaan sehat / kesehatan) dan kata sifat-na (bugar / menyehatkan). Contoh: 健康診断 (pemeriksaan kesehatan), 健康保険 (asuransi kesehatan), 健康な体 (tubuh yang sehat). Berbeda dengan 元気 (genki) yang lebih mencerminkan semangat ceria dan vitalitas fisik sehari-hari; 健康 lebih mengarah pada kondisi medis fisik dan fungsi organ yang bebas dari penyakit.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"健康【けんこう】を 確認【かくにん】します。",furigana:"健康を 確認します。",romaji:"kenkou o kakunin shimasu.",idText:"Memeriksa kesehatan; sehat, bugar."}},{id:"vg-n3-01388",word:"濃い",reading:"こい",romaji:"koi",meaning:"pekat, kental, tebal, tua (warna), tajam (rasa)",pos:"i-adj",nuance:"Dipakai untuk menyatakan kepekatan rasa/aroma makanan, kegelapan warna (warna tua), atau ketebalan cairan dan kabut. Berlawanan langsung dengan '薄い' (usui) yang bermakna encer, hambar, atau muda.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"濃い【こい】を 確認【かくにん】します。",furigana:"濃いを 確認します。",romaji:"koi o kakunin shimasu.",idText:"Memeriksa pekat, kental, tebal, tua (warna), tajam (rasa)."}},{id:"vg-n3-01390",word:"幸運",reading:"こううん",romaji:"kouun",meaning:"keberuntungan, nasib baik, mujur",pos:"na-adj",nuance:"Menyatakan nasib mujur atau kesempatan beruntung yang datang secara tak terduga. Berlawanan dengan '不運' (fuun) yang berarti kemalangan atau nasib sial.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"幸運【こううん】を 確認【かくにん】します。",furigana:"幸運を 確認します。",romaji:"kouun o kakunin shimasu.",idText:"Memeriksa keberuntungan, nasib baik, mujur."}},{id:"vg-n3-01393",word:"高価",reading:"こうか",romaji:"kouka",meaning:"mahal harganya, bernilai tinggi",pos:"na-adj",nuance:"Bentuk formal untuk menyatakan barang bernilai ekonomi tinggi atau berharga mahal. Berbeda dengan '高い' (takai) yang umum dipakai dalam percakapan santai. Lawan katanya adalah '安価' (anka).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"高価【こうか】を 確認【かくにん】します。",furigana:"高価を 確認します。",romaji:"kouka o kakunin shimasu.",idText:"Memeriksa mahal harganya, bernilai tinggi."}},{id:"vg-n3-01394",word:"豪華",reading:"ごうか",romaji:"gouka",meaning:"mewah, megah, bergelimang kemewahan",pos:"na-adj",nuance:"Menggambarkan tampilan kemewahan yang megah, berkelas, dan menghabiskan dana besar (seperti hotel berbintang atau pesta besar). Berbeda dengan '派手' (hade) yang berkonotasi warna/gaya mencolok. Lawan katanya adalah '質素' (shisso).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"豪華【ごうか】を 確認【かくにん】します。",furigana:"豪華を 確認します。",romaji:"gouka o kakunin shimasu.",idText:"Memeriksa mewah, megah, bergelimang kemewahan."}},{id:"vg-n3-01405",word:"公正",reading:"こうせい",romaji:"kousei",meaning:"adil, tidak memihak, jujur objektif",pos:"na-adj",nuance:"Menggambarkan prinsip keadilan yang bebas dari bias dan berpatokan teguh pada hukum atau moral yang sah (seperti dalam proses peradilan atau pemilu). Berbeda dengan '公平' (kouhei) yang lebih menitikberatkan pembagian porsi secara merata.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"公正【こうせい】を 確認【かくにん】します。",furigana:"公正を 確認します。",romaji:"kousei o kakunin shimasu.",idText:"Memeriksa adil, tidak memihak, jujur objektif."}},{id:"vg-n3-01411",word:"幸福",reading:"こうふく",romaji:"koufuku",meaning:"kebahagiaan batin, kemujuran hidup",pos:"na-adj",nuance:"Menyatakan kondisi batin yang tenteram dan dipenuhi kepuasan hidup yang bermakna mendalam. Bernada lebih formal dan filosofis dibandingkan kata santai '幸せ' (shiawase). Lawan katanya adalah '不幸' (fukou).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"幸福【こうふく】を 確認【かくにん】します。",furigana:"幸福を 確認します。",romaji:"koufuku o kakunin shimasu.",idText:"Memeriksa kebahagiaan batin, kemujuran hidup."}},{id:"vg-n3-01461",word:"最高",reading:"さいこう",romaji:"saikou",meaning:"tertinggi, terbaik, terhebat, paling mantap",pos:"na-adj",nuance:"Memiliki dua kegunaan utama: (1) Nilai, batas, atau posisi paling atas (最高気温 / suhu tertinggi, 最高記録 / rekor tertinggi). (2) Bahasa sehari-hari untuk menyatakan kepuasan puncak bahwa suatu hal itu 'paling mantap/terbaik' (最高だ！ / mantap sekali!). Lawan katanya adalah 最低 (saitei).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"最高【さいこう】を 確認【かくにん】します。",furigana:"最高を 確認します。",romaji:"saikou o kakunin shimasu.",idText:"Memeriksa tertinggi, terbaik, terhebat, paling mantap."}}],explanations:[{id:"exp-1",grammarId:"gn3-00093",title:"Pola: 〜てごらん",formula:"Vて + ごらん",meaning:"coba lakukan ... / cobalah ...",nuanceNotes:"〜てごらん digunakan untuk menyarankan atau menantang seseorang untuk mencoba sesuatu. Digunakan oleh orang yang lebih tua/memiliki otoritas kepada yang lebih muda.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てごらん",idText:"coba lakukan ... / cobalah ..."}],examples:[{jp:"やってみてごらん。きっとできるよ。",romaji:"",idText:"Coba lakukan. Pasti bisa."},{jp:"この本を読んでごらん。面白いから。",romaji:"",idText:"Coba baca buku ini. Karena menarik."}]},{id:"exp-2",grammarId:"gn3-00095",title:"Pola: 〜んだって",formula:"V/Adj plain / N + んだって",meaning:"katanya ... / memangnya ...",nuanceNotes:'〜んだって adalah bentuk kasual untuk melaporkan informasi yang didengar dari orang lain: "katanya".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜んだって",idText:"katanya ... / memangnya ..."}],examples:[{jp:"田中さん、転職するんだって。",romaji:"",idText:"Katanya Tanaka-san mau ganti pekerjaan."},{jp:"明日休みなんだって。",romaji:"",idText:"Katanya besok libur."}]},{id:"exp-3",grammarId:"gn3-00099",title:"Pola: もしかすると / もしかしたら〜かもしれない",formula:"もしかすると / もしかしたら + 文 + かもしれない",meaning:"mungkin saja ... / bisa jadi ...",nuanceNotes:'もしかすると〜かもしれない memperkuat ekspresi kemungkinan yang tidak pasti: "mungkin saja", "bisa jadi".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"もしかすると / もしかしたら〜かもしれない",idText:"mungkin saja ... / bisa jadi ..."}],examples:[{jp:"もしかすると、彼女は知っているかもしれない。",romaji:"",idText:"Mungkin saja dia tahu."},{jp:"もしかしたら、雨が降るかもしれないから傘を持って行こう。",romaji:"",idText:"Bisa jadi hujan, jadi ayo bawa payung."}]},{id:"exp-4",grammarId:"gn3-00104",title:"Pola: 〜かな（あ）",formula:"V/Adj plain / N + かな(あ)",meaning:"... ya kira-kira / ... ya (monolog)",nuanceNotes:"〜かな（あ） digunakan dalam monolog atau percakapan kasual untuk mengekspresikan keraguan, keheranan, atau harapan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜かな（あ）",idText:"... ya kira-kira / ... ya (monolog)"}],examples:[{jp:"もうそろそろ来るかなあ。",romaji:"",idText:"Kira-kira sebentar lagi datang ya."},{jp:"明日晴れるかな。",romaji:"",idText:"Besok cerah ya kira-kira."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "健康"?',sentencePrompt:'Makna kata "健康" (けんこう) dalam situasi kerja ini adalah:',options:["kesehatan; sehat, bugar","pekat, kental, tebal, tua (warna), tajam (rasa)","keberuntungan, nasib baik, mujur","mahal harganya, bernilai tinggi"],correctAnswer:"kesehatan; sehat, bugar",explanation:'Makna yang tepat untuk "健康" adalah "kesehatan; sehat, bugar".',diagnosticFeedback:{"pekat, kental, tebal, tua (warna), tajam (rasa)":'Salah: Pilihan "pekat, kental, tebal, tua (warna), tajam (rasa)" adalah makna dari kata "濃い" (こい), bukan arti kata "健康".',"keberuntungan, nasib baik, mujur":'Salah: Pilihan "keberuntungan, nasib baik, mujur" adalah makna dari kata "幸運" (こううん), bukan arti kata "健康".',"mahal harganya, bernilai tinggi":'Salah: Pilihan "mahal harganya, bernilai tinggi" adalah makna dari kata "高価" (こうか), bukan arti kata "健康".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"やって（　　）。きっとできるよ。",options:["みてごらん","んだって","もしかすると / もしかしたら〜かもしれない","ことになっている"],correctAnswer:"みてごらん",explanation:'Pola 〜てごらん bermakna "coba lakukan ... / cobalah ...". Kalimat lengkap: "やってみてごらん。きっとできるよ。".',diagnosticFeedback:{んだって:'Salah: Pola "んだって" bermakna "katanya ... / memangnya ...", yang tidak sesuai konteks kalimat ini.',"もしかすると / もしかしたら〜かもしれない":'Salah: Pola "もしかすると / もしかしたら〜かもしれない" bermakna "mungkin saja ... / bisa jadi ...", yang tidak sesuai konteks kalimat ini.',ことになっている:'Salah: Pola "ことになっている" bermakna "sudah ada aturan bahwa ..., berlaku ketentuan ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜てごらん secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["この本を読んでごらん。面白いから。","この本を読んでごらん。面白いから。でした","田中さん、転職するんだって。","趣味というより、もはや仕事になっている。"],correctAnswer:"この本を読んでごらん。面白いから。",explanation:'Kalimat yang benar dan alami adalah "この本を読んでごらん。面白いから。" (Coba baca buku ini. Karena menarik.).',diagnosticFeedback:{"この本を読んでごらん。面白いから。でした":"Jebakan Konjugasi: Pola 〜てごらん membutuhkan aturan sambung (Vて + ごらん), bukan bentuk ini.","田中さん、転職するんだって。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜んだって: katanya ... / memangnya ...), bukan kaidah 〜てごらん.","趣味というより、もはや仕事になっている。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜てごらん secara tepat (coba lakukan ... / cobalah ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["田中さん 、 転職するんだって 。","、 田中さん 転職するんだって 。","田中さん 転職するんだって 、 。","。 田中さん 、 転職するんだって"],correctAnswer:"田中さん 、 転職するんだって 。",explanation:'Susunan yang benar: "田中さん 、 転職するんだって 。" (Katanya Tanaka-san mau ganti pekerjaan.).',diagnosticFeedback:{"、 田中さん 転職するんだって 。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","田中さん 転職するんだって 、 。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","。 田中さん 、 転職するんだって":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["田中さん","、","転職するんだって","。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.", saat Yamada menyampaikan arahan: 「なるほど。田中さん、転職するんだって。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜てごらん dan 〜んだって secara mandiri.",situation:"Situasi komunikasi profesional di Pemeriksaan akhir mutu produk (Quality Control) sebelum pengepakan kontainer pelabuhan.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜てごらん!",modelAnswer:"はい、Yamadaさん！ やってみてごらん。きっとできるよ。。",modelAnswerId:"Ya, Yamada! Coba lakukan. Pasti bisa..",culturalEtiquette:"Pilihlah 〜koso saat menyampaikan komitmen integritas kerja tim di hadapan auditor eksternal.",skillUnlocked:["Menguasai formulasi pola 〜てごらん","Mampu menerapkan prinsip koordinasi komunikasi kerja Penekanan Topik, Pengecualian & Batas Minimal"]},pocket_summary:{keyFormula:"〜てごらん (coba lakukan ... / cobalah ...)",coreWords:["健康【けんこう】 (kesehatan; sehat, bugar)","濃い【こい】 (pekat, kental, tebal, tua (warna), tajam (rasa))","幸運【こううん】 (keberuntungan, nasib baik, mujur)","高価【こうか】 (mahal harganya, bernilai tinggi)"],coreWarning:"Perhatikan bahwa 〜sae terkadang mengandung nuansa menyindir jika ditujukan pada kekhilafan orang lain.",quickDialogue:"A: ブディさん、健康の 状況【じょうきょう】は どうで... → B: はい、Yamadaさん！ やってみてごらん。きっと..."}}},e={"les-n3-u10-01":{pedagogical_framework:{what:{summary:"Rasa Batin, Keraguan Halus & Nada Percakapan (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜ことになっている, 〜ないわけにはいかない, 〜てもかまわない, 〜ていただけませんか, 〜てくださいませんか dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜ことになっている dan 〜ないわけにはいかない dalam percakapan kerja wajar.",targetPatterns:["〜ことになっている (sudah ada aturan bahwa ..., berlaku ketentuan ...)","〜ないわけにはいかない (tidak bisa tidak ..., harus melakukan ...)","〜てもかまわない (tidak apa-apa kalau ..., boleh saja ..., tidak masalah jika ...)","〜ていただけませんか (bisakah Anda bersedia melakukan ..., maukah Anda ... (permohonan formal))","〜てくださいませんか (maukah Anda ..., tolong ... (permintaan formal menggunakan kudasaru))"],coreVocabSample:["かわいらしい","クラシック","くわしい","こんなん","しあわせ","ちょくせつ","つらい","よい"]},sensei_context:{sceneIntro:"Istirahat siang di kafetaria kantor bersama rekan kerja multinasional. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜ことになっている dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Rasa Batin, Keraguan Halus & Nada Percakapan",etiquette:"Gunakan ragam percakapan yang hangat namun tetap santun untuk mempererat keakraban antarstaf.",taboos:"Jangan memakai partikel kasual 〜dakke atau 〜damon saat berkoordinasi resmi dengan pimpinan direksi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ことになっている",moraNote:"Ucapkan ki ga suru dengan nada mengambang ringan untuk menunjukkan firasat personal.",soundTip:"Ucapkan 〜ことになっている dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ことになっている",caseScenario:"Menggunakan 〜ことになっている tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ことになっている.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ことになっている sesuai kaidah.",explanation:"Kaidah koneksi 〜ことになっている: V-plain (非過去) + ことになっている."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Rasa Batin, Keraguan Halus & Nada Percakapan (Fondasi & Pemahaman Pola)",setting:"Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ことになっている."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、かわいらしいの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、かわいらしいの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, kawairashii no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai indah; manis? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ この建物では、禁煙することになっている。。",furigana:"はい、Yamadaさん！ この建物では、禁煙することになっている。。",romaji:"Hai, Yamada-san! ことになっている de susumete imasu.",idText:"Ya, Yamada! Sudah ada ketentuan bahwa merokok dilarang di gedung ini.."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。約束したから、行かないわけにはいかない。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。約束したから、行かないわけにはいかない。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Karena sudah berjanji, saya tidak bisa tidak pergi.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02492",word:"かわいらしい",reading:"かわいらしい",romaji:"kawairashii",meaning:"indah; manis",pos:"i-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"かわいらしいを 確認【かくにん】します。",furigana:"かわいらしいを 確認します。",romaji:"kawairashii o kakunin shimasu.",idText:"Memeriksa indah; manis."}},{id:"vg-n3-02504",word:"クラシック",reading:"クラシック",romaji:"kurashikku",meaning:"klasik",pos:"na-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"クラシックを 確認【かくにん】します。",furigana:"クラシックを 確認します。",romaji:"kurashikku o kakunin shimasu.",idText:"Memeriksa klasik."}},{id:"vg-n3-02505",word:"詳しい",reading:"くわしい",romaji:"kuwashii",meaning:"knowing very well; detailed",pos:"i-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"詳しい【くわしい】を 確認【かくにん】します。",furigana:"詳しいを 確認します。",romaji:"kuwashii o kakunin shimasu.",idText:"Memeriksa knowing very well; detailed."}},{id:"vg-n3-02516",word:"困難",reading:"こんなん",romaji:"konnan",meaning:"kesulitan; kesusahan",pos:"na-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"困難【こんなん】を 確認【かくにん】します。",furigana:"困難を 確認します。",romaji:"konnan o kakunin shimasu.",idText:"Memeriksa kesulitan; kesusahan."}},{id:"vg-n3-02529",word:"幸せ",reading:"しあわせ",romaji:"shiawase",meaning:"happiness; good fortune",pos:"na-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"幸せ【しあわせ】を 確認【かくにん】します。",furigana:"幸せを 確認します。",romaji:"shiawase o kakunin shimasu.",idText:"Memeriksa happiness; good fortune."}},{id:"vg-n3-02577",word:"直接",reading:"ちょくせつ",romaji:"chokusetsu",meaning:"direct; immediate",pos:"na-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"直接【ちょくせつ】を 確認【かくにん】します。",furigana:"直接を 確認します。",romaji:"chokusetsu o kakunin shimasu.",idText:"Memeriksa direct; immediate."}},{id:"vg-n3-02581",word:"辛い",reading:"つらい",romaji:"tsurai",meaning:"menyakitkan; memilukan",pos:"i-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"辛い【つらい】を 確認【かくにん】します。",furigana:"辛いを 確認します。",romaji:"tsurai o kakunin shimasu.",idText:"Memeriksa menyakitkan; memilukan."}},{id:"vg-n3-02635",word:"よい",reading:"よい",romaji:"yoi",meaning:"bagus / baik",pos:"i-adj",nuance:"Kosakata level N3: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"よいを 確認【かくにん】します。",furigana:"よいを 確認します。",romaji:"yoi o kakunin shimasu.",idText:"Memeriksa bagus / baik."}}],explanations:[{id:"exp-1",grammarId:"gn3-00123",title:"Pola: 〜ことになっている",formula:"V-plain (非過去) + ことになっている",meaning:"sudah ada aturan bahwa ..., berlaku ketentuan ...",nuanceNotes:"〜ことになっている menyatakan suatu aturan, peraturan, atau kesepakatan yang sudah berlaku dan diakui secara umum. Pola ini digunakan ketika ingin menyampaikan bahwa sesuatu adalah kebijakan atau ketentuan yang sudah ditetapkan, bukan keputusan pribadi pembicara.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことになっている",idText:"sudah ada aturan bahwa ..., berlaku ketentuan ..."}],examples:[{jp:"この建物では、禁煙することになっている。",romaji:"",idText:"Sudah ada ketentuan bahwa merokok dilarang di gedung ini."},{jp:"会議には全員が参加することになっている。",romaji:"",idText:"Berlaku ketentuan bahwa semua orang harus hadir dalam rapat."},{jp:"毎月、報告書を提出することになっています。",romaji:"",idText:"Ada aturan bahwa laporan harus diserahkan setiap bulan."}]},{id:"exp-2",grammarId:"gn3-00138",title:"Pola: 〜ないわけにはいかない",formula:"V-ない + わけにはいかない",meaning:"tidak bisa tidak ..., harus melakukan ...",nuanceNotes:'〜ないわけにはいかない menyatakan bahwa pembicara tidak bisa tidak melakukan sesuatu karena alasan moral, sosial, atau logis yang memaksa. Secara harfiah berarti "tidak ada alasan untuk tidak melakukan". Pola ini mengungkapkan kewajiban yang dirasakan dari luar diri pembicara.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ないわけにはいかない",idText:"tidak bisa tidak ..., harus melakukan ..."}],examples:[{jp:"約束したから、行かないわけにはいかない。",romaji:"",idText:"Karena sudah berjanji, saya tidak bisa tidak pergi."},{jp:"上司に頼まれたら、引き受けないわけにはいかない。",romaji:"",idText:"Kalau diminta atasan, tidak bisa tidak menerimanya."},{jp:"彼が謝ってきたら、許さないわけにはいかないだろう。",romaji:"",idText:"Kalau dia sudah minta maaf, tidak ada alasan untuk tidak memaafkan."}]},{id:"exp-3",grammarId:"gn3-00151",title:"Pola: 〜てもかまわない",formula:"V-て + もかまわない",meaning:"tidak apa-apa kalau ..., boleh saja ..., tidak masalah jika ...",nuanceNotes:"〜てもかまわない menyatakan izin atau persetujuan terhadap suatu tindakan — bahwa pembicara tidak keberatan jika hal tersebut dilakukan. Bentuk negatifnya 〜てもかまわない digunakan untuk memberi izin dengan santai, sementara bentuk negatif 〜てもかまわない dapat dipakai untuk meminta izin secara halus. Berbeda dari larangan, pola ini bersifat memperbolehkan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てもかまわない",idText:"tidak apa-apa kalau ..., boleh saja ..., tidak masalah jika ..."}],examples:[{jp:"窓を開けてもかまわないですか。",romaji:"",idText:"Apakah tidak apa-apa jika saya membuka jendelanya?"},{jp:"もう帰ってもかまわないよ。",romaji:"",idText:"Sudah boleh pulang, tidak masalah kok."},{jp:"このパソコンを使ってもかまわないですか。",romaji:"",idText:"Bolehkah saya menggunakan komputer ini?"}]},{id:"exp-4",grammarId:"gn3-00152",title:"Pola: 〜ていただけませんか",formula:"V-て + いただけませんか",meaning:"bisakah Anda bersedia melakukan ..., maukah Anda ... (permohonan formal)",nuanceNotes:"〜ていただけませんか adalah bentuk permohonan paling formal dan sopan dalam deret permintaan bahasa Jepang. Menggunakan bentuk negatif bertanya (〜ませんか) dari kata kerja rendah hati いただく (menerima), pola ini menyiratkan kerendahan hati pembicara yang sangat tinggi. Biasanya dipakai kepada atasan, klien, atau orang yang tidak dikenal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ていただけませんか",idText:"bisakah Anda bersedia melakukan ..., maukah Anda ... (permohonan formal)"}],examples:[{jp:"もう一度説明していただけませんか。",romaji:"",idText:"Bisakah Anda menjelaskannya sekali lagi?"},{jp:"資料をメールで送っていただけませんか。",romaji:"",idText:"Maukah Anda mengirimkan dokumennya melalui email?"},{jp:"こちらにご署名いただけませんか。",romaji:"",idText:"Bisakah Anda berkenan menandatangani di sini?"}]},{id:"exp-5",grammarId:"gn3-00153",title:"Pola: 〜てくださいませんか",formula:"V-て + くださいませんか",meaning:"maukah Anda ..., tolong ... (permintaan formal menggunakan kudasaru)",nuanceNotes:"〜てくださいませんか adalah bentuk permohonan sopan yang menggunakan kata kerja hormat くださる (bentuk hormat dari あげる/くれる). Karena menggunakan くださる yang meninggikan lawan bicara (sonkeigo), pola ini bersifat lebih hormat kepada subjek, meski sedikit kurang merendah dibandingkan 〜ていただけませんか. Cocok untuk situasi formal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てくださいませんか",idText:"maukah Anda ..., tolong ... (permintaan formal menggunakan kudasaru)"}],examples:[{jp:"少々お待ちくださいませんか。",romaji:"",idText:"Maukah Anda menunggu sebentar?"},{jp:"こちらにお名前をご記入くださいませんか。",romaji:"",idText:"Maukah Anda mengisi nama Anda di sini?"},{jp:"会議の日程を変更してくださいませんか。",romaji:"",idText:"Bisakah Anda mengubah jadwal rapat?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "かわいらしい"?',sentencePrompt:'Makna kata "かわいらしい" (かわいらしい) dalam situasi kerja ini adalah:',options:["indah; manis","klasik","knowing very well; detailed","kesulitan; kesusahan"],correctAnswer:"indah; manis",explanation:'Makna yang tepat untuk "かわいらしい" adalah "indah; manis".',diagnosticFeedback:{klasik:'Salah: Pilihan "klasik" adalah makna dari kata "クラシック" (クラシック), bukan arti kata "かわいらしい".',"knowing very well; detailed":'Salah: Pilihan "knowing very well; detailed" adalah makna dari kata "詳しい" (くわしい), bukan arti kata "かわいらしい".',"kesulitan; kesusahan":'Salah: Pilihan "kesulitan; kesusahan" adalah makna dari kata "困難" (こんなん), bukan arti kata "かわいらしい".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"この建物では、禁煙する（　　）。",options:["ことになっている","ないわけにはいかない","てもかまわない","といいですね"],correctAnswer:"ことになっている",explanation:'Pola 〜ことになっている bermakna "sudah ada aturan bahwa ..., berlaku ketentuan ...". Kalimat lengkap: "この建物では、禁煙することになっている。".',diagnosticFeedback:{ないわけにはいかない:'Salah: Pola "ないわけにはいかない" bermakna "tidak bisa tidak ..., harus melakukan ...", yang tidak sesuai konteks kalimat ini.',てもかまわない:'Salah: Pola "てもかまわない" bermakna "tidak apa-apa kalau ..., boleh saja ..., tidak masalah jika ...", yang tidak sesuai konteks kalimat ini.',といいですね:'Salah: Pola "といいですね" bermakna "semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ことになっている secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["会議には全員が参加することになっている。","会議には全員が参加することになっているでした。","約束したから、行かないわけにはいかない。","毎日練習した。その結果、大会で優勝できた。"],correctAnswer:"会議には全員が参加することになっている。",explanation:'Kalimat yang benar dan alami adalah "会議には全員が参加することになっている。" (Berlaku ketentuan bahwa semua orang harus hadir dalam rapat.).',diagnosticFeedback:{"会議には全員が参加することになっているでした。":"Jebakan Konjugasi: Pola 〜ことになっている membutuhkan aturan sambung (V-plain (非過去) + ことになっている), bukan bentuk ini.","約束したから、行かないわけにはいかない。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ないわけにはいかない: tidak bisa tidak ..., harus melakukan ...), bukan kaidah 〜ことになっている.","毎日練習した。その結果、大会で優勝できた。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ことになっている secara tepat (sudah ada aturan bahwa ..., berlaku ketentuan ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["約束したから 、 行かないわけにはいかない 。","、 約束したから 行かないわけにはいかない 。","約束したから 行かないわけにはいかない 、 。","。 約束したから 、 行かないわけにはいかない"],correctAnswer:"約束したから 、 行かないわけにはいかない 。",explanation:'Susunan yang benar: "約束したから 、 行かないわけにはいかない 。" (Karena sudah berjanji, saya tidak bisa tidak pergi.).',diagnosticFeedback:{"、 約束したから 行かないわけにはいかない 。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","約束したから 行かないわけにはいかない 、 。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","。 約束したから 、 行かないわけにはいかない":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["約束したから","、","行かないわけにはいかない","。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.", saat Yamada menyampaikan arahan: 「なるほど。約束したから、行かないわけにはいかない。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜ことになっている dan 〜ないわけにはいかない dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ことになっている!",modelAnswer:"はい、Yamadaさん！ この建物では、禁煙することになっている。。",modelAnswerId:"Ya, Yamada! Sudah ada ketentuan bahwa merokok dilarang di gedung ini..",culturalEtiquette:"Gunakan ragam percakapan yang hangat namun tetap santun untuk mempererat keakraban antarstaf.",skillUnlocked:["Menguasai formulasi pola 〜ことになっている","Mampu menerapkan prinsip koordinasi komunikasi kerja Rasa Batin, Keraguan Halus & Nada Percakapan"]},pocket_summary:{keyFormula:"〜ことになっている (sudah ada aturan bahwa ..., berlaku ketentuan ...)",coreWords:["かわいらしい【かわいらしい】 (indah; manis)","クラシック【クラシック】 (klasik)","詳しい【くわしい】 (knowing very well; detailed)","困難【こんなん】 (kesulitan; kesusahan)"],coreWarning:"Jangan memakai partikel kasual 〜dakke atau 〜damon saat berkoordinasi resmi dengan pimpinan direksi.",quickDialogue:"A: ブディさん、かわいらしいの 状況【じょうきょう】は... → B: はい、Yamadaさん！ この建物では、禁煙するこ..."}},"les-n3-u10-02":{pedagogical_framework:{what:{summary:"Rasa Batin, Keraguan Halus & Nada Percakapan (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ていただけますか, 〜させてください, 〜てもらえませんか, 〜てもらえますか dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ていただけますか dan 〜させてください secara mandiri.",targetPatterns:["〜ていただけますか (bisakah Anda ..., bolehkah saya meminta Anda ... (formal, sedikit lebih lunak))","〜させてください (izinkan saya ..., tolong biarkan saya melakukan ...)","〜てもらえませんか (bisakah kamu melakukan ... untukku, maukah kamu ... (kasual-menengah))","〜てもらえますか (maukah kamu ..., boleh minta tolong ... (kasual-menengah, bentuk positif))"],coreVocabSample:["わざわざ","せめて","たとえ","もし","かりに","おそらく","こうりつよく","まとめて"]},sensei_context:{sceneIntro:"Istirahat siang di kafetaria kantor bersama rekan kerja multinasional. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ていただけますか dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Rasa Batin, Keraguan Halus & Nada Percakapan",etiquette:"Gunakan ragam percakapan yang hangat namun tetap santun untuk mempererat keakraban antarstaf.",taboos:"Jangan memakai partikel kasual 〜dakke atau 〜damon saat berkoordinasi resmi dengan pimpinan direksi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ていただけますか",moraNote:"Ucapkan ki ga suru dengan nada mengambang ringan untuk menunjukkan firasat personal.",soundTip:"Ucapkan 〜ていただけますか dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ていただけますか",caseScenario:"Menggunakan 〜ていただけますか tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ていただけますか.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ていただけますか sesuai kaidah.",explanation:"Kaidah koneksi 〜ていただけますか: V-て + いただけますか."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Rasa Batin, Keraguan Halus & Nada Percakapan (Produksi Aktif & Aplikasi Nyata)",setting:"Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ていただけますか."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、わざわざの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、わざわざの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, wazawaza no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai sengaja, repot-repot, susah payah datang/melakukan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ ご確認いただけますか。。",furigana:"はい、Yamadaさん！ ご確認いただけますか。。",romaji:"Hai, Yamada-san! ていただけますか de susumete imasu.",idText:"Ya, Yamada! Bisakah Anda memverifikasinya?."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。少し考える時間をさせてください。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。少し考える時間をさせてください。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Izinkan saya berpikir sebentar.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00610",word:"わざわざ",reading:"わざわざ",romaji:"wazawaza",meaning:"sengaja, repot-repot, susah payah datang/melakukan",pos:"adverb-manner",nuance:"Menekankan bahwa seseorang telah melakukan upaya ekstra atau tindakan tidak diperlukan — bisa mengandung rasa terima kasih (わざわざ来てくれてありがとう) atau sindiran halus (わざわざそんなことしなくていい). Berbeda dari あえて yang menekankan keberanian — わざわざ lebih pada kerepotan atau tindakan yang melebihi kebutuhan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"わざわざを 確認【かくにん】します。",furigana:"わざわざを 確認します。",romaji:"wazawaza o kakunin shimasu.",idText:"Memeriksa sengaja, repot-repot, susah payah datang/melakukan."}},{id:"vg-n3-00611",word:"せめて",reading:"せめて",romaji:"semete",meaning:"setidaknya, paling tidak, minimal",pos:"adverb",nuance:"Mengungkapkan harapan minimal atau permintaan terkecil — pembicara sudah menerima bahwa idealnya tidak tercapai, lalu meminta syarat minimum. Berbeda dari少なくとも (yang bersifat faktual/kuantitatif) — せめて mengandung nuansa emosional, sering terasa seperti permohonan atau harapan terakhir.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"せめてを 確認【かくにん】します。",furigana:"せめてを 確認します。",romaji:"semete o kakunin shimasu.",idText:"Memeriksa setidaknya, paling tidak, minimal."}},{id:"vg-n3-00612",word:"たとえ",reading:"たとえ",romaji:"tatoe",meaning:"seandainya, meskipun, walaupun",pos:"adverb",nuance:"Selalu berpasangan dengan 〜ても atau 〜でも — tidak digunakan sendiri. Menekankan bahwa kondisi apapun tidak mengubah hasil. Berbeda dari もし (kondisional netral) — たとえ menyiratkan kontras yang kuat dan tekad, sering digunakan dalam ungkapan dramatis atau janji.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"たとえを 確認【かくにん】します。",furigana:"たとえを 確認します。",romaji:"tatoe o kakunin shimasu.",idText:"Memeriksa seandainya, meskipun, walaupun."}},{id:"vg-n3-00613",word:"もし",reading:"もし",romaji:"moshi",meaning:"seandainya, kalau, jika (kondisional)",pos:"adverb",nuance:"Menandai kondisi hipotetis yang masih mungkin terjadi — membuka klausa kondisional (〜たら/〜なら/〜ば). Berbeda dari 仮に (yang lebih bersifat counterfactual/andaikan) dan たとえ (yang menekankan ketidakpedulian terhadap kondisi apapun) — もし adalah bentuk kondisional paling umum dan netral.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"もしを 確認【かくにん】します。",furigana:"もしを 確認します。",romaji:"moshi o kakunin shimasu.",idText:"Memeriksa seandainya, kalau, jika (kondisional)."}},{id:"vg-n3-00614",word:"仮に",reading:"かりに",romaji:"kari ni",meaning:"misalkan, andaikan, seumpama (hipotesis)",pos:"adverb",nuance:"Lebih eksplisit bersifat hipotetis atau counterfactual dibanding もし — sering dipakai dalam argumen, debat, atau diskusi ilmiah ketika pembicara mengajukan skenario yang mungkin tidak nyata. Sering diikuti 〜としても (bahkan jika seandainya). もし lebih umum dan kasual; 仮に lebih terstruktur dan analitis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"仮に【かりに】を 確認【かくにん】します。",furigana:"仮にを 確認します。",romaji:"kari ni o kakunin shimasu.",idText:"Memeriksa misalkan, andaikan, seumpama (hipotesis)."}},{id:"vg-n3-00615",word:"おそらく",reading:"おそらく",romaji:"osoraku",meaning:"kemungkinan besar, mungkin, barangkali (formal)",pos:"adverb",nuance:"Menyatakan dugaan dengan tingkat kepercayaan yang cukup tinggi — lebih formal dan lebih confident dari たぶん. Sering muncul dalam tulisan, berita, atau percakapan setengah formal. たぶん lebih kasual dan sehari-hari, sedangkan おそらく terkesan lebih bijaksana atau analitis. Biasanya diikuti 〜だろう atau 〜と思われる.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"おそらくを 確認【かくにん】します。",furigana:"おそらくを 確認します。",romaji:"osoraku o kakunin shimasu.",idText:"Memeriksa kemungkinan besar, mungkin, barangkali (formal)."}},{id:"vg-n3-00731",word:"効率よく",reading:"こうりつよく",romaji:"kouritsu yoku",meaning:"dengan efisien, secara efektif tanpa boros",pos:"adverb-manner",nuance:"Bentuk adverbia dari 効率 (efisiensi) — menerangkan cara melakukan sesuatu dengan rasio hasil/usaha yang baik. Berbeda dari ただ速く (sekadar cepat); 効率よく menyiratkan bahwa hasilnya juga berkualitas, bukan sekadar buru-buru. Pasangan alaminya: 効率よく仕事する、効率よく勉強する.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"効率よく【こうりつよく】を 確認【かくにん】します。",furigana:"効率よくを 確認します。",romaji:"kouritsu yoku o kakunin shimasu.",idText:"Memeriksa dengan efisien, secara efektif tanpa boros."}},{id:"vg-n3-00732",word:"まとめて",reading:"まとめて",romaji:"matomete",meaning:"sekaligus, secara kolektif, dikumpulkan jadi satu",pos:"adverb-manner",nuance:"Menekankan penggabungan beberapa hal menjadi satu tindakan atau satu paket — efisiensi dengan menghindari pengulangan. Berbeda dari いっぺんに yang juga berarti 'sekaligus' tapi menekankan kebersamaan waktu; まとめて lebih menekankan penggabungan atau pengumpulan menjadi satu unit sebelum dikerjakan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"まとめてを 確認【かくにん】します。",furigana:"まとめてを 確認します。",romaji:"matomete o kakunin shimasu.",idText:"Memeriksa sekaligus, secara kolektif, dikumpulkan jadi satu."}}],explanations:[{id:"exp-1",grammarId:"gn3-00154",title:"Pola: 〜ていただけますか",formula:"V-て + いただけますか",meaning:"bisakah Anda ..., bolehkah saya meminta Anda ... (formal, sedikit lebih lunak)",nuanceNotes:"〜ていただけますか adalah versi positif (bentuk bertanya afirmatif) dari 〜ていただけませんか. Sama-sama formal dan menggunakan いただく sebagai kata kerja rendah hati, namun bentuk positif (〜ますか) terasa sedikit kurang melunak karena tidak memberikan peluang penolakan selonggar bentuk negatif. Tetap sangat sopan dan layak digunakan di lingkungan kerja formal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ていただけますか",idText:"bisakah Anda ..., bolehkah saya meminta Anda ... (formal, sedikit lebih lunak)"}],examples:[{jp:"ご確認いただけますか。",romaji:"",idText:"Bisakah Anda memverifikasinya?"},{jp:"この書類にサインしていただけますか。",romaji:"",idText:"Bisakah Anda menandatangani dokumen ini?"},{jp:"少し声を大きくしていただけますか。",romaji:"",idText:"Bisakah Anda berbicara sedikit lebih keras?"}]},{id:"exp-2",grammarId:"gn3-00156",title:"Pola: 〜させてください",formula:"V-stem (causative させ) + てください",meaning:"izinkan saya ..., tolong biarkan saya melakukan ...",nuanceNotes:'〜させてください adalah permohonan langsung untuk mendapat izin melakukan sesuatu. Menggabungkan bentuk kausatif (〜させる) dengan 〜てください, pola ini secara eksplisit meminta lawan bicara untuk "membiarkan" pembicara melakukan X. Lebih langsung dari 〜させていただく, namun masih cukup sopan untuk digunakan di berbagai situasi.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜させてください",idText:"izinkan saya ..., tolong biarkan saya melakukan ..."}],examples:[{jp:"少し考える時間をさせてください。",romaji:"",idText:"Izinkan saya berpikir sebentar."},{jp:"私に手伝わせてください。",romaji:"",idText:"Tolong biarkan saya membantu."},{jp:"もう一度やり直させてください。",romaji:"",idText:"Izinkan saya mencoba lagi dari awal."}]},{id:"exp-3",grammarId:"gn3-00157",title:"Pola: 〜てもらえませんか",formula:"V-て + もらえませんか",meaning:"bisakah kamu melakukan ... untukku, maukah kamu ... (kasual-menengah)",nuanceNotes:"〜てもらえませんか adalah bentuk permohonan kasual-menengah yang menggunakan もらう (menerima sesuatu dari orang lain). Berbeda dari いただく yang merupakan bentuk rendah hati, もらう adalah kata biasa sehingga pola ini tidak sekaku 〜ていただけませんか. Cocok digunakan kepada teman, kolega yang akrab, atau situasi yang tidak terlalu formal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てもらえませんか",idText:"bisakah kamu melakukan ... untukku, maukah kamu ... (kasual-menengah)"}],examples:[{jp:"ちょっと手伝ってもらえませんか。",romaji:"",idText:"Bisakah kamu membantuku sebentar?"},{jp:"これを田中さんに渡してもらえませんか。",romaji:"",idText:"Bisakah kamu menyampaikan ini kepada Pak Tanaka?"},{jp:"少し静かにしてもらえませんか。",romaji:"",idText:"Bisakah kamu sedikit lebih tenang?"}]},{id:"exp-4",grammarId:"gn3-00158",title:"Pola: 〜てもらえますか",formula:"V-て + もらえますか",meaning:"maukah kamu ..., boleh minta tolong ... (kasual-menengah, bentuk positif)",nuanceNotes:"〜てもらえますか adalah versi positif (afirmatif) dari 〜てもらえませんか. Keduanya termasuk dalam rentang permohonan kasual-menengah menggunakan もらう. Bentuk positif ini sedikit lebih langsung dibandingkan versi negatifnya, namun tetap sopan. Umum dipakai di percakapan sehari-hari antara teman, rekan kerja, atau di situasi semi-formal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てもらえますか",idText:"maukah kamu ..., boleh minta tolong ... (kasual-menengah, bentuk positif)"}],examples:[{jp:"もう一度読んでもらえますか。",romaji:"",idText:"Bisakah kamu membacanya sekali lagi?"},{jp:"これ、コピーしてもらえますか。",romaji:"",idText:"Bisakah kamu meng-copy ini?"},{jp:"駅まで送ってもらえますか。",romaji:"",idText:"Maukah kamu mengantarku ke stasiun?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "わざわざ"?',sentencePrompt:'Makna kata "わざわざ" (わざわざ) dalam situasi kerja ini adalah:',options:["sengaja, repot-repot, susah payah datang/melakukan","setidaknya, paling tidak, minimal","seandainya, meskipun, walaupun","seandainya, kalau, jika (kondisional)"],correctAnswer:"sengaja, repot-repot, susah payah datang/melakukan",explanation:'Makna yang tepat untuk "わざわざ" adalah "sengaja, repot-repot, susah payah datang/melakukan".',diagnosticFeedback:{"setidaknya, paling tidak, minimal":'Salah: Pilihan "setidaknya, paling tidak, minimal" adalah makna dari kata "せめて" (せめて), bukan arti kata "わざわざ".',"seandainya, meskipun, walaupun":'Salah: Pilihan "seandainya, meskipun, walaupun" adalah makna dari kata "たとえ" (たとえ), bukan arti kata "わざわざ".',"seandainya, kalau, jika (kondisional)":'Salah: Pilihan "seandainya, kalau, jika (kondisional)" adalah makna dari kata "もし" (もし), bukan arti kata "わざわざ".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"ご確認（　　）。",options:["いただけますか","させてください","てもらえませんか","といいですね"],correctAnswer:"いただけますか",explanation:'Pola 〜ていただけますか bermakna "bisakah Anda ..., bolehkah saya meminta Anda ... (formal, sedikit lebih lunak)". Kalimat lengkap: "ご確認いただけますか。".',diagnosticFeedback:{させてください:'Salah: Pola "させてください" bermakna "izinkan saya ..., tolong biarkan saya melakukan ...", yang tidak sesuai konteks kalimat ini.',てもらえませんか:'Salah: Pola "てもらえませんか" bermakna "bisakah kamu melakukan ... untukku, maukah kamu ... (kasual-menengah)", yang tidak sesuai konteks kalimat ini.',といいですね:'Salah: Pola "といいですね" bermakna "semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ていただけますか secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["この書類にサインしていただけますか。","この書類にサインしていただけますかでした。","少し考える時間をさせてください。","毎日練習した。その結果、大会で優勝できた。"],correctAnswer:"この書類にサインしていただけますか。",explanation:'Kalimat yang benar dan alami adalah "この書類にサインしていただけますか。" (Bisakah Anda menandatangani dokumen ini?).',diagnosticFeedback:{"この書類にサインしていただけますかでした。":"Jebakan Konjugasi: Pola 〜ていただけますか membutuhkan aturan sambung (V-て + いただけますか), bukan bentuk ini.","少し考える時間をさせてください。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜させてください: izinkan saya ..., tolong biarkan saya melakukan ...), bukan kaidah 〜ていただけますか.","毎日練習した。その結果、大会で優勝できた。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ていただけますか secara tepat (bisakah Anda ..., bolehkah saya meminta Anda ... (formal, sedikit lebih lunak))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["少し 考える 時間を させてください。","考える 少し 時間を させてください。","少し 時間を 考える させてください。","させてください。 少し 考える 時間を"],correctAnswer:"少し 考える 時間を させてください。",explanation:'Susunan yang benar: "少し 考える 時間を させてください。" (Izinkan saya berpikir sebentar.).',diagnosticFeedback:{"考える 少し 時間を させてください。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","少し 時間を 考える させてください。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","させてください。 少し 考える 時間を":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["少し","考える","時間を","させてください。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.", saat Yamada menyampaikan arahan: 「なるほど。少し考える時間をさせてください。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ていただけますか dan 〜させてください secara mandiri.",situation:"Situasi komunikasi profesional di Istirahat siang di kafetaria kantor bersama rekan kerja multinasional.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ていただけますか!",modelAnswer:"はい、Yamadaさん！ ご確認いただけますか。。",modelAnswerId:"Ya, Yamada! Bisakah Anda memverifikasinya?.",culturalEtiquette:"Gunakan ragam percakapan yang hangat namun tetap santun untuk mempererat keakraban antarstaf.",skillUnlocked:["Menguasai formulasi pola 〜ていただけますか","Mampu menerapkan prinsip koordinasi komunikasi kerja Rasa Batin, Keraguan Halus & Nada Percakapan"]},pocket_summary:{keyFormula:"〜ていただけますか (bisakah Anda ..., bolehkah saya meminta Anda ... (formal, sedikit lebih lunak))",coreWords:["わざわざ【わざわざ】 (sengaja, repot-repot, susah payah datang/melakukan)","せめて【せめて】 (setidaknya, paling tidak, minimal)","たとえ【たとえ】 (seandainya, meskipun, walaupun)","もし【もし】 (seandainya, kalau, jika (kondisional))"],coreWarning:"Jangan memakai partikel kasual 〜dakke atau 〜damon saat berkoordinasi resmi dengan pimpinan direksi.",quickDialogue:"A: ブディさん、わざわざの 状況【じょうきょう】は ど... → B: はい、Yamadaさん！ ご確認いただけますか。。..."}}},i={"les-n3-u11-01":{pedagogical_framework:{what:{summary:"Permohonan Santun, Ajakan Kerja & Doa Harapan (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜といいですね, 〜といいですが, 〜わけがない, 〜はずがない, 〜はずだ dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜といいですね dan 〜といいですが dalam percakapan kerja wajar.",targetPatterns:["〜といいですね (semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain))","〜といいですが (semoga saja ..., mudah-mudahan ya ... (harapan disertai sedikit kekhawatiran))","〜わけがない (tidak mungkin ..., mustahil ..., tidak ada alasannya ...)","〜はずがない (tidak seharusnya ..., tidak mungkin ... (berdasarkan ekspektasi yang ada))","〜はずだ (seharusnya ..., mestinya ..., sudah semestinya ...)"],coreVocabSample:["たまたま","たんに","ちかごろ","つぎつぎ","つねに","どうしても","どこか","とにかく"]},sensei_context:{sceneIntro:"Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜といいですね dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Permohonan Santun, Ajakan Kerja & Doa Harapan",etiquette:"Membungkuk hormat (Ojigi 30 derajat) saat mengucapkan permohonan santun itadakemasen ka.",taboos:"Jangan gunakan 〜te goran kepada orang yang lebih tua atau statusnya lebih tinggi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜といいですね",moraNote:"Lembutkan desisan mora terakhir ka pada permohonan santun tanpa nada menuntut.",soundTip:"Ucapkan 〜といいですね dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜といいですね",caseScenario:"Menggunakan 〜といいですね tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜といいですね.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜といいですね sesuai kaidah.",explanation:"Kaidah koneksi 〜といいですね: V-dict / い-Adj / な-Adj (な) + といいですね."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Permohonan Santun, Ajakan Kerja & Doa Harapan (Fondasi & Pemahaman Pola)",setting:"Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 〜といいですね."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、偶々の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、偶々の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, tamatama no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai kebetulan, secara tidak sengaja, tanpa direncanakan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ 試験、うまくいくといいですね。。",furigana:"はい、Yamadaさん！ 試験、うまくいくといいですね。。",romaji:"Hai, Yamada-san! といいですね de susumete imasu.",idText:"Ya, Yamada! Semoga ujiannya berjalan lancar ya.."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。天気が崩れないといいですが。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。天気が崩れないといいですが。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Semoga saja cuacanya tidak memburuk ya.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01849",word:"偶々",reading:"たまたま",romaji:"tamatama",meaning:"kebetulan, secara tidak sengaja, tanpa direncanakan",pos:"adverb",nuance:"Menyatakan bahwa peristiwa terjadi semata-mata karena faktor kebetulan (koinsidensi), tanpa niat, motif khusus, ataupun perencanaan awal. Berbeda dengan たまに (tamani) yang menyatakan frekuensi waktu (sesekali), たまたま menekankan bahwa peristiwanya terjadi secara tak terduga pada waktu tersebut.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"偶々【たまたま】を 確認【かくにん】します。",furigana:"偶々を 確認します。",romaji:"tamatama o kakunin shimasu.",idText:"Memeriksa kebetulan, secara tidak sengaja, tanpa direncanakan."}},{id:"vg-n3-01863",word:"単に",reading:"たんに",romaji:"tanni",meaning:"semata-mata, sekadar, hanya",pos:"adverb",nuance:"Kata keterangan (adverb) yang membatasi alasan atau kondisi, sering berpasangan dengan pola 〜だけでなく (tidak hanya sekadar...) atau 〜に過ぎない (tidak lebih dari sekadar...). Berbeda dengan 単なる (tannaru) yang menempel langsung sebelum nomina, 単に berfungsi sebagai adverbia untuk menerangkan verba, adjektiva, atau kalimat secara utuh.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"単に【たんに】を 確認【かくにん】します。",furigana:"単にを 確認します。",romaji:"tanni o kakunin shimasu.",idText:"Memeriksa semata-mata, sekadar, hanya."}},{id:"vg-n3-01872",word:"近頃",reading:"ちかごろ",romaji:"chikagoro",meaning:"akhir-akhir ini, belakangan ini, dewasa ini",pos:"adverb",nuance:"Menyatakan kurun waktu terkini yang membentang dari beberapa waktu lampau hingga saat ini (contoh: 近頃の若者 = pemuda zaman sekarang; 近頃は忙しい = akhir-akhir ini sibuk). Sering mengandung pengamatan terhadap tren atau perubahan kondisi yang sedang berlangsung. Sangat mirip dengan 最近 (saikin), namun 近頃 sedikit lebih bernuansa percakapan atau refleksi atas keadaan sekitar.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"近頃【ちかごろ】を 確認【かくにん】します。",furigana:"近頃を 確認します。",romaji:"chikagoro o kakunin shimasu.",idText:"Memeriksa akhir-akhir ini, belakangan ini, dewasa ini."}},{id:"vg-n3-01910",word:"次々",reading:"つぎつぎ",romaji:"tsugitsugi",meaning:"satu demi satu, berturut-turut, silih berganti",pos:"adverb",nuance:"Menggambarkan peristiwa, orang, atau objek yang datang atau terjadi satu demi satu tanpa jeda yang lama. Sering dipakai dalam bentuk adverbia 次々に (tsugitsugi ni) atau 次々と (tsugitsugi to). Memberikan kesan kelancaran atau kesinambungan peristiwa yang beruntun.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"次々【つぎつぎ】を 確認【かくにん】します。",furigana:"次々を 確認します。",romaji:"tsugitsugi o kakunin shimasu.",idText:"Memeriksa satu demi satu, berturut-turut, silih berganti."}},{id:"vg-n3-01920",word:"常に",reading:"つねに",romaji:"tsuneni",meaning:"selalu, senantiasa, tak henti-hentinya",pos:"adverb",nuance:"Bermakna selalu tanpa putus dalam setiap keadaan. Bersifat formal dan bernuansa ragam tulisan atau ungkapan penuh kesungguhan. Berbeda dengan いつも (itsumo) yang sangat santai dan lazim dalam obrolan sehari-hari, 常に lebih umum ditemukan dalam pedoman kerja, peribahasa, atau tulisan esai.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"常に【つねに】を 確認【かくにん】します。",furigana:"常にを 確認します。",romaji:"tsuneni o kakunin shimasu.",idText:"Memeriksa selalu, senantiasa, tak henti-hentinya."}},{id:"vg-n3-01969",word:"どうしても",reading:"どうしても",romaji:"doushitemo",meaning:"bagaimanapun juga, bagaimanapun caranya, mau tidak mau",pos:"adverb",nuance:"Adverbia penegas dengan dua pemakaian pokok: 1) Menyatakan tekad bulat membara yang pantang menyerah untuk mencapai suatu tujuan apa pun taruhannya (diikuti bentuk keinginan: どうしても行きたい); 2) Menyatakan rasa putus asa atau kebuntuan daya upaya meskipun telah berusaha sekeras tenaga (diikuti bentuk negatif: どうしても解けない). Berbeda dengan 是非 (zehi) yang sekadar harapan ramah, どうしても menyiratkan desakan batin yang mutlak.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"どうしてもを 確認【かくにん】します。",furigana:"どうしてもを 確認します。",romaji:"doushitemo o kakunin shimasu.",idText:"Memeriksa bagaimanapun juga, bagaimanapun caranya, mau tidak mau."}},{id:"vg-n3-01990",word:"どこか",reading:"どこか",romaji:"dokoka",meaning:"suatu tempat, entah di mana, entah kenapa/ada bagian tertentu",pos:"adverb",nuance:"Gabungan kata tanya どこ dengan partikel tak tentu か. Bisa merujuk pada lokasi yang tidak ditentukan secara spesifik ('di suatu tempat'), atau secara figuratif merujuk pada bagian/aspek tertentu yang samar-samar dirasakan dari seseorang atau sesuatu ('entah mengapa rasanya... / ada bagian yang...').",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"どこかを 確認【かくにん】します。",furigana:"どこかを 確認します。",romaji:"dokoka o kakunin shimasu.",idText:"Memeriksa suatu tempat, entah di mana, entah kenapa/ada bagian tertentu."}},{id:"vg-n3-02000",word:"とにかく",reading:"とにかく",romaji:"tonikaku",meaning:"pokoknya, bagaimanapun juga, yang terpenting",pos:"adverb",nuance:"Digunakan untuk mengesampingkan rincian lain atau perdebatan yang rumit, dan mengajak lawan bicara untuk memprioritaskan tindakan yang paling mendesak sekarang juga. Berbeda dengan ともかく yang sedikit lebih formal dan netral, とにかく sangat umum dalam percakapan lisan sehari-hari untuk menegaskan: 'terlepas dari segalanya, yang paling utama saat ini adalah...'",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"とにかくを 確認【かくにん】します。",furigana:"とにかくを 確認します。",romaji:"tonikaku o kakunin shimasu.",idText:"Memeriksa pokoknya, bagaimanapun juga, yang terpenting."}}],explanations:[{id:"exp-1",grammarId:"gn3-00168",title:"Pola: 〜といいですね",formula:"V-dict / い-Adj / な-Adj (な) + といいですね",meaning:"semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain)",nuanceNotes:"〜といいですね menyatakan harapan yang hangat dan optimis terhadap sesuatu yang diinginkan orang lain — atau bersama lawan bicara. ですね di akhir menunjukkan bahwa pembicara mengajak lawan bicara merasakan harapan tersebut bersama-sama. Nuansanya positif dan penuh dukungan, sering dipakai sebagai ungkapan simpati atau dorongan semangat.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜といいですね",idText:"semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain)"}],examples:[{jp:"試験、うまくいくといいですね。",romaji:"",idText:"Semoga ujiannya berjalan lancar ya."},{jp:"早く元気になるといいですね。",romaji:"",idText:"Mudah-mudahan kamu cepat pulih ya."},{jp:"旅行、楽しいといいですね。",romaji:"",idText:"Semoga perjalanannya menyenangkan ya."}]},{id:"exp-2",grammarId:"gn3-00169",title:"Pola: 〜といいですが",formula:"V-dict / い-Adj / な-Adj (な) + といいですが",meaning:"semoga saja ..., mudah-mudahan ya ... (harapan disertai sedikit kekhawatiran)",nuanceNotes:"〜といいですが menyatakan harapan yang disertai dengan kekhawatiran ringan atau keraguan — pembicara berharap sesuatu terjadi, namun tidak sepenuhnya yakin. が di akhir berfungsi sebagai partikel kontrastif yang menyisakan ruang untuk kemungkinan sebaliknya. Pola ini terasa lebih hati-hati dan realistis dibandingkan 〜といいですね.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜といいですが",idText:"semoga saja ..., mudah-mudahan ya ... (harapan disertai sedikit kekhawatiran)"}],examples:[{jp:"天気が崩れないといいですが。",romaji:"",idText:"Semoga saja cuacanya tidak memburuk ya."},{jp:"渋滞に巻き込まれないといいですが。",romaji:"",idText:"Mudah-mudahan tidak terjebak macet, tapi ya khawatir juga."},{jp:"手術がうまくいくといいですが、心配ですね。",romaji:"",idText:"Semoga operasinya berhasil, tapi kami khawatir ya."}]},{id:"exp-3",grammarId:"gn3-00173",title:"Pola: 〜わけがない",formula:"V-plain / い-Adj / な-Adj (な) / N (な) + わけがない",meaning:"tidak mungkin ..., mustahil ..., tidak ada alasannya ...",nuanceNotes:'〜わけがない menyatakan bahwa suatu hal adalah mustahil secara logis atau faktual — tidak ada alasan apapun untuk itu bisa terjadi. わけ berarti "alasan/dasar", sehingga わけがない berarti "tidak ada alasan (untuk itu terjadi)". Digunakan untuk menyatakan penolakan keras terhadap suatu kemungkinan.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜わけがない",idText:"tidak mungkin ..., mustahil ..., tidak ada alasannya ..."}],examples:[{jp:"彼女がそんな嘘をつくわけがない。",romaji:"",idText:"Mustahil dia mau berbohong seperti itu."},{jp:"一夜漬けで合格できるわけがない。",romaji:"",idText:"Tidak mungkin bisa lulus hanya dengan belajar semalam."},{jp:"こんな難しい問題、私に解けるわけがない。",romaji:"",idText:"Mustahil aku bisa memecahkan soal sesulit ini."}]},{id:"exp-4",grammarId:"gn3-00174",title:"Pola: 〜はずがない",formula:"V-plain / い-Adj / な-Adj (な) / N (の) + はずがない",meaning:"tidak seharusnya ..., tidak mungkin ... (berdasarkan ekspektasi yang ada)",nuanceNotes:'〜はずがない menyatakan bahwa suatu hal tidak seharusnya terjadi berdasarkan logika, pengetahuan, atau ekspektasi yang pembicara miliki tentang situasi spesifik tersebut. はず mengandung arti "seharusnya / semestinya", sehingga はずがない = "tidak ada alasan itu seharusnya terjadi". Pola ini lebih kontekstual dibandingkan 〜わけがない.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜はずがない",idText:"tidak seharusnya ..., tidak mungkin ... (berdasarkan ekspektasi yang ada)"}],examples:[{jp:"彼は正直者だから、うそをつくはずがない。",romaji:"",idText:"Karena dia orang jujur, tidak mungkin dia berbohong."},{jp:"昨日届いた荷物が、もう壊れているはずがない。",romaji:"",idText:"Paket yang baru tiba kemarin tidak mungkin sudah rusak."},{jp:"こんな基本的なことを彼が知らないはずがない。",romaji:"",idText:"Tidak mungkin dia tidak tahu hal yang seprementer ini."}]},{id:"exp-5",grammarId:"gn3-00175",title:"Pola: 〜はずだ",formula:"V-plain / い-Adj / な-Adj (な) / N (の) + はずだ",meaning:"seharusnya ..., mestinya ..., sudah semestinya ...",nuanceNotes:"〜はずだ menyatakan bahwa pembicara memiliki ekspektasi logis atau keyakinan berdasarkan bukti/pengetahuan bahwa sesuatu semestinya terjadi atau benar. Berbeda dari 〜はずがない, pola ini mengonfirmasi kemungkinan positif. Pembicara tidak menyaksikan langsung, namun menyimpulkan berdasarkan informasi yang dimiliki.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜はずだ",idText:"seharusnya ..., mestinya ..., sudah semestinya ..."}],examples:[{jp:"彼はもう家に着いているはずだ。",romaji:"",idText:"Dia seharusnya sudah sampai di rumah sekarang."},{jp:"説明書通りにやれば、動くはずだ。",romaji:"",idText:"Kalau dilakukan sesuai petunjuk, mestinya bisa berjalan."},{jp:"昨日送ったから、今日届くはずだ。",romaji:"",idText:"Karena dikirim kemarin, seharusnya hari ini sampai."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "偶々"?',sentencePrompt:'Makna kata "偶々" (たまたま) dalam situasi kerja ini adalah:',options:["kebetulan, secara tidak sengaja, tanpa direncanakan","semata-mata, sekadar, hanya","akhir-akhir ini, belakangan ini, dewasa ini","satu demi satu, berturut-turut, silih berganti"],correctAnswer:"kebetulan, secara tidak sengaja, tanpa direncanakan",explanation:'Makna yang tepat untuk "偶々" adalah "kebetulan, secara tidak sengaja, tanpa direncanakan".',diagnosticFeedback:{"semata-mata, sekadar, hanya":'Salah: Pilihan "semata-mata, sekadar, hanya" adalah makna dari kata "単に" (たんに), bukan arti kata "偶々".',"akhir-akhir ini, belakangan ini, dewasa ini":'Salah: Pilihan "akhir-akhir ini, belakangan ini, dewasa ini" adalah makna dari kata "近頃" (ちかごろ), bukan arti kata "偶々".',"satu demi satu, berturut-turut, silih berganti":'Salah: Pilihan "satu demi satu, berturut-turut, silih berganti" adalah makna dari kata "次々" (つぎつぎ), bukan arti kata "偶々".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"試験、うまくいく（　　）。",options:["といいですね","といいですが","わけがない","だろう / 〜でしょう"],correctAnswer:"といいですね",explanation:'Pola 〜といいですね bermakna "semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain)". Kalimat lengkap: "試験、うまくいくといいですね。".',diagnosticFeedback:{といいですが:'Salah: Pola "といいですが" bermakna "semoga saja ..., mudah-mudahan ya ... (harapan disertai sedikit kekhawatiran)", yang tidak sesuai konteks kalimat ini.',わけがない:'Salah: Pola "わけがない" bermakna "tidak mungkin ..., mustahil ..., tidak ada alasannya ...", yang tidak sesuai konteks kalimat ini.',"だろう / 〜でしょう":'Salah: Pola "だろう / 〜でしょう" bermakna "mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜といいですね secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["早く元気になるといいですね。","早く元気になるといいですねでした。","天気が崩れないといいですが。","父が来られないかわりに、兄が来ました。"],correctAnswer:"早く元気になるといいですね。",explanation:'Kalimat yang benar dan alami adalah "早く元気になるといいですね。" (Mudah-mudahan kamu cepat pulih ya.).',diagnosticFeedback:{"早く元気になるといいですねでした。":"Jebakan Konjugasi: Pola 〜といいですね membutuhkan aturan sambung (V-dict / い-Adj / な-Adj (な) + といいですね), bukan bentuk ini.","天気が崩れないといいですが。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜といいですが: semoga saja ..., mudah-mudahan ya ... (harapan disertai sedikit kekhawatiran)), bukan kaidah 〜といいですね.","父が来られないかわりに、兄が来ました。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜といいですね secara tepat (semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["天気が 崩れない といいで すが。","崩れない 天気が といいで すが。","天気が といいで 崩れない すが。","すが。 天気が 崩れない といいで"],correctAnswer:"天気が 崩れない といいで すが。",explanation:'Susunan yang benar: "天気が 崩れない といいで すが。" (Semoga saja cuacanya tidak memburuk ya.).',diagnosticFeedback:{"崩れない 天気が といいで すが。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","天気が といいで 崩れない すが。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","すが。 天気が 崩れない といいで":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["天気が","崩れない","といいで","すが。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.", saat Yamada menyampaikan arahan: 「なるほど。天気が崩れないといいですが。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜といいですね dan 〜といいですが dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜といいですね!",modelAnswer:"はい、Yamadaさん！ 試験、うまくいくといいですね。。",modelAnswerId:"Ya, Yamada! Semoga ujiannya berjalan lancar ya..",culturalEtiquette:"Membungkuk hormat (Ojigi 30 derajat) saat mengucapkan permohonan santun itadakemasen ka.",skillUnlocked:["Menguasai formulasi pola 〜といいですね","Mampu menerapkan prinsip koordinasi komunikasi kerja Permohonan Santun, Ajakan Kerja & Doa Harapan"]},pocket_summary:{keyFormula:"〜といいですね (semoga ..., mudah-mudahan ... (mengungkapkan harapan baik untuk orang lain))",coreWords:["偶々【たまたま】 (kebetulan, secara tidak sengaja, tanpa direncanakan)","単に【たんに】 (semata-mata, sekadar, hanya)","近頃【ちかごろ】 (akhir-akhir ini, belakangan ini, dewasa ini)","次々【つぎつぎ】 (satu demi satu, berturut-turut, silih berganti)"],coreWarning:"Jangan gunakan 〜te goran kepada orang yang lebih tua atau statusnya lebih tinggi.",quickDialogue:"A: ブディさん、偶々の 状況【じょうきょう】は どうで... → B: はい、Yamadaさん！ 試験、うまくいくといいで..."}},"les-n3-u11-02":{pedagogical_framework:{what:{summary:"Permohonan Santun, Ajakan Kerja & Doa Harapan (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜はずだった, 〜に決まっている, 〜に違いない, 〜かもしれない dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜はずだった dan 〜に決まっている secara mandiri.",targetPatterns:["〜はずだった (seharusnya ... (tapi tidak terjadi), semestinya ... (tapi meleset))","〜に決まっている (pasti ..., sudah pasti ..., tidak diragukan lagi ... (keyakinan kuat subjektif))","〜に違いない (pasti ..., tidak mungkin selain ... (kesimpulan logis yang hampir pasti))","〜かもしれない (mungkin ..., bisa jadi ..., barangkali ...)"],coreVocabSample:["たいど","しらせ","さいきん","さいしょ","さいご","とちゅう","そのご／そのあと","それまで"]},sensei_context:{sceneIntro:"Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜はずだった dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Permohonan Santun, Ajakan Kerja & Doa Harapan",etiquette:"Membungkuk hormat (Ojigi 30 derajat) saat mengucapkan permohonan santun itadakemasen ka.",taboos:"Jangan gunakan 〜te goran kepada orang yang lebih tua atau statusnya lebih tinggi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜はずだった",moraNote:"Lembutkan desisan mora terakhir ka pada permohonan santun tanpa nada menuntut.",soundTip:"Ucapkan 〜はずだった dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜はずだった",caseScenario:"Menggunakan 〜はずだった tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜はずだった.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜はずだった sesuai kaidah.",explanation:"Kaidah koneksi 〜はずだった: V-plain / い-Adj / な-Adj (な) / N (の) + はずだった."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Permohonan Santun, Ajakan Kerja & Doa Harapan (Produksi Aktif & Aplikasi Nyata)",setting:"Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 〜はずだった."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、態度の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、態度の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, taido no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai sikap, perilaku, cara bersikap? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ 3時に来るはずだったのに、まだ来ない。。",furigana:"はい、Yamadaさん！ 3時に来るはずだったのに、まだ来ない。。",romaji:"Hai, Yamada-san! はずだった de susumete imasu.",idText:"Ya, Yamada! Seharusnya dia datang jam 3, tapi sampai sekarang belum muncul.."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。こんなに遅いんだから、迷っているに決まっている。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。こんなに遅いんだから、迷っているに決まっている。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Sudah selambat ini, pasti dia sedang tersesat.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00285",word:"態度",reading:"たいど",romaji:"taido",meaning:"sikap, perilaku, cara bersikap",pos:"noun",nuance:"Cara seseorang berperilaku atau bersikap, terutama yang terlihat dari luar. Beda dari 性格 (kepribadian bawaan). 態度を改める (memperbaiki sikap) sangat umum dipakai di konteks kerja dan pendidikan. Bisa positif maupun negatif.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"態度【たいど】を 確認【かくにん】します。",furigana:"態度を 確認します。",romaji:"taido o kakunin shimasu.",idText:"Memeriksa sikap, perilaku, cara bersikap."}},{id:"vg-n3-00319",word:"知らせ",reading:"しらせ",romaji:"shirase",meaning:"pemberitahuan, kabar, berita",pos:"noun",nuance:"Bentuk kata benda dari 知らせる. Sering muncul dalam frasa 嬉しい知らせ (kabar gembira) atau 悲しい知らせ (kabar sedih). Terasa lebih personal dari お知らせ yang bersifat resmi/publik.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"知らせ【しらせ】を 確認【かくにん】します。",furigana:"知らせを 確認します。",romaji:"shirase o kakunin shimasu.",idText:"Memeriksa pemberitahuan, kabar, berita."}},{id:"vg-n3-00346",word:"最近",reading:"さいきん",romaji:"saikin",meaning:"belakangan ini, baru-baru ini",pos:"noun-temporal",nuance:"Merujuk pada periode waktu dekat di masa lalu; bisa berfungsi sebagai subjek atau keterangan. Berbeda dari 先日 yang lebih spesifik dan formal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"最近【さいきん】を 確認【かくにん】します。",furigana:"最近を 確認します。",romaji:"saikin o kakunin shimasu.",idText:"Memeriksa belakangan ini, baru-baru ini."}},{id:"vg-n3-00347",word:"最初",reading:"さいしょ",romaji:"saisho",meaning:"pertama, awal, pada mulanya",pos:"noun-temporal",nuance:"Menunjukkan titik paling awal dalam urutan kejadian. Pola 最初に = pertama-tama (dalam instruksi). Berbeda dari 初め yang lebih umum dan 当初 yang lebih formal serta menekankan kondisi semula.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"最初【さいしょ】を 確認【かくにん】します。",furigana:"最初を 確認します。",romaji:"saisho o kakunin shimasu.",idText:"Memeriksa pertama, awal, pada mulanya."}},{id:"vg-n3-00348",word:"最後",reading:"さいご",romaji:"saigo",meaning:"terakhir, akhir, pada akhirnya",pos:"noun-temporal",nuance:"Menunjukkan titik paling akhir dari suatu rangkaian. 最後に = terakhir sekali / pada akhirnya. Juga bisa bermakna emosional seperti momen perpisahan terakhir yang dramatis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"最後【さいご】を 確認【かくにん】します。",furigana:"最後を 確認します。",romaji:"saigo o kakunin shimasu.",idText:"Memeriksa terakhir, akhir, pada akhirnya."}},{id:"vg-n3-00349",word:"途中",reading:"とちゅう",romaji:"tochuu",meaning:"di tengah jalan, belum selesai, di tengah-tengah",pos:"noun-temporal",nuance:"Menunjukkan proses yang belum selesai, baik secara waktu (di tengah mengerjakan sesuatu) maupun perjalanan (di tengah jalan). Pola 途中で = di tengah-tengah. Sering menyiratkan bahwa sesuatu terhenti sebelum selesai.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"途中【とちゅう】を 確認【かくにん】します。",furigana:"途中を 確認します。",romaji:"tochuu o kakunin shimasu.",idText:"Memeriksa di tengah jalan, belum selesai, di tengah-tengah."}},{id:"vg-n3-00360",word:"その後",reading:"そのご／そのあと",romaji:"sono go / sono ato",meaning:"setelah itu, sesudahnya, sesudah kejadian itu",pos:"noun-temporal",nuance:"Merujuk pada periode setelah suatu kejadian yang sudah disebutkan. Lebih formal dari それから dan lebih sering dipakai dalam narasi tulisan. Pengucapan そのご lebih formal, そのあと lebih kasual — keduanya umum.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"その後【そのご／そのあと】を 確認【かくにん】します。",furigana:"その後を 確認します。",romaji:"sono go / sono ato o kakunin shimasu.",idText:"Memeriksa setelah itu, sesudahnya, sesudah kejadian itu."}},{id:"vg-n3-00361",word:"それまで",reading:"それまで",romaji:"sore made",meaning:"sampai saat itu, hingga waktu itu",pos:"noun-temporal",nuance:"Merujuk pada periode sebelum titik waktu tertentu yang sudah disebutkan. Ketika dipakai di akhir kalimat (それまでだ), artinya bergeser menjadi 'sudah selesai di situ' atau 'tidak ada harapan lagi' — nuansa pesimis yang perlu diperhatikan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"それまでを 確認【かくにん】します。",furigana:"それまでを 確認します。",romaji:"sore made o kakunin shimasu.",idText:"Memeriksa sampai saat itu, hingga waktu itu."}}],explanations:[{id:"exp-1",grammarId:"gn3-00176",title:"Pola: 〜はずだった",formula:"V-plain / い-Adj / な-Adj (な) / N (の) + はずだった",meaning:"seharusnya ... (tapi tidak terjadi), semestinya ... (tapi meleset)",nuanceNotes:"〜はずだった adalah bentuk lampau dari 〜はずだ, digunakan untuk menyatakan ekspektasi atau rencana yang seharusnya terjadi di masa lalu, namun pada kenyataannya tidak terpenuhi. Pola ini sering mengandung nuansa kekecewaan, kejutan, atau penyesalan — ada kontras antara ekspektasi dan kenyataan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜はずだった",idText:"seharusnya ... (tapi tidak terjadi), semestinya ... (tapi meleset)"}],examples:[{jp:"3時に来るはずだったのに、まだ来ない。",romaji:"",idText:"Seharusnya dia datang jam 3, tapi sampai sekarang belum muncul."},{jp:"今日は休めるはずだったが、急な仕事が入った。",romaji:"",idText:"Seharusnya hari ini aku bisa istirahat, tapi tiba-tiba ada pekerjaan mendadak."},{jp:"この計画はうまくいくはずだった。",romaji:"",idText:"Rencana ini seharusnya berjalan dengan baik."}]},{id:"exp-2",grammarId:"gn3-00177",title:"Pola: 〜に決まっている",formula:"V-plain / い-Adj / な-Adj / N + に決まっている",meaning:"pasti ..., sudah pasti ..., tidak diragukan lagi ... (keyakinan kuat subjektif)",nuanceNotes:'〜に決まっている menyatakan keyakinan sangat kuat pembicara bahwa sesuatu pasti benar atau pasti terjadi — seolah "sudah diputuskan demikian". Berbeda dari pola kepastian lain, 〜に決まっている sering mengandung unsur emosional atau intuitif — pembicara sangat yakin meski belum tentu berdasarkan bukti yang kuat.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に決まっている",idText:"pasti ..., sudah pasti ..., tidak diragukan lagi ... (keyakinan kuat subjektif)"}],examples:[{jp:"こんなに遅いんだから、迷っているに決まっている。",romaji:"",idText:"Sudah selambat ini, pasti dia sedang tersesat."},{jp:"あんなに一生懸命やっているんだから、合格するに決まっているよ。",romaji:"",idText:"Sudah bekerja sekeras itu, pasti lulus lah!"},{jp:"彼女が怒っているに決まっているじゃないか。",romaji:"",idText:"Sudah jelas dia marah, kan?"}]},{id:"exp-3",grammarId:"gn3-00178",title:"Pola: 〜に違いない",formula:"V-plain / い-Adj / な-Adj / N + に違いない",meaning:"pasti ..., tidak mungkin selain ... (kesimpulan logis yang hampir pasti)",nuanceNotes:'〜に違いない menyatakan keyakinan kuat berdasarkan deduksi logis — pembicara menyimpulkan sesuatu hampir pasti benar berdasarkan bukti atau situasi yang ada. 違いない berarti "tidak ada kekeliruan", sehingga ekspresinya adalah "pasti demikian, tidak mungkin salah". Lebih formal dan analitis dari 〜に決まっている.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に違いない",idText:"pasti ..., tidak mungkin selain ... (kesimpulan logis yang hampir pasti)"}],examples:[{jp:"光の速さで動くものは存在しないに違いない。",romaji:"",idText:"Pasti tidak ada benda yang bergerak secepat cahaya."},{jp:"財布が見当たらない。落としてきたに違いない。",romaji:"",idText:"Dompet tidak ada. Pasti terjatuh di jalan tadi."},{jp:"彼がこんなに急いでいるのは、理由があるに違いない。",romaji:"",idText:"Pasti ada alasannya mengapa dia terburu-buru seperti ini."}]},{id:"exp-4",grammarId:"gn3-00179",title:"Pola: 〜かもしれない",formula:"V-plain / い-Adj / な-Adj (stem) / N + かもしれない",meaning:"mungkin ..., bisa jadi ..., barangkali ...",nuanceNotes:'〜かもしれない menyatakan kemungkinan yang tidak pasti — pembicara menduga sesuatu mungkin benar, namun tidak yakin. かも berasal dari か (pertanyaan) + も (juga), sehingga mengandung arti "ada kemungkinan itu benar, tapi tidak pasti". Pola ini sangat umum dan penting dalam bahasa Jepang sehari-hari untuk mengungkapkan ketidakpastian secara sopan.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜かもしれない",idText:"mungkin ..., bisa jadi ..., barangkali ..."}],examples:[{jp:"明日は雨が降るかもしれない。",romaji:"",idText:"Besok mungkin akan hujan."},{jp:"彼女はもう帰ったかもしれない。",romaji:"",idText:"Bisa jadi dia sudah pulang."},{jp:"私の思い違いかもしれないけど、気になる。",romaji:"",idText:"Mungkin aku yang salah duga, tapi aku penasaran."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "態度"?',sentencePrompt:'Makna kata "態度" (たいど) dalam situasi kerja ini adalah:',options:["sikap, perilaku, cara bersikap","pemberitahuan, kabar, berita","belakangan ini, baru-baru ini","pertama, awal, pada mulanya"],correctAnswer:"sikap, perilaku, cara bersikap",explanation:'Makna yang tepat untuk "態度" adalah "sikap, perilaku, cara bersikap".',diagnosticFeedback:{"pemberitahuan, kabar, berita":'Salah: Pilihan "pemberitahuan, kabar, berita" adalah makna dari kata "知らせ" (しらせ), bukan arti kata "態度".',"belakangan ini, baru-baru ini":'Salah: Pilihan "belakangan ini, baru-baru ini" adalah makna dari kata "最近" (さいきん), bukan arti kata "態度".',"pertama, awal, pada mulanya":'Salah: Pilihan "pertama, awal, pada mulanya" adalah makna dari kata "最初" (さいしょ), bukan arti kata "態度".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"3時に来る（　　）のに、まだ来ない。",options:["はずだった","に決まっている","に違いない","だろう / 〜でしょう"],correctAnswer:"はずだった",explanation:'Pola 〜はずだった bermakna "seharusnya ... (tapi tidak terjadi), semestinya ... (tapi meleset)". Kalimat lengkap: "3時に来るはずだったのに、まだ来ない。".',diagnosticFeedback:{に決まっている:'Salah: Pola "に決まっている" bermakna "pasti ..., sudah pasti ..., tidak diragukan lagi ... (keyakinan kuat subjektif)", yang tidak sesuai konteks kalimat ini.',に違いない:'Salah: Pola "に違いない" bermakna "pasti ..., tidak mungkin selain ... (kesimpulan logis yang hampir pasti)", yang tidak sesuai konteks kalimat ini.',"だろう / 〜でしょう":'Salah: Pola "だろう / 〜でしょう" bermakna "mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜はずだった secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["今日は休めるはずだったが、急な仕事が入った。","今日は休めるはずだったでしたが、急な仕事が入った。","こんなに遅いんだから、迷っているに決まっている。","父が来られないかわりに、兄が来ました。"],correctAnswer:"今日は休めるはずだったが、急な仕事が入った。",explanation:'Kalimat yang benar dan alami adalah "今日は休めるはずだったが、急な仕事が入った。" (Seharusnya hari ini aku bisa istirahat, tapi tiba-tiba ada pekerjaan mendadak.).',diagnosticFeedback:{"今日は休めるはずだったでしたが、急な仕事が入った。":"Jebakan Konjugasi: Pola 〜はずだった membutuhkan aturan sambung (V-plain / い-Adj / な-Adj (な) / N (の) + はずだった), bukan bentuk ini.","こんなに遅いんだから、迷っているに決まっている。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜に決まっている: pasti ..., sudah pasti ..., tidak diragukan lagi ... (keyakinan kuat subjektif)), bukan kaidah 〜はずだった.","父が来られないかわりに、兄が来ました。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜はずだった secara tepat (seharusnya ... (tapi tidak terjadi), semestinya ... (tapi meleset))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["こんなに 遅いんだから、 迷っているに 決まっている。","遅いんだから、 こんなに 迷っているに 決まっている。","こんなに 迷っているに 遅いんだから、 決まっている。","決まっている。 こんなに 遅いんだから、 迷っているに"],correctAnswer:"こんなに 遅いんだから、 迷っているに 決まっている。",explanation:'Susunan yang benar: "こんなに 遅いんだから、 迷っているに 決まっている。" (Sudah selambat ini, pasti dia sedang tersesat.).',diagnosticFeedback:{"遅いんだから、 こんなに 迷っているに 決まっている。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","こんなに 迷っているに 遅いんだから、 決まっている。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","決まっている。 こんなに 遅いんだから、 迷っているに":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["こんなに","遅いんだから、","迷っているに","決まっている。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.", saat Yamada menyampaikan arahan: 「なるほど。こんなに遅いんだから、迷っているに決まっている。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜はずだった dan 〜に決まっている secara mandiri.",situation:"Situasi komunikasi profesional di Meja resepsionis dan ruang konsultasi pengurusan visa kerja di kantor konsultan imigrasi.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜はずだった!",modelAnswer:"はい、Yamadaさん！ 3時に来るはずだったのに、まだ来ない。。",modelAnswerId:"Ya, Yamada! Seharusnya dia datang jam 3, tapi sampai sekarang belum muncul..",culturalEtiquette:"Membungkuk hormat (Ojigi 30 derajat) saat mengucapkan permohonan santun itadakemasen ka.",skillUnlocked:["Menguasai formulasi pola 〜はずだった","Mampu menerapkan prinsip koordinasi komunikasi kerja Permohonan Santun, Ajakan Kerja & Doa Harapan"]},pocket_summary:{keyFormula:"〜はずだった (seharusnya ... (tapi tidak terjadi), semestinya ... (tapi meleset))",coreWords:["態度【たいど】 (sikap, perilaku, cara bersikap)","知らせ【しらせ】 (pemberitahuan, kabar, berita)","最近【さいきん】 (belakangan ini, baru-baru ini)","最初【さいしょ】 (pertama, awal, pada mulanya)"],coreWarning:"Jangan gunakan 〜te goran kepada orang yang lebih tua atau statusnya lebih tinggi.",quickDialogue:"A: ブディさん、態度の 状況【じょうきょう】は どうで... → B: はい、Yamadaさん！ 3時に来るはずだったのに..."}}},t={"les-n3-u12-01":{pedagogical_framework:{what:{summary:"Kepastian Logis, Dugaan Kuat & Kemustahilan (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜だろう / 〜でしょう, 〜るところだった, 〜わけではない / 〜わけじゃない, 必ずしも〜とは限らない, 決して〜ない dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜だろう / 〜でしょう dan 〜るところだった dalam percakapan kerja wajar.",targetPatterns:["〜だろう / 〜でしょう (mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang))","〜るところだった (hampir saja ... / nyaris ...)","〜わけではない / 〜わけじゃない (bukan berarti ... / tidak selalu ...)","必ずしも〜とは限らない (tidak selalu ... / belum tentu ...)","決して〜ない (tidak pernah ... / sama sekali tidak ...)"],coreVocabSample:["はいけい","たちば","かんてん","どうき","げんそく","かちかん","げんかい","のうりょく"]},sensei_context:{sceneIntro:"Pemeriksaan forensik log server database operasional logistik di pusat TI. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜だろう / 〜でしょう dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kepastian Logis, Dugaan Kuat & Kemustahilan",etiquette:"Dukung pernyataan 〜ni chigainai dengan data angka konkret agar kesimpulan Anda kredibel di mata rekan.",taboos:"Jangan memakai 〜hazu ga nai jika Anda belum memeriksa data faktual lapangan secara langsung."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜だろう / 〜でしょう",moraNote:"Pertahankan nada heiban pada chigainai dengan artikulasi mora jernih.",soundTip:"Ucapkan 〜だろう / 〜でしょう dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜だろう / 〜でしょう",caseScenario:"Menggunakan 〜だろう / 〜でしょう tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜だろう / 〜でしょう.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜だろう / 〜でしょう sesuai kaidah.",explanation:"Kaidah koneksi 〜だろう / 〜でしょう: V-plain / い-Adj / な-Adj (stem) / N + だろう (casual) / でしょう (polite)."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pemeriksaan forensik log server database operasional logistik di pusat TI.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kepastian Logis, Dugaan Kuat & Kemustahilan (Fondasi & Pemahaman Pola)",setting:"Pemeriksaan forensik log server database operasional logistik di pusat TI.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 〜だろう / 〜でしょう."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、背景の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、背景の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, haikei no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai latar belakang, konteks? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ 明日は晴れるでしょう。。",furigana:"はい、Yamadaさん！ 明日は晴れるでしょう。。",romaji:"Hai, Yamada-san! だろう / 〜でしょう de susumete imasu.",idText:"Ya, Yamada! Besok mungkin akan cerah.."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。電車に乗り遅れるところだった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。電車に乗り遅れるところだった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Hampir saja ketinggalan kereta.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00515",word:"背景",reading:"はいけい",romaji:"haikei",meaning:"latar belakang, konteks",pos:"noun",nuance:"背景 memiliki dua makna: (1) latar/backdrop secara visual (lukisan, foto), (2) latar belakang/konteks situasi atau seseorang. Berbeda dari 文脈 (ぶんみゃく) yang khusus merujuk pada konteks dalam teks/percakapan. 家庭背景 = latar belakang keluarga. 社会的背景 = latar belakang sosial.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"背景【はいけい】を 確認【かくにん】します。",furigana:"背景を 確認します。",romaji:"haikei o kakunin shimasu.",idText:"Memeriksa latar belakang, konteks."}},{id:"vg-n3-00516",word:"立場",reading:"たちば",romaji:"tachiba",meaning:"posisi, kedudukan, sudut pandang (sosial/situasional)",pos:"noun",nuance:"立場 menekankan posisi/kedudukan seseorang dalam konteks sosial, peran, atau situasi tertentu — sering menyiratkan tanggung jawab yang menyertai posisi itu. Berbeda dari 観点 yang murni merujuk pada sudut pandang analitis. 立場上 = mengingat posisi/kedudukan saya. 相手の立場 = posisi/keadaan pihak lain.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"立場【たちば】を 確認【かくにん】します。",furigana:"立場を 確認します。",romaji:"tachiba o kakunin shimasu.",idText:"Memeriksa posisi, kedudukan, sudut pandang (sosial/situasional)."}},{id:"vg-n3-00517",word:"観点",reading:"かんてん",romaji:"kanten",meaning:"sudut pandang, perspektif, titik pandang",pos:"noun",nuance:"観点 adalah kerangka analitis atau cara memandang suatu hal — lebih intelektual dan abstrak. Berbeda dari 立場 yang menekankan posisi sosial/situasional seseorang. ～の観点から = dari sudut pandang/perspektif ~. Sering dipakai dalam tulisan akademis dan diskusi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"観点【かんてん】を 確認【かくにん】します。",furigana:"観点を 確認します。",romaji:"kanten o kakunin shimasu.",idText:"Memeriksa sudut pandang, perspektif, titik pandang."}},{id:"vg-n3-00519",word:"動機",reading:"どうき",romaji:"douki",meaning:"motivasi, dorongan, motif",pos:"noun",nuance:"動機 adalah kekuatan/dorongan yang menggerakkan seseorang untuk bertindak — bisa internal (keinginan) atau eksternal (insentif). Berbeda dari 目的 yang merujuk pada tujuan/sasaran. Dalam konteks hukum, 動機 = motif kejahatan. 内発的動機 = motivasi intrinsik.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"動機【どうき】を 確認【かくにん】します。",furigana:"動機を 確認します。",romaji:"douki o kakunin shimasu.",idText:"Memeriksa motivasi, dorongan, motif."}},{id:"vg-n3-00520",word:"原則",reading:"げんそく",romaji:"gensoku",meaning:"prinsip, asas, kaidah dasar",pos:"noun",nuance:"原則 adalah prinsip atau kaidah mendasar yang menjadi panduan — sifatnya lebih fleksibel dan normatif. Berbeda dari 規則 (きそく) yang merupakan aturan konkret yang harus dipatuhi. 原則として = pada prinsipnya/secara umum. 原則を守る = menjaga prinsip.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"原則【げんそく】を 確認【かくにん】します。",furigana:"原則を 確認します。",romaji:"gensoku o kakunin shimasu.",idText:"Memeriksa prinsip, asas, kaidah dasar."}},{id:"vg-n3-00521",word:"価値観",reading:"かちかん",romaji:"kachikan",meaning:"nilai-nilai hidup, pandangan tentang nilai, sistem nilai",pos:"noun",nuance:"価値観 adalah sistem nilai atau pandangan seseorang tentang apa yang penting/berharga dalam hidup — bersifat personal dan terbentuk dari budaya/pengalaman. Berbeda dari 価値 (かち) yang merujuk pada nilai/harga suatu hal spesifik. 価値観の違い = perbedaan nilai-nilai hidup.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"価値観【かちかん】を 確認【かくにん】します。",furigana:"価値観を 確認します。",romaji:"kachikan o kakunin shimasu.",idText:"Memeriksa nilai-nilai hidup, pandangan tentang nilai, sistem nilai."}},{id:"vg-n3-00522",word:"限界",reading:"げんかい",romaji:"genkai",meaning:"batas, keterbatasan, titik akhir kemampuan",pos:"noun",nuance:"限界 adalah batas alami atau inheren dari kemampuan, kapasitas, atau kondisi tertentu — sering berkonotasi pada batas yang tak bisa dilampaui. Berbeda dari 制限 (せいげん) yang merupakan pembatasan yang diterapkan dari luar. 限界を超える = melampaui batas. もう限界だ = sudah di batas kemampuan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"限界【げんかい】を 確認【かくにん】します。",furigana:"限界を 確認します。",romaji:"genkai o kakunin shimasu.",idText:"Memeriksa batas, keterbatasan, titik akhir kemampuan."}},{id:"vg-n3-00523",word:"能力",reading:"のうりょく",romaji:"nouryoku",meaning:"kemampuan, kapasitas, kompetensi",pos:"noun",nuance:"能力 adalah kemampuan yang bisa diasah/dipelajari — mencakup keahlian teknis dan kapasitas umum. Berbeda dari 才能 (さいのう) yang merujuk pada bakat alami/bawaan. 能力がある/ない = mampu/tidak mampu. 能力を発揮する = menunjukkan kemampuan. 日本語能力試験 (JLPT) memakai kata ini.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"能力【のうりょく】を 確認【かくにん】します。",furigana:"能力を 確認します。",romaji:"nouryoku o kakunin shimasu.",idText:"Memeriksa kemampuan, kapasitas, kompetensi."}}],explanations:[{id:"exp-1",grammarId:"gn3-00180",title:"Pola: 〜だろう / 〜でしょう",formula:"V-plain / い-Adj / な-Adj (stem) / N + だろう (casual) / でしょう (polite)",meaning:"mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang)",nuanceNotes:"〜だろう dan 〜でしょう adalah pasangan kasual-formal dari pola perkiraan umum. Menyatakan bahwa pembicara menduga atau memperkirakan sesuatu dengan keyakinan yang cukup kuat, namun belum memastikan. でしょう adalah bentuk sopan dari だろう. Pola ini sangat luas penggunaannya — dari ramalan cuaca, pernyataan logis, hingga konfirmasi dengan lawan bicara (〜でしょう?).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜だろう / 〜でしょう",idText:"mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang)"}],examples:[{jp:"明日は晴れるでしょう。",romaji:"",idText:"Besok mungkin akan cerah."},{jp:"彼も知っているだろう。",romaji:"",idText:"Dia juga pasti tahu."},{jp:"この映画、面白いでしょう？",romaji:"",idText:"Film ini menarik, kan?"}]},{id:"exp-2",grammarId:"gn3-00015",title:"Pola: 〜るところだった",formula:"Vる + ところだった",meaning:"hampir saja ... / nyaris ...",nuanceNotes:'〜るところだった menyatakan bahwa suatu peristiwa (biasanya negatif) hampir saja terjadi tapi tidak jadi. "Nyaris", "hampir saja".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜るところだった",idText:"hampir saja ... / nyaris ..."}],examples:[{jp:"電車に乗り遅れるところだった。",romaji:"",idText:"Hampir saja ketinggalan kereta."},{jp:"転ぶところだったが、助けてもらった。",romaji:"",idText:"Hampir saja terjatuh, tapi ditolong."}]},{id:"exp-3",grammarId:"gn3-00029",title:"Pola: 〜わけではない / 〜わけじゃない",formula:"V/Adj plain / N + というわけではない",meaning:"bukan berarti ... / tidak selalu ...",nuanceNotes:'〜わけではない digunakan untuk menyanggah atau membatasi interpretasi: "bukan berarti", "tidak selalu demikian".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜わけではない / 〜わけじゃない",idText:"bukan berarti ... / tidak selalu ..."}],examples:[{jp:"嫌いなわけではないが、好きでもない。",romaji:"",idText:"Bukan berarti tidak suka, tapi juga tidak suka."},{jp:"すべてが悪いわけじゃない。",romaji:"",idText:"Bukan berarti semuanya buruk."}]},{id:"exp-4",grammarId:"gn3-00033",title:"Pola: 必ずしも〜とは限らない",formula:"必ずしも + V/Adj + とは限らない",meaning:"tidak selalu ... / belum tentu ...",nuanceNotes:'必ずしも〜とは限らない menyatakan bahwa sesuatu tidak selalu demikian, meskipun umum dianggap begitu: "belum tentu", "tidak selalu".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"必ずしも〜とは限らない",idText:"tidak selalu ... / belum tentu ..."}],examples:[{jp:"高い物が必ずしもいい物だとは限らない。",romaji:"",idText:"Barang mahal belum tentu barang yang baik."},{jp:"有名人が必ずしも幸せとは限らない。",romaji:"",idText:"Orang terkenal belum tentu bahagia."}]},{id:"exp-5",grammarId:"gn3-00044",title:"Pola: 決して〜ない",formula:"決して + V/Adj + ない",meaning:"tidak pernah ... / sama sekali tidak ...",nuanceNotes:'決して〜ない menyatakan penyangkalan yang kuat dan mutlak: "tidak pernah", "sama sekali tidak".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"決して〜ない",idText:"tidak pernah ... / sama sekali tidak ..."}],examples:[{jp:"あの経験は決して忘れない。",romaji:"",idText:"Pengalaman itu tidak akan pernah saya lupakan."},{jp:"決して諦めない！",romaji:"",idText:"Tidak akan pernah menyerah!"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "背景"?',sentencePrompt:'Makna kata "背景" (はいけい) dalam situasi kerja ini adalah:',options:["latar belakang, konteks","posisi, kedudukan, sudut pandang (sosial/situasional)","sudut pandang, perspektif, titik pandang","motivasi, dorongan, motif"],correctAnswer:"latar belakang, konteks",explanation:'Makna yang tepat untuk "背景" adalah "latar belakang, konteks".',diagnosticFeedback:{"posisi, kedudukan, sudut pandang (sosial/situasional)":'Salah: Pilihan "posisi, kedudukan, sudut pandang (sosial/situasional)" adalah makna dari kata "立場" (たちば), bukan arti kata "背景".',"sudut pandang, perspektif, titik pandang":'Salah: Pilihan "sudut pandang, perspektif, titik pandang" adalah makna dari kata "観点" (かんてん), bukan arti kata "背景".',"motivasi, dorongan, motif":'Salah: Pilihan "motivasi, dorongan, motif" adalah makna dari kata "動機" (どうき), bukan arti kata "背景".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"明日は晴れる（　　）。",options:["でしょう","るところだった","わけではない / 〜わけじゃない","というより"],correctAnswer:"でしょう",explanation:'Pola 〜だろう / 〜でしょう bermakna "mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang)". Kalimat lengkap: "明日は晴れるでしょう。".',diagnosticFeedback:{るところだった:'Salah: Pola "るところだった" bermakna "hampir saja ... / nyaris ...", yang tidak sesuai konteks kalimat ini.',"わけではない / 〜わけじゃない":'Salah: Pola "わけではない / 〜わけじゃない" bermakna "bukan berarti ... / tidak selalu ...", yang tidak sesuai konteks kalimat ini.',というより:'Salah: Pola "というより" bermakna "lebih tepatnya ... / daripada disebut ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜だろう / 〜でしょう secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["彼も知っているだろう。","彼も知っているだろう。でした","電車に乗り遅れるところだった。","彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。"],correctAnswer:"彼も知っているだろう。",explanation:'Kalimat yang benar dan alami adalah "彼も知っているだろう。" (Dia juga pasti tahu.).',diagnosticFeedback:{"彼も知っているだろう。でした":"Jebakan Konjugasi: Pola 〜だろう / 〜でしょう membutuhkan aturan sambung (V-plain / い-Adj / な-Adj (stem) / N + だろう (casual) / でしょう (polite)), bukan bentuk ini.","電車に乗り遅れるところだった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜るところだった: hampir saja ... / nyaris ...), bukan kaidah 〜だろう / 〜でしょう.","彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜だろう / 〜でしょう secara tepat (mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["電車に 乗り遅れ るところ だった。","乗り遅れ 電車に るところ だった。","電車に るところ 乗り遅れ だった。","だった。 電車に 乗り遅れ るところ"],correctAnswer:"電車に 乗り遅れ るところ だった。",explanation:'Susunan yang benar: "電車に 乗り遅れ るところ だった。" (Hampir saja ketinggalan kereta.).',diagnosticFeedback:{"乗り遅れ 電車に るところ だった。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","電車に るところ 乗り遅れ だった。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","だった。 電車に 乗り遅れ るところ":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["電車に","乗り遅れ","るところ","だった。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pemeriksaan forensik log server database operasional logistik di pusat TI.", saat Yamada menyampaikan arahan: 「なるほど。電車に乗り遅れるところだった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜だろう / 〜でしょう dan 〜るところだった dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Pemeriksaan forensik log server database operasional logistik di pusat TI.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜だろう / 〜でしょう!",modelAnswer:"はい、Yamadaさん！ 明日は晴れるでしょう。。",modelAnswerId:"Ya, Yamada! Besok mungkin akan cerah..",culturalEtiquette:"Dukung pernyataan 〜ni chigainai dengan data angka konkret agar kesimpulan Anda kredibel di mata rekan.",skillUnlocked:["Menguasai formulasi pola 〜だろう / 〜でしょう","Mampu menerapkan prinsip koordinasi komunikasi kerja Kepastian Logis, Dugaan Kuat & Kemustahilan"]},pocket_summary:{keyFormula:"〜だろう / 〜でしょう (mungkin ..., sepertinya ..., sepertinya begitu (perkiraan dengan keyakinan sedang))",coreWords:["背景【はいけい】 (latar belakang, konteks)","立場【たちば】 (posisi, kedudukan, sudut pandang (sosial/situasional))","観点【かんてん】 (sudut pandang, perspektif, titik pandang)","動機【どうき】 (motivasi, dorongan, motif)"],coreWarning:"Jangan memakai 〜hazu ga nai jika Anda belum memeriksa data faktual lapangan secara langsung.",quickDialogue:"A: ブディさん、背景の 状況【じょうきょう】は どうで... → B: はい、Yamadaさん！ 明日は晴れるでしょう。。..."}},"les-n3-u12-02":{pedagogical_framework:{what:{summary:"Kepastian Logis, Dugaan Kuat & Kemustahilan (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 少しも / ちっとも〜ない, まったく〜ない, 〜に比べて, 〜にかけて dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 少しも / ちっとも〜ない dan まったく〜ない secara mandiri.",targetPatterns:["少しも / ちっとも〜ない (sedikitpun tidak ... / sama sekali tidak ...)","まったく〜ない (sama sekali tidak ... / benar-benar tidak ...)","〜に比べて (dibandingkan dengan ...)","〜にかけて (dari ... hingga ... / selama rentang ...)"],coreVocabSample:["さんこうしょ","こうりつ","こうじょうしん","こうきしん","ぶんや","せんもん","ちしき","よゆう"]},sensei_context:{sceneIntro:"Pemeriksaan forensik log server database operasional logistik di pusat TI. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 少しも / ちっとも〜ない dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kepastian Logis, Dugaan Kuat & Kemustahilan",etiquette:"Dukung pernyataan 〜ni chigainai dengan data angka konkret agar kesimpulan Anda kredibel di mata rekan.",taboos:"Jangan memakai 〜hazu ga nai jika Anda belum memeriksa data faktual lapangan secara langsung."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 少しも / ちっとも〜ない",moraNote:"Pertahankan nada heiban pada chigainai dengan artikulasi mora jernih.",soundTip:"Ucapkan 少しも / ちっとも〜ない dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 少しも / ちっとも〜ない",caseScenario:"Menggunakan 少しも / ちっとも〜ない tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 少しも / ちっとも〜ない.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 少しも / ちっとも〜ない sesuai kaidah.",explanation:"Kaidah koneksi 少しも / ちっとも〜ない: 少しも / ちっとも + V/Adj + ない."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pemeriksaan forensik log server database operasional logistik di pusat TI.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kepastian Logis, Dugaan Kuat & Kemustahilan (Produksi Aktif & Aplikasi Nyata)",setting:"Pemeriksaan forensik log server database operasional logistik di pusat TI.",narrative:"Budi dan Yamada berkoordinasi mengenai alur operasional kerja menggunakan pola 少しも / ちっとも〜ない."}},dialogue:[{id:"d1",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"ブディさん、参考書の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、参考書の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, sankousho no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai buku referensi, buku pelajaran tambahan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Yamadaさん！ 彼女のことが少しもわからない。。",furigana:"はい、Yamadaさん！ 彼女のことが少しもわからない。。",romaji:"Hai, Yamada-san! 少しも / ちっとも〜ない de susumete imasu.",idText:"Ya, Yamada! Sedikitpun saya tidak mengerti tentang dia.."},{id:"d3",speaker:"Yamada",speakerRole:"Manajer QC & Logistik",avatar:"👷‍♂️",jp:"なるほど。日本語がまったくわからない。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。日本語がまったくわからない。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Sama sekali tidak mengerti bahasa Jepang.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00691",word:"参考書",reading:"さんこうしょ",romaji:"sankousho",meaning:"buku referensi, buku pelajaran tambahan",pos:"noun",nuance:"Secara spesifik merujuk pada buku yang digunakan siswa secara mandiri untuk memperdalam pemahaman atau mempersiapkan ujian — bukan buku teks wajib dari sekolah. Berbeda dari 教材 yang mencakup semua materi ajar; 参考書 dipilih sendiri oleh siswa dan sifatnya suplemental.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"参考書【さんこうしょ】を 確認【かくにん】します。",furigana:"参考書を 確認します。",romaji:"sankousho o kakunin shimasu.",idText:"Memeriksa buku referensi, buku pelajaran tambahan."}},{id:"vg-n3-00698",word:"効率",reading:"こうりつ",romaji:"kouritsu",meaning:"efisiensi, rasio hasil terhadap usaha yang dikeluarkan",pos:"noun",nuance:"Menekankan perbandingan antara hasil yang diperoleh dengan sumber daya (waktu, energi) yang digunakan. Berbeda dari 効果 yang hanya mengukur apakah hasilnya ada/tidak; 効率 mempertanyakan seberapa hemat cara mencapainya. 効率がいい = cara yang efisien; 効果がある = cara yang manjur.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"効率【こうりつ】を 確認【かくにん】します。",furigana:"効率を 確認します。",romaji:"kouritsu o kakunin shimasu.",idText:"Memeriksa efisiensi, rasio hasil terhadap usaha yang dikeluarkan."}},{id:"vg-n3-00700",word:"向上心",reading:"こうじょうしん",romaji:"koujoushin",meaning:"semangat untuk terus berkembang, hasrat maju",pos:"noun",nuance:"Merujuk pada dorongan dari dalam diri untuk terus memperbaiki kemampuan dan kualitas diri — selalu berkonotasi positif. Berbeda dari 野心 yang bisa berkonotasi negatif (ambisi berlebihan, haus kekuasaan); 向上心 diapresiasi di konteks belajar dan karier di Jepang.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"向上心【こうじょうしん】を 確認【かくにん】します。",furigana:"向上心を 確認します。",romaji:"koujoushin o kakunin shimasu.",idText:"Memeriksa semangat untuk terus berkembang, hasrat maju."}},{id:"vg-n3-00701",word:"好奇心",reading:"こうきしん",romaji:"koukishin",meaning:"rasa ingin tahu, dorongan untuk menjelajahi hal-hal baru",pos:"noun",nuance:"Merujuk pada dorongan alami untuk mengetahui dan mengeksplorasi hal-hal yang belum diketahui. Berbeda dari 興味 (minat terhadap sesuatu yang sudah dikenal); 好奇心 lebih aktif dan mengarah ke hal yang belum familiar, serta mengandung nuansa petualangan intelektual.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"好奇心【こうきしん】を 確認【かくにん】します。",furigana:"好奇心を 確認します。",romaji:"koukishin o kakunin shimasu.",idText:"Memeriksa rasa ingin tahu, dorongan untuk menjelajahi hal-hal baru."}},{id:"vg-n3-00703",word:"分野",reading:"ぶんや",romaji:"bun'ya",meaning:"bidang, ranah, area kajian atau kegiatan",pos:"noun",nuance:"Merujuk pada 'bidang' atau 'ranah' yang lebih luas dan kategoris — bisa dipakai untuk ilmu pengetahuan, seni, bisnis, dll. Berbeda dari 専門 yang merujuk pada keahlian spesifik seseorang; 分野 adalah label untuk kategori besarnya, bukan tingkat penguasaan individu.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"分野【ぶんや】を 確認【かくにん】します。",furigana:"分野を 確認します。",romaji:"bun'ya o kakunin shimasu.",idText:"Memeriksa bidang, ranah, area kajian atau kegiatan."}},{id:"vg-n3-00704",word:"専門",reading:"せんもん",romaji:"senmon",meaning:"spesialisasi, keahlian yang sudah dimiliki",pos:"noun",nuance:"Merujuk pada keahlian atau bidang yang sudah dikuasai seseorang — apa yang menjadi kekuatan utamanya. Berbeda dari 専攻 (jurusan yang sedang dipelajari) dan 分野 (kategori bidang yang luas); 専門 menyiratkan penguasaan yang sudah matang, sering dikaitkan dengan karier atau identitas profesional.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"専門【せんもん】を 確認【かくにん】します。",furigana:"専門を 確認します。",romaji:"senmon o kakunin shimasu.",idText:"Memeriksa spesialisasi, keahlian yang sudah dimiliki."}},{id:"vg-n3-00705",word:"知識",reading:"ちしき",romaji:"chishiki",meaning:"pengetahuan, ilmu yang sudah dipahami dan dimiliki",pos:"noun",nuance:"Merujuk pada informasi yang sudah diinternalisasi dan dipahami oleh seseorang — pengetahuan yang sudah menjadi milik. Berbeda dari 情報 yang hanya berarti 'informasi' atau 'data' yang belum tentu dipahami; 知識 menyiratkan pemahaman aktif, bukan sekadar data mentah.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"知識【ちしき】を 確認【かくにん】します。",furigana:"知識を 確認します。",romaji:"chishiki o kakunin shimasu.",idText:"Memeriksa pengetahuan, ilmu yang sudah dipahami dan dimiliki."}},{id:"vg-n3-00724",word:"余裕",reading:"よゆう",romaji:"yoyuu",meaning:"kelonggaran (waktu/uang/mental), kondisi tidak terburu-buru atau tidak tertekan",pos:"noun",nuance:"Merujuk pada kondisi di mana ada 'ruang ekstra' — waktu, uang, atau kapasitas mental yang cukup sehingga tidak merasa tertekan. Bisa dipakai secara fisik (余裕がある = ada waktu sisa) maupun emosional (余裕を持つ = bersikap tenang). Lawannya adalah 余裕がない = tidak ada kelonggaran, terdesak.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"余裕【よゆう】を 確認【かくにん】します。",furigana:"余裕を 確認します。",romaji:"yoyuu o kakunin shimasu.",idText:"Memeriksa kelonggaran (waktu/uang/mental), kondisi tidak terburu-buru atau tidak tertekan."}}],explanations:[{id:"exp-1",grammarId:"gn3-00046",title:"Pola: 少しも / ちっとも〜ない",formula:"少しも / ちっとも + V/Adj + ない",meaning:"sedikitpun tidak ... / sama sekali tidak ...",nuanceNotes:'少しも / ちっとも〜ない menyatakan negasi total: "sedikitpun tidak". ちっとも lebih kasual.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"少しも / ちっとも〜ない",idText:"sedikitpun tidak ... / sama sekali tidak ..."}],examples:[{jp:"彼女のことが少しもわからない。",romaji:"",idText:"Sedikitpun saya tidak mengerti tentang dia."},{jp:"ちっとも寒くないね。",romaji:"",idText:"Tidak dingin sedikitpun ya."}]},{id:"exp-2",grammarId:"gn3-00047",title:"Pola: まったく〜ない",formula:"まったく + V/Adj + ない",meaning:"sama sekali tidak ... / benar-benar tidak ...",nuanceNotes:'まったく〜ない menyatakan negasi mutlak: "sama sekali tidak", "benar-benar tidak".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"まったく〜ない",idText:"sama sekali tidak ... / benar-benar tidak ..."}],examples:[{jp:"日本語がまったくわからない。",romaji:"",idText:"Sama sekali tidak mengerti bahasa Jepang."},{jp:"まったく想定外のことが起きた。",romaji:"",idText:"Sesuatu yang benar-benar di luar dugaan terjadi."}]},{id:"exp-3",grammarId:"gn3-00051",title:"Pola: 〜に比べて",formula:"N + に比べて / に比べると",meaning:"dibandingkan dengan ...",nuanceNotes:'〜に比べて digunakan untuk membandingkan dua hal: "dibandingkan dengan".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に比べて",idText:"dibandingkan dengan ..."}],examples:[{jp:"去年に比べて、今年は暖かい。",romaji:"",idText:"Dibandingkan tahun lalu, tahun ini lebih hangat."},{jp:"電車に比べると、バスは時間がかかります。",romaji:"",idText:"Dibandingkan kereta, bus lebih memakan waktu."}]},{id:"exp-4",grammarId:"gn3-00052",title:"Pola: 〜にかけて",formula:"N (titik awal) + から + N (titik akhir) + にかけて",meaning:"dari ... hingga ... / selama rentang ...",nuanceNotes:'〜にかけて menyatakan rentang waktu atau tempat yang tidak pasti batasnya: "dari ... hingga ...", berbeda dari まで yang batasnya lebih pasti.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜にかけて",idText:"dari ... hingga ... / selama rentang ..."}],examples:[{jp:"春にかけて、花粉症がひどくなる。",romaji:"",idText:"Dari musim dingin hingga musim semi, alergi pollen semakin parah."},{jp:"関東から東北にかけて、大雪が降った。",romaji:"",idText:"Dari Kanto hingga Tohoku, turun salju lebat."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "参考書"?',sentencePrompt:'Makna kata "参考書" (さんこうしょ) dalam situasi kerja ini adalah:',options:["buku referensi, buku pelajaran tambahan","efisiensi, rasio hasil terhadap usaha yang dikeluarkan","semangat untuk terus berkembang, hasrat maju","rasa ingin tahu, dorongan untuk menjelajahi hal-hal baru"],correctAnswer:"buku referensi, buku pelajaran tambahan",explanation:'Makna yang tepat untuk "参考書" adalah "buku referensi, buku pelajaran tambahan".',diagnosticFeedback:{"efisiensi, rasio hasil terhadap usaha yang dikeluarkan":'Salah: Pilihan "efisiensi, rasio hasil terhadap usaha yang dikeluarkan" adalah makna dari kata "効率" (こうりつ), bukan arti kata "参考書".',"semangat untuk terus berkembang, hasrat maju":'Salah: Pilihan "semangat untuk terus berkembang, hasrat maju" adalah makna dari kata "向上心" (こうじょうしん), bukan arti kata "参考書".',"rasa ingin tahu, dorongan untuk menjelajahi hal-hal baru":'Salah: Pilihan "rasa ingin tahu, dorongan untuk menjelajahi hal-hal baru" adalah makna dari kata "好奇心" (こうきしん), bukan arti kata "参考書".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"彼女のことが（　　）わから（　　）。",options:["少しも","まったく〜ない","に比べて","というより"],correctAnswer:"少しも",explanation:'Pola 少しも / ちっとも〜ない bermakna "sedikitpun tidak ... / sama sekali tidak ...". Kalimat lengkap: "彼女のことが少しもわからない。".',diagnosticFeedback:{"まったく〜ない":'Salah: Pola "まったく〜ない" bermakna "sama sekali tidak ... / benar-benar tidak ...", yang tidak sesuai konteks kalimat ini.',に比べて:'Salah: Pola "に比べて" bermakna "dibandingkan dengan ...", yang tidak sesuai konteks kalimat ini.',というより:'Salah: Pola "というより" bermakna "lebih tepatnya ... / daripada disebut ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 少しも / ちっとも〜ない secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["ちっとも寒くないね。","ちっとも寒くないね。でした","日本語がまったくわからない。","彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。"],correctAnswer:"ちっとも寒くないね。",explanation:'Kalimat yang benar dan alami adalah "ちっとも寒くないね。" (Tidak dingin sedikitpun ya.).',diagnosticFeedback:{"ちっとも寒くないね。でした":"Jebakan Konjugasi: Pola 少しも / ちっとも〜ない membutuhkan aturan sambung (少しも / ちっとも + V/Adj + ない), bukan bentuk ini.","日本語がまったくわからない。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (まったく〜ない: sama sekali tidak ... / benar-benar tidak ...), bukan kaidah 少しも / ちっとも〜ない.","彼は昨日も一昨日も来なかった。つまり、もう来ないつもりだろう。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 少しも / ちっとも〜ない secara tepat (sedikitpun tidak ... / sama sekali tidak ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["日本語 がまった くわから ない。","がまった 日本語 くわから ない。","日本語 くわから がまった ない。","ない。 日本語 がまった くわから"],correctAnswer:"日本語 がまった くわから ない。",explanation:'Susunan yang benar: "日本語 がまった くわから ない。" (Sama sekali tidak mengerti bahasa Jepang.).',diagnosticFeedback:{"がまった 日本語 くわから ない。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","日本語 くわから がまった ない。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","ない。 日本語 がまった くわから":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["日本語","がまった","くわから","ない。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pemeriksaan forensik log server database operasional logistik di pusat TI.", saat Yamada menyampaikan arahan: 「なるほど。日本語がまったくわからない。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 少しも / ちっとも〜ない dan まったく〜ない secara mandiri.",situation:"Situasi komunikasi profesional di Pemeriksaan forensik log server database operasional logistik di pusat TI.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 少しも / ちっとも〜ない!",modelAnswer:"はい、Yamadaさん！ 彼女のことが少しもわからない。。",modelAnswerId:"Ya, Yamada! Sedikitpun saya tidak mengerti tentang dia..",culturalEtiquette:"Dukung pernyataan 〜ni chigainai dengan data angka konkret agar kesimpulan Anda kredibel di mata rekan.",skillUnlocked:["Menguasai formulasi pola 少しも / ちっとも〜ない","Mampu menerapkan prinsip koordinasi komunikasi kerja Kepastian Logis, Dugaan Kuat & Kemustahilan"]},pocket_summary:{keyFormula:"少しも / ちっとも〜ない (sedikitpun tidak ... / sama sekali tidak ...)",coreWords:["参考書【さんこうしょ】 (buku referensi, buku pelajaran tambahan)","効率【こうりつ】 (efisiensi, rasio hasil terhadap usaha yang dikeluarkan)","向上心【こうじょうしん】 (semangat untuk terus berkembang, hasrat maju)","好奇心【こうきしん】 (rasa ingin tahu, dorongan untuk menjelajahi hal-hal baru)"],coreWarning:"Jangan memakai 〜hazu ga nai jika Anda belum memeriksa data faktual lapangan secara langsung.",quickDialogue:"A: ブディさん、参考書の 状況【じょうきょう】は どう... → B: はい、Yamadaさん！ 彼女のことが少しもわから..."}}},r={"les-n3-u13-01":{pedagogical_framework:{what:{summary:"Negasi Parsial, Penyangkalan Total & Pembatasan (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜というより, 〜のように / 〜ように（説明）, まるで〜のよう / 〜みたい, 〜くらい / 〜ぐらい / 〜ほど（程度）, 〜ずにはいられない dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜というより dan 〜のように / 〜ように（説明） dalam percakapan kerja wajar.",targetPatterns:["〜というより (lebih tepatnya ... / daripada disebut ...)","〜のように / 〜ように（説明） (seperti ... / sebagaimana ...)","まるで〜のよう / 〜みたい (seperti ... / bagaikan ...)","〜くらい / 〜ぐらい / 〜ほど（程度） (sekitar ... / sampai-sampai ... / sedemikian ...)","〜ずにはいられない (tidak bisa tidak ..., terpaksa harus ...)"],coreVocabSample:["しょう","しょう","しょうがい","じょうきゃく","しょうご","じょうしき","しょうじょ","じょうだん"]},sensei_context:{sceneIntro:"Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜というより dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Negasi Parsial, Penyangkalan Total & Pembatasan",etiquette:"Gunakan negasi parsial untuk meluruskan kesalahpahaman klien dengan bahasa diplomatis yang elegan.",taboos:"Menolak pernyataan mitra secara mentah-mentah tanpa awalan diplomatis dapat merusak relasi bisnis."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜というより",moraNote:"Tekankan mora wa-ke pada wake dewa nai secara santun tanpa aksen meninggi di akhir.",soundTip:"Ucapkan 〜というより dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜というより",caseScenario:"Menggunakan 〜というより tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜というより.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜というより sesuai kaidah.",explanation:"Kaidah koneksi 〜というより: N/V/Adj + というより."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Negasi Parsial, Penyangkalan Total & Pembatasan (Fondasi & Pemahaman Pola)",setting:"Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜というより."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、章の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、章の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, shou no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai bab, bagian (buku); lencana? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 趣味というより、もはや仕事になっている。。",furigana:"はい、Sakuraさん！ 趣味というより、もはや仕事になっている。。",romaji:"Hai, Sakura-san! というより de susumete imasu.",idText:"Ya, Sakura! Daripada disebut hobi, itu sudah menjadi pekerjaan.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。前回説明したように、この問題は複雑です。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。前回説明したように、この問題は複雑です。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Seperti yang sudah dijelaskan sebelumnya, masalah ini kompleks.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00836",word:"章",reading:"しょう",romaji:"shou",meaning:"bab, bagian (buku); lencana",pos:"noun",nuance:"Umumnya digunakan untuk menyebut bab dalam buku, novel, atau karya ilmiah (sering dipadukan dengan angka urutan seperti 第一章 / bab pertama). Berbeda dengan 節 (setsu) yang merujuk pada sub-bab atau pasal yang lebih kecil di dalam bab. Dalam konteks resmi pemerintahan atau militer, kata ini juga bermakna lencana tanda kehormatan seperti pada 勲章 (kunshou).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"章【しょう】を 確認【かくにん】します。",furigana:"章を 確認します。",romaji:"shou o kakunin shimasu.",idText:"Memeriksa bab, bagian (buku); lencana."}},{id:"vg-n3-00837",word:"賞",reading:"しょう",romaji:"shou",meaning:"penghargaan, hadiah kehormatan",pos:"noun",nuance:"Merujuk pada penghargaan atau gelar kehormatan yang dianugerahkan atas prestasi atau karya unggul (misalnya ノーベル賞 / Hadiah Nobel, atau 最優秀賞 / Penghargaan Terbaik). Berbeda dengan 賞品 (shouhin) yang merujuk pada bentuk fisik barang hadiahnya, sedangkan kata 賞 lebih menekankan status penghargaan itu sendiri.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"賞【しょう】を 確認【かくにん】します。",furigana:"賞を 確認します。",romaji:"shou o kakunin shimasu.",idText:"Memeriksa penghargaan, hadiah kehormatan."}},{id:"vg-n3-00838",word:"障害",reading:"しょうがい",romaji:"shougai",meaning:"rintangan, kendala, gangguan, disabilitas",pos:"noun",nuance:"Memiliki dua pemakaian utama: pertama, masalah teknis atau kendala yang menghambat operasional suatu sistem (misalnya システム障害 / gangguan sistem); kedua, kondisi keterbatasan fungsi tubuh atau mental (misalnya 身体障害 / disabilitas fisik). Berbeda dengan 邪魔 (jama) yang cenderung berarti gangguan sesaat dari pihak luar yang mengalihkan perhatian.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"障害【しょうがい】を 確認【かくにん】します。",furigana:"障害を 確認します。",romaji:"shougai o kakunin shimasu.",idText:"Memeriksa rintangan, kendala, gangguan, disabilitas."}},{id:"vg-n3-00839",word:"乗客",reading:"じょうきゃく",romaji:"joukyaku",meaning:"penumpang (kendaraan)",pos:"noun",nuance:"Khusus merujuk pada penumpang yang menaiki kendaraan transportasi umum seperti kereta api, pesawat, kapal laut, atau bus. Berbeda dengan 客 (kyaku) atau お客さん (okyakusan) yang mencakup pelanggan toko, pembeli, ataupun tamu di rumah.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"乗客【じょうきゃく】を 確認【かくにん】します。",furigana:"乗客を 確認します。",romaji:"joukyaku o kakunin shimasu.",idText:"Memeriksa penumpang (kendaraan)."}},{id:"vg-n3-00840",word:"正午",reading:"しょうご",romaji:"shougo",meaning:"tengah hari, pukul 12 siang tepat",pos:"noun",nuance:"Menunjukkan waktu tepat jam dua belas siang (12:00). Berbeda dengan お昼 (ohiru) atau 昼の十二時 yang bernuansa percakapan santai sehari-hari, 正午 lebih sering digunakan dalam konteks resmi, siaran berita, jadwal acara, atau dokumen tertulis formal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"正午【しょうご】を 確認【かくにん】します。",furigana:"正午を 確認します。",romaji:"shougo o kakunin shimasu.",idText:"Memeriksa tengah hari, pukul 12 siang tepat."}},{id:"vg-n3-00842",word:"常識",reading:"じょうしき",romaji:"joushiki",meaning:"akal sehat, norma umum, pemikiran wajar",pos:"noun",nuance:"Mengacu pada norma kepantasan sosial atau pengetahuan dasar yang wajar diketahui dan dipatuhi oleh masyarakat umum. Sering dipakai dalam bentuk 常識がある (punya norma/akal sehat) atau lawannya 非常識 (tidak punya etika/tidak masuk akal). Berbeda dengan 知識 (chishiki) yang murni berarti wawasan atau hafalan akademis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"常識【じょうしき】を 確認【かくにん】します。",furigana:"常識を 確認します。",romaji:"joushiki o kakunin shimasu.",idText:"Memeriksa akal sehat, norma umum, pemikiran wajar."}},{id:"vg-n3-00843",word:"少女",reading:"しょうじょ",romaji:"shoujo",meaning:"anak perempuan, gadis belia",pos:"noun",nuance:"Merujuk pada anak perempuan dari usia kanak-kanak akhir hingga menjelang remaja awal (sekitar usia 7 sampai 15 tahun). Berbeda dengan 女の子 (onna no ko) yang lebih kasual dan bisa merujuk hingga wanita muda, serta berbeda dengan 女性 (josei) yang formal untuk wanita dewasa.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"少女【しょうじょ】を 確認【かくにん】します。",furigana:"少女を 確認します。",romaji:"shoujo o kakunin shimasu.",idText:"Memeriksa anak perempuan, gadis belia."}},{id:"vg-n3-00847",word:"冗談",reading:"じょうだん",romaji:"joudan",meaning:"lelucon, candaan, kelakar",pos:"noun",nuance:"Merujuk pada kata-kata gurauan yang diucapkan demi mencairkan suasana atau menghibur tanpa maksud sungguh-sungguh. Sering muncul dalam frasa 冗談を言う (bercanda), 冗談じゃない (jangan bercanda / tidak masuk akal), atau 冗談はさておき (mengesampingkan lelucon). Berbeda dengan からかい (karakai) yang cenderung bermaksud menggoda atau mengejek pihak lain.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"冗談【じょうだん】を 確認【かくにん】します。",furigana:"冗談を 確認します。",romaji:"joudan o kakunin shimasu.",idText:"Memeriksa lelucon, candaan, kelakar."}}],explanations:[{id:"exp-1",grammarId:"gn3-00067",title:"Pola: 〜というより",formula:"N/V/Adj + というより",meaning:"lebih tepatnya ... / daripada disebut ...",nuanceNotes:'〜というより digunakan untuk mengoreksi atau memperjelas: "daripada dikatakan X, lebih tepat Y".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜というより",idText:"lebih tepatnya ... / daripada disebut ..."}],examples:[{jp:"趣味というより、もはや仕事になっている。",romaji:"",idText:"Daripada disebut hobi, itu sudah menjadi pekerjaan."},{jp:"好きというより、尊敬しています。",romaji:"",idText:"Daripada disebut suka, lebih tepatnya saya kagum."}]},{id:"exp-2",grammarId:"gn3-00068",title:"Pola: 〜のように / 〜ように（説明）",formula:"N + のように / 文 + ように",meaning:"seperti ... / sebagaimana ...",nuanceNotes:'〜のように digunakan sebagai pengantar penjelasan atau instruksi yang memiliki nuansa "seperti yang... ", "sebagaimana...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜のように / 〜ように（説明）",idText:"seperti ... / sebagaimana ..."}],examples:[{jp:"前回説明したように、この問題は複雑です。",romaji:"",idText:"Seperti yang sudah dijelaskan sebelumnya, masalah ini kompleks."},{jp:"彼女は天使のように歌います。",romaji:"",idText:"Dia menyanyi seperti malaikat."}]},{id:"exp-3",grammarId:"gn3-00080",title:"Pola: まるで〜のよう / 〜みたい",formula:"まるで + N + の + ようだ / みたいだ",meaning:"seperti ... / bagaikan ...",nuanceNotes:'まるで〜ようだ / みたいだ memperkuat perumpamaan: "benar-benar seperti", "bagaikan".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"まるで〜のよう / 〜みたい",idText:"seperti ... / bagaikan ..."}],examples:[{jp:"まるで夢のようだ。",romaji:"",idText:"Benar-benar seperti mimpi."},{jp:"その子はまるで人形みたいにかわいい。",romaji:"",idText:"Anak itu lucu bagaikan boneka."}]},{id:"exp-4",grammarId:"gn3-00098",title:"Pola: 〜くらい / 〜ぐらい / 〜ほど（程度）",formula:"V/Adj + くらい / ぐらい / ほど",meaning:"sekitar ... / sampai-sampai ... / sedemikian ...",nuanceNotes:'〜くらい / 〜ほど (derajat) menyatakan tingkat atau ukuran: "sampai-sampai", "sedemikian", "sekitar". Menekankan derajat yang ekstrem.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜くらい / 〜ぐらい / 〜ほど（程度）",idText:"sekitar ... / sampai-sampai ... / sedemikian ..."}],examples:[{jp:"泣きたいほど嬉しかった。",romaji:"",idText:"Senangnya sampai ingin menangis."},{jp:"死ぬくらい疲れた。",romaji:"",idText:"Capai sampai seperti mau mati."}]},{id:"exp-5",grammarId:"gn3-00137",title:"Pola: 〜ずにはいられない",formula:"V-ない (語幹) + ずにはいられない ※する→せずに",meaning:"tidak bisa tidak ..., terpaksa harus ...",nuanceNotes:"〜ずにはいられない menyatakan bahwa pembicara tidak dapat menahan diri untuk tidak melakukan sesuatu karena dorongan emosi atau perasaan yang kuat. Ini adalah ekspresi dari ketidakmampuan untuk menahan impuls atau reaksi alami. Merupakan pola yang agak formal dan literari.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ずにはいられない",idText:"tidak bisa tidak ..., terpaksa harus ..."}],examples:[{jp:"この映画を見て、涙を流さずにはいられなかった。",romaji:"",idText:"Menonton film ini, saya tidak bisa tidak menangis."},{jp:"彼の冗談を聞いて、笑わずにはいられない。",romaji:"",idText:"Mendengar leluconnya, saya tidak bisa menahan tawa."},{jp:"あまりにも不公平で、抗議せずにはいられなかった。",romaji:"",idText:"Terlalu tidak adil sehingga saya tidak bisa tidak melakukan protes."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "章"?',sentencePrompt:'Makna kata "章" (しょう) dalam situasi kerja ini adalah:',options:["bab, bagian (buku); lencana","penghargaan, hadiah kehormatan","rintangan, kendala, gangguan, disabilitas","penumpang (kendaraan)"],correctAnswer:"bab, bagian (buku); lencana",explanation:'Makna yang tepat untuk "章" adalah "bab, bagian (buku); lencana".',diagnosticFeedback:{"penghargaan, hadiah kehormatan":'Salah: Pilihan "penghargaan, hadiah kehormatan" adalah makna dari kata "賞" (しょう), bukan arti kata "章".',"rintangan, kendala, gangguan, disabilitas":'Salah: Pilihan "rintangan, kendala, gangguan, disabilitas" adalah makna dari kata "障害" (しょうがい), bukan arti kata "章".',"penumpang (kendaraan)":'Salah: Pilihan "penumpang (kendaraan)" adalah makna dari kata "乗客" (じょうきゃく), bukan arti kata "章".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"趣味（　　）、もはや仕事になっている。",options:["というより","のように / 〜ように","まるで〜のよう / 〜みたい","その結果"],correctAnswer:"というより",explanation:'Pola 〜というより bermakna "lebih tepatnya ... / daripada disebut ...". Kalimat lengkap: "趣味というより、もはや仕事になっている。".',diagnosticFeedback:{"のように / 〜ように":'Salah: Pola "のように / 〜ように" bermakna "seperti ... / sebagaimana ...", yang tidak sesuai konteks kalimat ini.',"まるで〜のよう / 〜みたい":'Salah: Pola "まるで〜のよう / 〜みたい" bermakna "seperti ... / bagaikan ...", yang tidak sesuai konteks kalimat ini.',その結果:'Salah: Pola "その結果" bermakna "akibatnya / hasilnya", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜というより secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["好きというより、尊敬しています。","好きというよりでした、尊敬しています。","前回説明したように、この問題は複雑です。","料理が嫌いなわけではないが、毎日作る時間がない。"],correctAnswer:"好きというより、尊敬しています。",explanation:'Kalimat yang benar dan alami adalah "好きというより、尊敬しています。" (Daripada disebut suka, lebih tepatnya saya kagum.).',diagnosticFeedback:{"好きというよりでした、尊敬しています。":"Jebakan Konjugasi: Pola 〜というより membutuhkan aturan sambung (N/V/Adj + というより), bukan bentuk ini.","前回説明したように、この問題は複雑です。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜のように / 〜ように（説明）: seperti ... / sebagaimana ...), bukan kaidah 〜というより.","料理が嫌いなわけではないが、毎日作る時間がない。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜というより secara tepat (lebih tepatnya ... / daripada disebut ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["前回説明したように、 この 問題は 複雑です。","この 前回説明したように、 問題は 複雑です。","前回説明したように、 問題は この 複雑です。","複雑です。 前回説明したように、 この 問題は"],correctAnswer:"前回説明したように、 この 問題は 複雑です。",explanation:'Susunan yang benar: "前回説明したように、 この 問題は 複雑です。" (Seperti yang sudah dijelaskan sebelumnya, masalah ini kompleks.).',diagnosticFeedback:{"この 前回説明したように、 問題は 複雑です。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","前回説明したように、 問題は この 複雑です。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","複雑です。 前回説明したように、 この 問題は":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["前回説明したように、","この","問題は","複雑です。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.", saat Sakura menyampaikan arahan: 「なるほど。前回説明したように、この問題は複雑です。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜というより dan 〜のように / 〜ように（説明） dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜というより!",modelAnswer:"はい、Sakuraさん！ 趣味というより、もはや仕事になっている。。",modelAnswerId:"Ya, Sakura! Daripada disebut hobi, itu sudah menjadi pekerjaan..",culturalEtiquette:"Gunakan negasi parsial untuk meluruskan kesalahpahaman klien dengan bahasa diplomatis yang elegan.",skillUnlocked:["Menguasai formulasi pola 〜というより","Mampu menerapkan prinsip koordinasi komunikasi kerja Negasi Parsial, Penyangkalan Total & Pembatasan"]},pocket_summary:{keyFormula:"〜というより (lebih tepatnya ... / daripada disebut ...)",coreWords:["章【しょう】 (bab, bagian (buku); lencana)","賞【しょう】 (penghargaan, hadiah kehormatan)","障害【しょうがい】 (rintangan, kendala, gangguan, disabilitas)","乗客【じょうきゃく】 (penumpang (kendaraan))"],coreWarning:"Menolak pernyataan mitra secara mentah-mentah tanpa awalan diplomatis dapat merusak relasi bisnis.",quickDialogue:"A: ブディさん、章の 状況【じょうきょう】は どうです... → B: はい、Sakuraさん！ 趣味というより、もはや仕..."}},"les-n3-u13-02":{pedagogical_framework:{what:{summary:"Negasi Parsial, Penyangkalan Total & Pembatasan (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ことなく, 〜おかげで, 〜せいで / 〜せいか, 〜そのため（に） dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ことなく dan 〜おかげで secara mandiri.",targetPatterns:["〜ことなく (tanpa ... sama sekali, tidak pernah ...)","〜おかげで (berkat ... / karena ... (hal positif))","〜せいで / 〜せいか (gara-gara ... / akibat ... (hal negatif))","〜そのため（に） (oleh karena itu / untuk itu)"],coreVocabSample:["せいじん","せいねん","せいねんがっぴ","せいひん","せいめい","せきたん","せきゆ","せけん"]},sensei_context:{sceneIntro:"Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ことなく dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Negasi Parsial, Penyangkalan Total & Pembatasan",etiquette:"Gunakan negasi parsial untuk meluruskan kesalahpahaman klien dengan bahasa diplomatis yang elegan.",taboos:"Menolak pernyataan mitra secara mentah-mentah tanpa awalan diplomatis dapat merusak relasi bisnis."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ことなく",moraNote:"Tekankan mora wa-ke pada wake dewa nai secara santun tanpa aksen meninggi di akhir.",soundTip:"Ucapkan 〜ことなく dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ことなく",caseScenario:"Menggunakan 〜ことなく tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ことなく.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ことなく sesuai kaidah.",explanation:"Kaidah koneksi 〜ことなく: V-plain (辞書形) + ことなく."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Negasi Parsial, Penyangkalan Total & Pembatasan (Produksi Aktif & Aplikasi Nyata)",setting:"Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ことなく."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、成人の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、成人の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, seijin no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai orang dewasa? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 彼は一度も休むことなく、働き続けた。。",furigana:"はい、Sakuraさん！ 彼は一度も休むことなく、働き続けた。。",romaji:"Hai, Sakura-san! ことなく de susumete imasu.",idText:"Ya, Sakura! Dia terus bekerja tanpa sekali pun istirahat.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。先生のご指導のおかげで、試験に合格しました。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。先生のご指導のおかげで、試験に合格しました。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Berkat bimbingan guru, saya lulus ujian.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00937",word:"成人",reading:"せいじん",romaji:"seijin",meaning:"orang dewasa",pos:"noun",nuance:"Merujuk pada orang yang sudah mencapai usia dewasa menurut hukum (di Jepang usia 18 tahun). Sering digunakan dalam konteks resmi dan kemasyarakatan seperti 成人式 (upacara kedewasaan). Berbeda dengan 大人 (otona) yang lebih umum dipakai dalam percakapan santai sehari-hari.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"成人【せいじん】を 確認【かくにん】します。",furigana:"成人を 確認します。",romaji:"seijin o kakunin shimasu.",idText:"Memeriksa orang dewasa."}},{id:"vg-n3-00943",word:"青年",reading:"せいねん",romaji:"seinen",meaning:"pemuda, kaum muda",pos:"noun",nuance:"Merujuk pada orang di rentang usia muda (remaja akhir hingga usia dua puluhan). Cenderung bernuansa lebih tertulis atau formal dibandingkan kata 若者 (wakamono). Berbeda dengan 少年 (shounen) yang merujuk pada anak laki-laki usia sekolah dasar hingga menengah pertama.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"青年【せいねん】を 確認【かくにん】します。",furigana:"青年を 確認します。",romaji:"seinen o kakunin shimasu.",idText:"Memeriksa pemuda, kaum muda."}},{id:"vg-n3-00944",word:"生年月日",reading:"せいねんがっぴ",romaji:"seinengappi",meaning:"tanggal lahir lengkap",pos:"noun",nuance:"Istilah formal untuk tanggal, bulan, dan tahun kelahiran secara lengkap pada dokumen legal, pendaftaran dinas, dan kartu tanda pengenal. Berbeda dengan 誕生日 (tanjoubi) yang lebih santai dan sering dipakai dalam konteks perayaan ulang tahun.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"生年月日【せいねんがっぴ】を 確認【かくにん】します。",furigana:"生年月日を 確認します。",romaji:"seinengappi o kakunin shimasu.",idText:"Memeriksa tanggal lahir lengkap."}},{id:"vg-n3-00945",word:"製品",reading:"せいひん",romaji:"seihin",meaning:"produk, barang jadi, barang buatan",pos:"noun",nuance:"Menunjuk pada barang jadi hasil proses manufaktur pabrik yang siap diperdagangkan atau digunakan konsumen. Berbeda dengan 作品 (sakuhin) yang merujuk pada karya seni/kreatif individual, serta berbeda dengan 原料 (genryou, bahan mentah).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"製品【せいひん】を 確認【かくにん】します。",furigana:"製品を 確認します。",romaji:"seihin o kakunin shimasu.",idText:"Memeriksa produk, barang jadi, barang buatan."}},{id:"vg-n3-00946",word:"生命",reading:"せいめい",romaji:"seimei",meaning:"nyawa, kehidupan, jiwa",pos:"noun",nuance:"Merujuk pada daya hidup atau eksistensi biologis makhluk hidup, sering dipakai dalam konteks sains atau formal seperti 生命保険 (asuransi jiwa). Dibandingkan 命 (inochi) yang lebih puitis dan emosional, 生命 cenderung lebih formal dan ilmiah.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"生命【せいめい】を 確認【かくにん】します。",furigana:"生命を 確認します。",romaji:"seimei o kakunin shimasu.",idText:"Memeriksa nyawa, kehidupan, jiwa."}},{id:"vg-n3-00948",word:"石炭",reading:"せきたん",romaji:"sekitan",meaning:"batu bara",pos:"noun",nuance:"Bahan bakar fosil padat berwarna hitam yang ditambang dari dalam perut bumi. Berbeda dengan 木炭 (mokutan, arang kayu biasa) yang terbuat dari pembakaran kayu, serta berbeda dengan 石油 (sekiyu) yang berwujud cair.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"石炭【せきたん】を 確認【かくにん】します。",furigana:"石炭を 確認します。",romaji:"sekitan o kakunin shimasu.",idText:"Memeriksa batu bara."}},{id:"vg-n3-00949",word:"石油",reading:"せきゆ",romaji:"sekiyu",meaning:"minyak bumi, minyak tanah",pos:"noun",nuance:"Bahan bakar fosil cair dari dalam bumi. Di Jepang, dalam percakapan rumah tangga juga sering merujuk pada minyak tanah untuk pemanas ruangan. Berbeda dengan 石炭 (sekitan) yang berupa batu bara padat, dan berbeda dengan 原油 (gen'yu) yang khusus minyak bumi mentah.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"石油【せきゆ】を 確認【かくにん】します。",furigana:"石油を 確認します。",romaji:"sekiyu o kakunin shimasu.",idText:"Memeriksa minyak bumi, minyak tanah."}},{id:"vg-n3-00950",word:"世間",reading:"せけん",romaji:"seken",meaning:"masyarakat umum, dunia sosial, khalayak ramai",pos:"noun",nuance:"Merujuk pada lingkungan sosial dan pandangan orang-orang di sekitar atau khalayak ramai, sering dikaitkan dengan norma sosial dan reputasi (misal 世間の目, tatapan masyarakat). Berbeda dengan 社会 (shakai) yang lebih netral dan struktural secara sosiologis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"世間【せけん】を 確認【かくにん】します。",furigana:"世間を 確認します。",romaji:"seken o kakunin shimasu.",idText:"Memeriksa masyarakat umum, dunia sosial, khalayak ramai."}}],explanations:[{id:"exp-1",grammarId:"gn3-00140",title:"Pola: 〜ことなく",formula:"V-plain (辞書形) + ことなく",meaning:"tanpa ... sama sekali, tidak pernah ...",nuanceNotes:"〜ことなく menyatakan bahwa suatu tindakan dilakukan tanpa pernah melakukan tindakan lain sama sekali. Pola ini bersifat formal dan literari, sering ditemukan dalam teks tertulis atau pidato. Maknanya setara dengan 〜ないで namun dengan nuansa yang lebih tegas dan formal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことなく",idText:"tanpa ... sama sekali, tidak pernah ..."}],examples:[{jp:"彼は一度も休むことなく、働き続けた。",romaji:"",idText:"Dia terus bekerja tanpa sekali pun istirahat."},{jp:"諦めることなく、最後まで頑張った。",romaji:"",idText:"Dia berjuang sampai akhir tanpa menyerah sedikit pun."},{jp:"涙を見せることなく、彼女は笑って別れた。",romaji:"",idText:"Tanpa menunjukkan air mata, dia berpisah sambil tersenyum."}]},{id:"exp-2",grammarId:"gn3-00001",title:"Pola: 〜おかげで",formula:"V/Adj plain / N + の + おかげで",meaning:"berkat ... / karena ... (hal positif)",nuanceNotes:"〜おかげで menyatakan bahwa suatu hasil positif dicapai berkat seseorang atau sesuatu. Selalu digunakan dengan konteks positif.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜おかげで",idText:"berkat ... / karena ... (hal positif)"}],examples:[{jp:"先生のご指導のおかげで、試験に合格しました。",romaji:"",idText:"Berkat bimbingan guru, saya lulus ujian."},{jp:"皆さんの協力のおかげで、プロジェクトが成功しました。",romaji:"",idText:"Berkat kerjasama semua orang, proyek berhasil."},{jp:"薬を飲んだおかげで、熱が下がりました。",romaji:"",idText:"Berkat minum obat, demam turun."}]},{id:"exp-3",grammarId:"gn3-00002",title:"Pola: 〜せいで / 〜せいか",formula:"V/Adj plain / N + の + せいで / せいか",meaning:"gara-gara ... / akibat ... (hal negatif)",nuanceNotes:'〜せいで menyatakan penyebab dari suatu hasil negatif, sering dengan nada menyalahkan. 〜せいか: nada lebih ragu ("mungkin gara-gara...").',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜せいで / 〜せいか",idText:"gara-gara ... / akibat ... (hal negatif)"}],examples:[{jp:"風邪のせいで、仕事を休みました。",romaji:"",idText:"Gara-gara masuk angin, saya tidak masuk kerja."},{jp:"睡眠不足のせいか、集中できない。",romaji:"",idText:"Mungkin gara-gara kurang tidur, saya tidak bisa konsentrasi."},{jp:"彼女のせいで、計画が台無しになった。",romaji:"",idText:"Gara-gara dia, rencana menjadi berantakan."}]},{id:"exp-4",grammarId:"gn3-00003",title:"Pola: 〜そのため（に）",formula:"文1。そのため（に）、文2。",meaning:"oleh karena itu / untuk itu",nuanceNotes:"〜そのため（に） menghubungkan dua kalimat sebagai sebab dan akibat, atau menunjukkan tujuan dari kalimat sebelumnya. Lebih formal dari だから.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜そのため（に）",idText:"oleh karena itu / untuk itu"}],examples:[{jp:"台風が接近している。そのため、学校は休みになった。",romaji:"",idText:"Topan sedang mendekat. Oleh karena itu, sekolah diliburkan."},{jp:"体を強くしたい。そのために、毎日運動している。",romaji:"",idText:"Ingin memperkuat tubuh. Untuk itu, berolahraga setiap hari."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "成人"?',sentencePrompt:'Makna kata "成人" (せいじん) dalam situasi kerja ini adalah:',options:["orang dewasa","pemuda, kaum muda","tanggal lahir lengkap","produk, barang jadi, barang buatan"],correctAnswer:"orang dewasa",explanation:'Makna yang tepat untuk "成人" adalah "orang dewasa".',diagnosticFeedback:{"pemuda, kaum muda":'Salah: Pilihan "pemuda, kaum muda" adalah makna dari kata "青年" (せいねん), bukan arti kata "成人".',"tanggal lahir lengkap":'Salah: Pilihan "tanggal lahir lengkap" adalah makna dari kata "生年月日" (せいねんがっぴ), bukan arti kata "成人".',"produk, barang jadi, barang buatan":'Salah: Pilihan "produk, barang jadi, barang buatan" adalah makna dari kata "製品" (せいひん), bukan arti kata "成人".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"彼は一度も休む（　　）、働き続けた。",options:["ことなく","おかげで","せいで / 〜せいか","その結果"],correctAnswer:"ことなく",explanation:'Pola 〜ことなく bermakna "tanpa ... sama sekali, tidak pernah ...". Kalimat lengkap: "彼は一度も休むことなく、働き続けた。".',diagnosticFeedback:{おかげで:'Salah: Pola "おかげで" bermakna "berkat ... / karena ... (hal positif)", yang tidak sesuai konteks kalimat ini.',"せいで / 〜せいか":'Salah: Pola "せいで / 〜せいか" bermakna "gara-gara ... / akibat ... (hal negatif)", yang tidak sesuai konteks kalimat ini.',その結果:'Salah: Pola "その結果" bermakna "akibatnya / hasilnya", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ことなく secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["諦めることなく、最後まで頑張った。","諦めることなくでした、最後まで頑張った。","先生のご指導のおかげで、試験に合格しました。","料理が嫌いなわけではないが、毎日作る時間がない。"],correctAnswer:"諦めることなく、最後まで頑張った。",explanation:'Kalimat yang benar dan alami adalah "諦めることなく、最後まで頑張った。" (Dia berjuang sampai akhir tanpa menyerah sedikit pun.).',diagnosticFeedback:{"諦めることなくでした、最後まで頑張った。":"Jebakan Konjugasi: Pola 〜ことなく membutuhkan aturan sambung (V-plain (辞書形) + ことなく), bukan bentuk ini.","先生のご指導のおかげで、試験に合格しました。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜おかげで: berkat ... / karena ... (hal positif)), bukan kaidah 〜ことなく.","料理が嫌いなわけではないが、毎日作る時間がない。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ことなく secara tepat (tanpa ... sama sekali, tidak pernah ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["先生のご指導の おかげで 、試験に 合格しました。","おかげで 先生のご指導の 、試験に 合格しました。","先生のご指導の 、試験に おかげで 合格しました。","合格しました。 先生のご指導の おかげで 、試験に"],correctAnswer:"先生のご指導の おかげで 、試験に 合格しました。",explanation:'Susunan yang benar: "先生のご指導の おかげで 、試験に 合格しました。" (Berkat bimbingan guru, saya lulus ujian.).',diagnosticFeedback:{"おかげで 先生のご指導の 、試験に 合格しました。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","先生のご指導の 、試験に おかげで 合格しました。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","合格しました。 先生のご指導の おかげで 、試験に":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["先生のご指導の","おかげで","、試験に","合格しました。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.", saat Sakura menyampaikan arahan: 「なるほど。先生のご指導のおかげで、試験に合格しました。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ことなく dan 〜おかげで secara mandiri.",situation:"Situasi komunikasi profesional di Sesi tanya jawab presentasi bisnis bersama klien rekanan industri otomotif.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ことなく!",modelAnswer:"はい、Sakuraさん！ 彼は一度も休むことなく、働き続けた。。",modelAnswerId:"Ya, Sakura! Dia terus bekerja tanpa sekali pun istirahat..",culturalEtiquette:"Gunakan negasi parsial untuk meluruskan kesalahpahaman klien dengan bahasa diplomatis yang elegan.",skillUnlocked:["Menguasai formulasi pola 〜ことなく","Mampu menerapkan prinsip koordinasi komunikasi kerja Negasi Parsial, Penyangkalan Total & Pembatasan"]},pocket_summary:{keyFormula:"〜ことなく (tanpa ... sama sekali, tidak pernah ...)",coreWords:["成人【せいじん】 (orang dewasa)","青年【せいねん】 (pemuda, kaum muda)","生年月日【せいねんがっぴ】 (tanggal lahir lengkap)","製品【せいひん】 (produk, barang jadi, barang buatan)"],coreWarning:"Menolak pernyataan mitra secara mentah-mentah tanpa awalan diplomatis dapat merusak relasi bisnis.",quickDialogue:"A: ブディさん、成人の 状況【じょうきょう】は どうで... → B: はい、Sakuraさん！ 彼は一度も休むことなく、..."}}},k={"les-n3-u14-01":{pedagogical_framework:{what:{summary:"Perbandingan Relatif, Majas & Derajat Ekstrem (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜その結果, 〜ために (sebab — formal), たとえ〜ても, 〜にしては, 〜わりに（は） dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜その結果 dan 〜ために (sebab — formal) dalam percakapan kerja wajar.",targetPatterns:["〜その結果 (akibatnya / hasilnya)","〜ために (sebab — formal) (karena ... / akibat ... (sebab, formal))","たとえ〜ても (sekalipun ... / bahkan jika ...)","〜にしては (padahal dia ... / untuk ukuran ...)","〜わりに（は） (untuk ... / dibandingkan dengan ...)"],coreVocabSample:["おうじ","おおや","おか","おき","おたがい","おに","おび","おひる"]},sensei_context:{sceneIntro:"Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜その結果 dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Perbandingan Relatif, Majas & Derajat Ekstrem",etiquette:"Pilihlah tolok ukur perbandingan yang adil dan objektif saat mempresentasikan kinerja divisi kerja.",taboos:"Hindari perumpamaan majas (marude) yang berlebihan pada laporan resmi teknis saintifik."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜その結果",moraNote:"Jaga kejelasan mora ku-ra-i dan kurabe-te agar tidak tertelan saat tempo bicara cepat.",soundTip:"Ucapkan 〜その結果 dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜その結果",caseScenario:"Menggunakan 〜その結果 tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜その結果.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜その結果 sesuai kaidah.",explanation:"Kaidah koneksi 〜その結果: 文1。その結果、文2。."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Perbandingan Relatif, Majas & Derajat Ekstrem (Fondasi & Pemahaman Pola)",setting:"Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜その結果."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、王子の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、王子の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, ouji no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai pangeran? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 毎日練習した。その結果、大会で優勝できた。。",furigana:"はい、Sakuraさん！ 毎日練習した。その結果、大会で優勝できた。。",romaji:"Hai, Sakura-san! その結果 de susumete imasu.",idText:"Ya, Sakura! Berlatih setiap hari. Akibatnya, bisa menang di kompetisi.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。地震のために、多くの家が壊れた。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。地震のために、多くの家が壊れた。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Karena gempa, banyak rumah rusak.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01093",word:"王子",reading:"おうじ",romaji:"ouji",meaning:"pangeran",pos:"noun",nuance:"Merujuk pada anak laki-laki dari seorang raja atau kaisar. Sering dipakai dalam dongeng (seperti 星の王子さま) atau sebagai kiasan pria tampan dan memikat (白馬の王子様). Lawan katanya adalah 王女 (oujo, putri raja) atau 姫 (hime).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"王子【おうじ】を 確認【かくにん】します。",furigana:"王子を 確認します。",romaji:"ouji o kakunin shimasu.",idText:"Memeriksa pangeran."}},{id:"vg-n3-01098",word:"大家",reading:"おおや",romaji:"ooya",meaning:"pemilik kontrakan, pemilik kos, induk semang",pos:"noun",nuance:"Sebutan untuk pemilik apartemen, rumah sewa, atau kamar kos, umumnya dipanggil secara akrab 大家さん (ooya-san). Berbeda bila dibaca たいか (taika) yang memiliki arti pakar atau maestro terkemuka di bidang seni atau keilmuan tertentu.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"大家【おおや】を 確認【かくにん】します。",furigana:"大家を 確認します。",romaji:"ooya o kakunin shimasu.",idText:"Memeriksa pemilik kontrakan, pemilik kos, induk semang."}},{id:"vg-n3-01099",word:"丘",reading:"おか",romaji:"oka",meaning:"bukit",pos:"noun",nuance:"Dataran yang lebih tinggi daripada tanah sekelilingnya tetapi tidak setinggi dan seterjal gunung (山, yama). Konturnya biasanya landai dan berumput hijau, cocok untuk piknik atau tempat bersantai.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"丘【おか】を 確認【かくにん】します。",furigana:"丘を 確認します。",romaji:"oka o kakunin shimasu.",idText:"Memeriksa bukit."}},{id:"vg-n3-01100",word:"沖",reading:"おき",romaji:"oki",meaning:"lepas pantai, laut lepas",pos:"noun",nuance:"Area perairan laut yang letaknya jauh dari garis pantai atau pesisir daratan. Lawan katanya adalah 岸 (kishi, tepi pantai/pantai) atau 浜 (hama). Frasa umumnya adalah 沖に出る (berlayar ke laut lepas).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"沖【おき】を 確認【かくにん】します。",furigana:"沖を 確認します。",romaji:"oki o kakunin shimasu.",idText:"Memeriksa lepas pantai, laut lepas."}},{id:"vg-n3-01111",word:"お互い",reading:"おたがい",romaji:"otagai",meaning:"satu sama lain, saling, kedua belah pihak",pos:"noun",nuance:"Menyatakan relasi timbal balik yang setara di antara kedua belah pihak. Sering dipakai dalam bentuk keterangan お互いに (otagai ni, secara saling) atau ungkapan simpati dan kerendahan hati お互い様 (otagaisama, kita berdua sama-sama / saling membutuhkan). Tidak dapat dipakai untuk aksi searah.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"お互い【おたがい】を 確認【かくにん】します。",furigana:"お互いを 確認します。",romaji:"otagai o kakunin shimasu.",idText:"Memeriksa satu sama lain, saling, kedua belah pihak."}},{id:"vg-n3-01113",word:"鬼",reading:"おに",romaji:"oni",meaning:"iblis, raksasa bertanduk, penjaga (dalam permainan)",pos:"noun",nuance:"Berbeda dengan 悪魔 (akuma) yang berasal dari konsep barat, 鬼 adalah makhluk mitologi khas Jepang bertanduk dengan gada berduri, melambangkan kejahatan atau watak bengis. Dalam permainan anak-anak seperti かくれんぼ atau 鬼ごっこ, 鬼 biasanya merujuk pada peran penjaga yang mengejar pemain lain.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"鬼【おに】を 確認【かくにん】します。",furigana:"鬼を 確認します。",romaji:"oni o kakunin shimasu.",idText:"Memeriksa iblis, raksasa bertanduk, penjaga (dalam permainan)."}},{id:"vg-n3-01114",word:"帯",reading:"おび",romaji:"obi",meaning:"sabuk kimono, obi, selempang sampul buku",pos:"noun",nuance:"Berbeda dengan ベルト (beruto) yang merupakan ikat pinggang gaya barat, 帯 secara khusus digunakan untuk sabuk kain lebar tradisional pelengkap kimono atau yukata. Selain pakaian, dalam industri buku Jepang kata ini juga sering digunakan untuk menyebut pita selempang promosi pada sampul buku baru.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"帯【おび】を 確認【かくにん】します。",furigana:"帯を 確認します。",romaji:"obi o kakunin shimasu.",idText:"Memeriksa sabuk kimono, obi, selempang sampul buku."}},{id:"vg-n3-01115",word:"お昼",reading:"おひる",romaji:"ohiru",meaning:"siang hari, makan siang",pos:"noun",nuance:"Bentuk sopan dan akrab dari 昼 (hiru). Berbeda dengan 昼食 (chuushoku) atau ランチ (ranchi) yang lebih formal, kata ini lebih sering digunakan dalam percakapan sehari-hari untuk menyebut makan siang (お昼ご飯 / お昼を食べる) ataupun istirahat siang (お昼休み).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"お昼【おひる】を 確認【かくにん】します。",furigana:"お昼を 確認します。",romaji:"ohiru o kakunin shimasu.",idText:"Memeriksa siang hari, makan siang."}}],explanations:[{id:"exp-1",grammarId:"gn3-00004",title:"Pola: 〜その結果",formula:"文1。その結果、文2。",meaning:"akibatnya / hasilnya",nuanceNotes:"〜その結果 menghubungkan kalimat sebab dengan akibat yang merupakan hasil konkret.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜その結果",idText:"akibatnya / hasilnya"}],examples:[{jp:"毎日練習した。その結果、大会で優勝できた。",romaji:"",idText:"Berlatih setiap hari. Akibatnya, bisa menang di kompetisi."},{jp:"無理をしすぎた。その結果、体を壊した。",romaji:"",idText:"Terlalu memaksakan diri. Hasilnya, jatuh sakit."}]},{id:"exp-2",grammarId:"gn3-00006",title:"Pola: 〜ために (sebab — formal)",formula:"Vた / N + の + ために",meaning:"karena ... / akibat ... (sebab, formal)",nuanceNotes:"〜ために (sebab) menyatakan penyebab dari suatu akibat dalam konteks formal atau tulisan. Berbeda dari ために tujuan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ために (sebab — formal)",idText:"karena ... / akibat ... (sebab, formal)"}],examples:[{jp:"地震のために、多くの家が壊れた。",romaji:"",idText:"Karena gempa, banyak rumah rusak."},{jp:"交通事故のために、道路が渋滞している。",romaji:"",idText:"Karena kecelakaan lalu lintas, jalan macet."}]},{id:"exp-3",grammarId:"gn3-00018",title:"Pola: たとえ〜ても",formula:"たとえ + V/Adj + ても",meaning:"sekalipun ... / bahkan jika ...",nuanceNotes:'たとえ〜ても memperkuat konsesi: "sekalipun", "bahkan jika X, Y tetap berlaku". Lebih tegas dari 〜ても biasa.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"たとえ〜ても",idText:"sekalipun ... / bahkan jika ..."}],examples:[{jp:"たとえ失敗しても、諦めません。",romaji:"",idText:"Sekalipun gagal, saya tidak akan menyerah."},{jp:"たとえ難しくても、やってみる価値があります。",romaji:"",idText:"Bahkan jika sulit, ada nilainya untuk dicoba."}]},{id:"exp-4",grammarId:"gn3-00019",title:"Pola: 〜にしては",formula:"N / Vる + にしては",meaning:"padahal dia ... / untuk ukuran ...",nuanceNotes:'〜にしては menyatakan bahwa suatu keadaan di luar ekspektasi berdasarkan kategori atau kondisi tertentu: "untuk ukuran...", "padahal...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜にしては",idText:"padahal dia ... / untuk ukuran ..."}],examples:[{jp:"子どもにしては、難しい本を読んでいる。",romaji:"",idText:"Untuk ukuran anak-anak, dia membaca buku yang sulit."},{jp:"初めてにしては、よくできました。",romaji:"",idText:"Untuk pertama kali, ini sudah sangat baik."}]},{id:"exp-5",grammarId:"gn3-00020",title:"Pola: 〜わりに（は）",formula:"V/Adj plain / N + の + わりに（は）",meaning:"untuk ... / dibandingkan dengan ...",nuanceNotes:'〜わりに（は） menyatakan bahwa suatu kondisi tidak sesuai dengan yang diharapkan dari keadaan tersebut: "untuk...", "ternyata lebih... dari yang seharusnya".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜わりに（は）",idText:"untuk ... / dibandingkan dengan ..."}],examples:[{jp:"値段のわりに、質がいいですね。",romaji:"",idText:"Untuk harganya, kualitasnya bagus ya."},{jp:"練習したわりには、あまり上手くない。",romaji:"",idText:"Padahal sudah berlatih, tapi tidak begitu mahir."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "王子"?',sentencePrompt:'Makna kata "王子" (おうじ) dalam situasi kerja ini adalah:',options:["pangeran","pemilik kontrakan, pemilik kos, induk semang","bukit","lepas pantai, laut lepas"],correctAnswer:"pangeran",explanation:'Makna yang tepat untuk "王子" adalah "pangeran".',diagnosticFeedback:{"pemilik kontrakan, pemilik kos, induk semang":'Salah: Pilihan "pemilik kontrakan, pemilik kos, induk semang" adalah makna dari kata "大家" (おおや), bukan arti kata "王子".',bukit:'Salah: Pilihan "bukit" adalah makna dari kata "丘" (おか), bukan arti kata "王子".',"lepas pantai, laut lepas":'Salah: Pilihan "lepas pantai, laut lepas" adalah makna dari kata "沖" (おき), bukan arti kata "王子".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"毎日練習した。（　　）、大会で優勝できた。",options:["その結果","ために (sebab — formal)","たとえ〜ても","かわりに"],correctAnswer:"その結果",explanation:'Pola 〜その結果 bermakna "akibatnya / hasilnya". Kalimat lengkap: "毎日練習した。その結果、大会で優勝できた。".',diagnosticFeedback:{"ために (sebab — formal)":'Salah: Pola "ために (sebab — formal)" bermakna "karena ... / akibat ... (sebab, formal)", yang tidak sesuai konteks kalimat ini.',"たとえ〜ても":'Salah: Pola "たとえ〜ても" bermakna "sekalipun ... / bahkan jika ...", yang tidak sesuai konteks kalimat ini.',かわりに:'Salah: Pola "かわりに" bermakna "sebagai gantinya / sebagai imbalannya", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜その結果 secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["無理をしすぎた。その結果、体を壊した。","無理をしすぎた。その結果でした、体を壊した。","地震のために、多くの家が壊れた。","この仕事は大変な一方で、やりがいもあります。"],correctAnswer:"無理をしすぎた。その結果、体を壊した。",explanation:'Kalimat yang benar dan alami adalah "無理をしすぎた。その結果、体を壊した。" (Terlalu memaksakan diri. Hasilnya, jatuh sakit.).',diagnosticFeedback:{"無理をしすぎた。その結果でした、体を壊した。":"Jebakan Konjugasi: Pola 〜その結果 membutuhkan aturan sambung (文1。その結果、文2。), bukan bentuk ini.","地震のために、多くの家が壊れた。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ために (sebab — formal): karena ... / akibat ... (sebab, formal)), bukan kaidah 〜その結果.","この仕事は大変な一方で、やりがいもあります。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜その結果 secara tepat (akibatnya / hasilnya)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["地震の ために、 多くの家が 壊れた。","ために、 地震の 多くの家が 壊れた。","地震の 多くの家が ために、 壊れた。","壊れた。 地震の ために、 多くの家が"],correctAnswer:"地震の ために、 多くの家が 壊れた。",explanation:'Susunan yang benar: "地震の ために、 多くの家が 壊れた。" (Karena gempa, banyak rumah rusak.).',diagnosticFeedback:{"ために、 地震の 多くの家が 壊れた。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","地震の 多くの家が ために、 壊れた。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","壊れた。 地震の ために、 多くの家が":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["地震の","ために、","多くの家が","壊れた。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.", saat Sakura menyampaikan arahan: 「なるほど。地震のために、多くの家が壊れた。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜その結果 dan 〜ために (sebab — formal) dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜その結果!",modelAnswer:"はい、Sakuraさん！ 毎日練習した。その結果、大会で優勝できた。。",modelAnswerId:"Ya, Sakura! Berlatih setiap hari. Akibatnya, bisa menang di kompetisi..",culturalEtiquette:"Pilihlah tolok ukur perbandingan yang adil dan objektif saat mempresentasikan kinerja divisi kerja.",skillUnlocked:["Menguasai formulasi pola 〜その結果","Mampu menerapkan prinsip koordinasi komunikasi kerja Perbandingan Relatif, Majas & Derajat Ekstrem"]},pocket_summary:{keyFormula:"〜その結果 (akibatnya / hasilnya)",coreWords:["王子【おうじ】 (pangeran)","大家【おおや】 (pemilik kontrakan, pemilik kos, induk semang)","丘【おか】 (bukit)","沖【おき】 (lepas pantai, laut lepas)"],coreWarning:"Hindari perumpamaan majas (marude) yang berlebihan pada laporan resmi teknis saintifik.",quickDialogue:"A: ブディさん、王子の 状況【じょうきょう】は どうで... → B: はい、Sakuraさん！ 毎日練習した。その結果、..."}},"les-n3-u14-02":{pedagogical_framework:{what:{summary:"Perbandingan Relatif, Majas & Derajat Ekstrem (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜くせに, 〜ものの, 〜にしても, 〜ことは〜が / けど dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜くせに dan 〜ものの secara mandiri.",targetPatterns:["〜くせに (padahal ... / meskipun (dengan nada kesal))","〜ものの (meskipun ... / walaupun ... (tapi))","〜にしても (meskipun begitu / bahkan jika ... pun)","〜ことは〜が / けど (... memang ... tapi / mengakui tapi ...)"],coreVocabSample:["から","がら","かん","かん","かんがえ","かんきゃく","かんじ","かんじゃ"]},sensei_context:{sceneIntro:"Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜くせに dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Perbandingan Relatif, Majas & Derajat Ekstrem",etiquette:"Pilihlah tolok ukur perbandingan yang adil dan objektif saat mempresentasikan kinerja divisi kerja.",taboos:"Hindari perumpamaan majas (marude) yang berlebihan pada laporan resmi teknis saintifik."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜くせに",moraNote:"Jaga kejelasan mora ku-ra-i dan kurabe-te agar tidak tertelan saat tempo bicara cepat.",soundTip:"Ucapkan 〜くせに dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜くせに",caseScenario:"Menggunakan 〜くせに tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜くせに.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜くせに sesuai kaidah.",explanation:"Kaidah koneksi 〜くせに: V/Adj plain / N + の + くせに."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Perbandingan Relatif, Majas & Derajat Ekstrem (Produksi Aktif & Aplikasi Nyata)",setting:"Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.",narrative:"Budi dan Sakura berkoordinasi mengenai alur operasional kerja menggunakan pola 〜くせに."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"ブディさん、殻の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、殻の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, kara no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai cangkang, kulit pelindung, tempurung? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Sakuraさん！ 知らないくせに、知ったかぶりをしている。。",furigana:"はい、Sakuraさん！ 知らないくせに、知ったかぶりをしている。。",romaji:"Hai, Sakura-san! くせに de susumete imasu.",idText:"Ya, Sakura! Padahal tidak tahu, pura-pura tahu.."},{id:"d3",speaker:"Sakura",speakerRole:"Konsultan & Mentor",avatar:"👩‍🏫",jp:"なるほど。日本語を勉強したものの、なかなか上達しない。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。日本語を勉強したものの、なかなか上達しない。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Meskipun sudah belajar bahasa Jepang, sulit sekali untuk maju.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01213",word:"殻",reading:"から",romaji:"kara",meaning:"cangkang, kulit pelindung, tempurung",pos:"noun",nuance:"Lapisan luar yang keras atau kaku pada hewan (kerang, penyu), telur, atau biji-bijian/kacang (卵の殻 kulit telur, 貝殻 cangkang kerang). Secara metaforis sering dipakai dalam frasa 自分の殻に閉じこもる (menutup diri dari dunia luar) atau 殻を破る (keluar dari zona nyaman).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"殻【から】を 確認【かくにん】します。",furigana:"殻を 確認します。",romaji:"kara o kakunin shimasu.",idText:"Memeriksa cangkang, kulit pelindung, tempurung."}},{id:"vg-n3-01214",word:"柄",reading:"がら",romaji:"gara",meaning:"motif, corak; perawakan, pembawaan diri",pos:"noun",nuance:"Memiliki makna: (1) Corak atau motif visual pada kain pakaian atau perabotan (花柄 motif bunga, しま柄 motif garis). (2) Pembawaan perangai atau watak seseorang, seperti dalam frasa 柄が悪い (berperangai kasar/preman) atau 柄にもない (tidak sesuai karakternya).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"柄【がら】を 確認【かくにん】します。",furigana:"柄を 確認します。",romaji:"gara o kakunin shimasu.",idText:"Memeriksa motif, corak; perawakan, pembawaan diri."}},{id:"vg-n3-01218",word:"缶",reading:"かん",romaji:"kan",meaning:"kaleng",pos:"noun",nuance:"Wadah logam kedap udara untuk minuman atau makanan (misal 缶コーヒー kopi kaleng, 缶詰 makanan kaleng, 空き缶 kaleng kosong). Sering dijumpai dalam aturan tata cara pembuangan sampah rumah tangga di Jepang (缶・ビン).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"缶【かん】を 確認【かくにん】します。",furigana:"缶を 確認します。",romaji:"kan o kakunin shimasu.",idText:"Memeriksa kaleng."}},{id:"vg-n3-01219",word:"勘",reading:"かん",romaji:"kan",meaning:"intuisi, firasat, kepekaan naluri, indra keenam",pos:"noun",nuance:"Perasaan naluriah atau penilaian kilat yang didasarkan pada kepekaan batin tanpa proses penalaran logis panjang. Pola umum: 勘が鋭い (intuisinya tajam), 勘が働く (firasatnya bekerja), 勘が外れる (tebakannya meleset), 勘違い (salah paham).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"勘【かん】を 確認【かくにん】します。",furigana:"勘を 確認します。",romaji:"kan o kakunin shimasu.",idText:"Memeriksa intuisi, firasat, kepekaan naluri, indra keenam."}},{id:"vg-n3-01220",word:"考え",reading:"かんがえ",romaji:"kangae",meaning:"pemikiran, pendapat, gagasan, ide, pertimbangan",pos:"noun",nuance:"Bentuk nomina dari kata kerja 考える (kangaeru). Merujuk pada isi benak, opini, rencana pertimbangan, atau gagasan yang dipikirkan seseorang. Pola umum: 考えがある (punya ide/rencana), 考え直す (meninjau kembali).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"考え【かんがえ】を 確認【かくにん】します。",furigana:"考えを 確認します。",romaji:"kangae o kakunin shimasu.",idText:"Memeriksa pemikiran, pendapat, gagasan, ide, pertimbangan."}},{id:"vg-n3-01221",word:"観客",reading:"かんきゃく",romaji:"kankyaku",meaning:"penonton, hadirin",pos:"noun",nuance:"Orang-orang yang hadir menyaksikan secara visual suatu pertunjukan seni teater, film di bioskop, atau laga olahraga. Berbeda dengan 聴衆 (choushuu) yang fokusnya menyimak pendengaran (konser musik, pidato) atau 読者 (dokusha - pembaca).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"観客【かんきゃく】を 確認【かくにん】します。",furigana:"観客を 確認します。",romaji:"kankyaku o kakunin shimasu.",idText:"Memeriksa penonton, hadirin."}},{id:"vg-n3-01224",word:"感じ",reading:"かんじ",romaji:"kanji",meaning:"perasaan, kesan, nuansa, suasana rasa",pos:"noun",nuance:"Bentuk nomina dari kata kerja 感じる (kanjiru). Menunjukkan kesan atau nuansa yang dirasakan panca indra atau suasana batin (seperti 感じがいい kesan ramah/menyenangkan; 嫌な感じ firasat tidak enak; ~という感じ nuansa seperti...). Berbeda dengan 感情 (kanjou) yang merujuk pada emosi psikologis formal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"感じ【かんじ】を 確認【かくにん】します。",furigana:"感じを 確認します。",romaji:"kanji o kakunin shimasu.",idText:"Memeriksa perasaan, kesan, nuansa, suasana rasa."}},{id:"vg-n3-01225",word:"患者",reading:"かんじゃ",romaji:"kanja",meaning:"pasien, orang yang dirawat",pos:"noun",nuance:"Orang yang menderita gangguan kesehatan atau luka dan sedang menerima pemeriksaan atau perawatan medis di klinik atau rumah sakit. Kanji 患 berarti sakit/menderita dan 者 berarti orang. Berbeda dengan 病人 (byounin) yang merujuk pada orang sakit secara umum tanpa spesifik dalam perawatan medis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"患者【かんじゃ】を 確認【かくにん】します。",furigana:"患者を 確認します。",romaji:"kanja o kakunin shimasu.",idText:"Memeriksa pasien, orang yang dirawat."}}],explanations:[{id:"exp-1",grammarId:"gn3-00021",title:"Pola: 〜くせに",formula:"V/Adj plain / N + の + くせに",meaning:"padahal ... / meskipun (dengan nada kesal)",nuanceNotes:'〜くせに menyatakan kontras dengan nada tidak puas, kesal, atau mengkritik. "Padahal..., tapi..." dengan emosi negatif.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜くせに",idText:"padahal ... / meskipun (dengan nada kesal)"}],examples:[{jp:"知らないくせに、知ったかぶりをしている。",romaji:"",idText:"Padahal tidak tahu, pura-pura tahu."},{jp:"下手なくせに、人の批判ばかりする。",romaji:"",idText:"Padahal tidak mahir, hanya mengkritik orang saja."}]},{id:"exp-2",grammarId:"gn3-00022",title:"Pola: 〜ものの",formula:"V/Adj plain / N + ではある + ものの",meaning:"meskipun ... / walaupun ... (tapi)",nuanceNotes:"〜ものの menyatakan konsesi: meskipun kondisi pertama berlaku, akibat yang diharapkan tidak terjadi atau ada hal lain yang menghalangi. Lebih formal dari けど.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ものの",idText:"meskipun ... / walaupun ... (tapi)"}],examples:[{jp:"日本語を勉強したものの、なかなか上達しない。",romaji:"",idText:"Meskipun sudah belajar bahasa Jepang, sulit sekali untuk maju."},{jp:"行きたいものの、時間がない。",romaji:"",idText:"Meskipun ingin pergi, tidak ada waktu."}]},{id:"exp-3",grammarId:"gn3-00023",title:"Pola: 〜にしても",formula:"V/Adj plain / N + にしても",meaning:"meskipun begitu / bahkan jika ... pun",nuanceNotes:"〜にしても menyatakan bahwa meskipun suatu kondisi berlaku, ada pernyataan tambahan yang juga relevan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜にしても",idText:"meskipun begitu / bahkan jika ... pun"}],examples:[{jp:"忙しいにしても、少しくらい連絡してほしい。",romaji:"",idText:"Meskipun sibuk, setidaknya tolong beri kabar."},{jp:"安いにしても、もう少し品質を上げてほしい。",romaji:"",idText:"Meskipun murah, tolong tingkatkan sedikit kualitasnya."}]},{id:"exp-4",grammarId:"gn3-00024",title:"Pola: 〜ことは〜が / けど",formula:"V + ことは + V + が / けど",meaning:"... memang ... tapi / mengakui tapi ...",nuanceNotes:"〜ことは〜が mengakui suatu kenyataan sebelum menyatakan kondisi yang membatasi atau kontras.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことは〜が / けど",idText:"... memang ... tapi / mengakui tapi ..."}],examples:[{jp:"行くことは行くが、あまり乗り気じゃない。",romaji:"",idText:"Pergi memang pergi, tapi tidak begitu bersemangat."},{jp:"分かることは分かるけど、難しいな。",romaji:"",idText:"Mengerti memang mengerti, tapi susah juga ya."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "殻"?',sentencePrompt:'Makna kata "殻" (から) dalam situasi kerja ini adalah:',options:["cangkang, kulit pelindung, tempurung","motif, corak; perawakan, pembawaan diri","kaleng","intuisi, firasat, kepekaan naluri, indra keenam"],correctAnswer:"cangkang, kulit pelindung, tempurung",explanation:'Makna yang tepat untuk "殻" adalah "cangkang, kulit pelindung, tempurung".',diagnosticFeedback:{"motif, corak; perawakan, pembawaan diri":'Salah: Pilihan "motif, corak; perawakan, pembawaan diri" adalah makna dari kata "柄" (がら), bukan arti kata "殻".',kaleng:'Salah: Pilihan "kaleng" adalah makna dari kata "缶" (かん), bukan arti kata "殻".',"intuisi, firasat, kepekaan naluri, indra keenam":'Salah: Pilihan "intuisi, firasat, kepekaan naluri, indra keenam" adalah makna dari kata "勘" (かん), bukan arti kata "殻".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"知らない（　　）、知ったかぶりをしている。",options:["くせに","ものの","にしても","かわりに"],correctAnswer:"くせに",explanation:'Pola 〜くせに bermakna "padahal ... / meskipun (dengan nada kesal)". Kalimat lengkap: "知らないくせに、知ったかぶりをしている。".',diagnosticFeedback:{ものの:'Salah: Pola "ものの" bermakna "meskipun ... / walaupun ... (tapi)", yang tidak sesuai konteks kalimat ini.',にしても:'Salah: Pola "にしても" bermakna "meskipun begitu / bahkan jika ... pun", yang tidak sesuai konteks kalimat ini.',かわりに:'Salah: Pola "かわりに" bermakna "sebagai gantinya / sebagai imbalannya", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜くせに secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["下手なくせに、人の批判ばかりする。","下手なくせにでした、人の批判ばかりする。","日本語を勉強したものの、なかなか上達しない。","この仕事は大変な一方で、やりがいもあります。"],correctAnswer:"下手なくせに、人の批判ばかりする。",explanation:'Kalimat yang benar dan alami adalah "下手なくせに、人の批判ばかりする。" (Padahal tidak mahir, hanya mengkritik orang saja.).',diagnosticFeedback:{"下手なくせにでした、人の批判ばかりする。":"Jebakan Konjugasi: Pola 〜くせに membutuhkan aturan sambung (V/Adj plain / N + の + くせに), bukan bentuk ini.","日本語を勉強したものの、なかなか上達しない。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ものの: meskipun ... / walaupun ... (tapi)), bukan kaidah 〜くせに.","この仕事は大変な一方で、やりがいもあります。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜くせに secara tepat (padahal ... / meskipun (dengan nada kesal))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["日本語を 勉強した ものの、なかなか 上達しない。","勉強した 日本語を ものの、なかなか 上達しない。","日本語を ものの、なかなか 勉強した 上達しない。","上達しない。 日本語を 勉強した ものの、なかなか"],correctAnswer:"日本語を 勉強した ものの、なかなか 上達しない。",explanation:'Susunan yang benar: "日本語を 勉強した ものの、なかなか 上達しない。" (Meskipun sudah belajar bahasa Jepang, sulit sekali untuk maju.).',diagnosticFeedback:{"勉強した 日本語を ものの、なかなか 上達しない。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","日本語を ものの、なかなか 勉強した 上達しない。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","上達しない。 日本語を 勉強した ものの、なかなか":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["日本語を","勉強した","ものの、なかなか","上達しない。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.", saat Sakura menyampaikan arahan: 「なるほど。日本語を勉強したものの、なかなか上達しない。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜くせに dan 〜ものの secara mandiri.",situation:"Situasi komunikasi profesional di Presentasi laporan efisiensi energi antara mesin generasi lama dan generasi baru di pabrik.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜くせに!",modelAnswer:"はい、Sakuraさん！ 知らないくせに、知ったかぶりをしている。。",modelAnswerId:"Ya, Sakura! Padahal tidak tahu, pura-pura tahu..",culturalEtiquette:"Pilihlah tolok ukur perbandingan yang adil dan objektif saat mempresentasikan kinerja divisi kerja.",skillUnlocked:["Menguasai formulasi pola 〜くせに","Mampu menerapkan prinsip koordinasi komunikasi kerja Perbandingan Relatif, Majas & Derajat Ekstrem"]},pocket_summary:{keyFormula:"〜くせに (padahal ... / meskipun (dengan nada kesal))",coreWords:["殻【から】 (cangkang, kulit pelindung, tempurung)","柄【がら】 (motif, corak; perawakan, pembawaan diri)","缶【かん】 (kaleng)","勘【かん】 (intuisi, firasat, kepekaan naluri, indra keenam)"],coreWarning:"Hindari perumpamaan majas (marude) yang berlebihan pada laporan resmi teknis saintifik.",quickDialogue:"A: ブディさん、殻の 状況【じょうきょう】は どうです... → B: はい、Sakuraさん！ 知らないくせに、知ったか..."}}};export{r as a,t as b,i as c,e as d,n as e,a as f,k as u};
